'use strict';

/**
 * VENDOR-EMBUTIDO.JS — Conteúdo dos arquivos "motor" (tela inicial + tela de
 * estudo) embutido como texto, pra o export funcionar mesmo com index.html
 * aberto direto (file://), onde fetch() de arquivos locais é bloqueado pelo
 * navegador. Gerado a partir de vendor/estudo/ por gerar-vendor-embutido.js —
 * não editar à mão; se mudar algo em vendor/estudo/, rode esse script de novo.
 */
const VENDOR_ARQUIVOS = {
  "index.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>{{APP_TITULO}}</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"css/inicio.css\">\n<link rel=\"icon\" href=\"{{APP_FAVICON_HREF}}\">\n<meta name=\"theme-color\" content=\"{{APP_COR}}\">\n</head>\n<body>\n\n<div class=\"app-wrapper\">\n\n  <header class=\"header\">\n    <div class=\"header-left\">\n      <div class=\"logo\">{{APP_LOGO_HTML}}</div>\n      <div class=\"header-title\">\n        <h1>{{APP_TITULO}}</h1>\n        <p>{{APP_SUBTITULO}}</p>\n      </div>\n    </div>\n  </header>\n\n  <div class=\"view-inicio\" id=\"viewInicio\">\n    <div id=\"etapasWrap\"></div>\n  </div>\n\n  <div class=\"view-erros\" id=\"viewErros\" style=\"display:none\">\n    <div class=\"erros-header\">\n      <h2>Cadernos</h2>\n      <p>Suas questões erradas, aulas favoritas e telas marcadas para revisão.</p>\n    </div>\n    <div class=\"cadernos-tabs\" id=\"cadernosTabs\">\n      <button type=\"button\" class=\"caderno-tab active\" data-tab=\"erros\">Erros</button>\n      <button type=\"button\" class=\"caderno-tab\" data-tab=\"favoritos\">Favoritos</button>\n      <button type=\"button\" class=\"caderno-tab\" data-tab=\"revisao\">Revisão</button>\n    </div>\n    <div class=\"cadernos-subtabs\" id=\"cadernosSubtabs\">\n      <button type=\"button\" class=\"caderno-subtab active\" data-subtab=\"aula\">Por aula</button>\n      <button type=\"button\" class=\"caderno-subtab\" data-subtab=\"geral\">Geral</button>\n    </div>\n    <div class=\"erros-list\" id=\"errosList\"></div>\n  </div>\n\n  <div class=\"view-placeholder\" id=\"viewDesempenho\" style=\"display:none\">\n    <h2>Desempenho</h2>\n    <p>Insígnias por nível aparecem aqui em uma próxima versão.</p>\n  </div>\n\n  <div class=\"view-niveis\" id=\"viewNiveis\" style=\"display:none\">\n    <div class=\"erros-header\">\n      <h2>Estudos</h2>\n      <p>Cada nível reúne várias etapas — conclua todas as aulas para desbloquear o próximo.</p>\n    </div>\n    <div class=\"niveis-lista\" id=\"niveisLista\"></div>\n  </div>\n\n  <nav class=\"bottom-nav\">\n    <div class=\"nav-item active\" data-view=\"inicio\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 9.5 12 3l9 6.5V20a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z\"></path></svg>\n      <span>Início</span>\n    </div>\n    <div class=\"nav-item\" data-view=\"erros\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"></path><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"></path></svg>\n      <span>Cadernos</span>\n    </div>\n    <div class=\"nav-item\" data-view=\"desempenho\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg>\n      <span>Desempenho</span>\n    </div>\n    <div class=\"nav-item\" data-view=\"niveis\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 2 7 12 12 22 7 12 2\"></polygon><polyline points=\"2 17 12 22 22 17\"></polyline><polyline points=\"2 12 12 17 22 12\"></polyline></svg>\n      <span>Estudos</span>\n    </div>\n  </nav>\n\n</div>\n\n<script src=\"js/progresso.mjs\"></script>\n<script src=\"js/data/modulos.mjs\"></script>\n<script src=\"js/inicio.mjs\"></script>\n<script src=\"js/cadernos.mjs\"></script>\n<script src=\"js/niveis.mjs\"></script>\n</body>\n</html>\n",
  "css/inicio.css": "/* INICIO.CSS — Tela inicial do projeto exportado (trilha de ciclos/etapas/\n   aulas), com as mesmas cores/estrutura de estudos/css/style.css.\n   Cor de marca em variáveis — o export injeta um :root{} novo no final do\n   arquivo com a cor escolhida no Construtor de Aulas (ver js/export.js). */\n:root {\n  --cor-primaria: #5B2BCB;\n  --cor-primaria-rgb: 91,43,203;\n  --cor-primaria-escura: #4a22a8;\n  --cor-gradiente-1: #8E5CF5;\n  --cor-gradiente-2: #6D2EE8;\n  --cor-clara: #f0eaff;\n  --cor-borda-clara: #e9dffb;\n  --cor-borda-media: #d4c4f0;\n  --cor-hover-fundo: #faf7ff;\n}\n* { margin: 0; padding: 0; box-sizing: border-box; font-family: 'Inter', sans-serif; }\nbody { background: #f4f0ff; min-height: 100vh; }\n\n.app-wrapper {\n  max-width: 700px; width: 100%; margin: 0 auto; background: #f4f0ff;\n  min-height: 100vh; display: flex; flex-direction: column; padding-bottom: 100px;\n}\n\n/* HEADER */\n.header {\n  background: #fff; padding: 16px 20px; display: flex; align-items: center;\n  justify-content: space-between; gap: 12px; box-shadow: 0 2px 10px rgba(var(--cor-primaria-rgb),0.06);\n  position: sticky; top: 0; z-index: 10;\n}\n.header-left { display: flex; align-items: center; gap: 12px; }\n.header .logo {\n  width: 42px; height: 42px; border-radius: 12px; overflow: hidden;\n  background: linear-gradient(135deg, var(--cor-gradiente-1) 0%, var(--cor-gradiente-2) 100%);\n  display: grid; place-items: center; color: #fff; flex-shrink: 0;\n}\n.header-title h1 { font-size: 17px; font-weight: 700; color: #1a1a2e; }\n.header-title p { font-size: 12.5px; color: #6b7280; margin-top: 1px; }\n\n/* HERO CARD */\n.etapa-view { padding: 16px 16px 4px; }\n.hero-card {\n  background: linear-gradient(135deg, var(--cor-clara) 0%, var(--cor-borda-clara) 100%);\n  border-radius: 24px; padding: 24px 20px 28px; cursor: pointer;\n  box-shadow: 0 4px 20px rgba(var(--cor-primaria-rgb),0.08);\n  transition: box-shadow .2s, padding .25s;\n}\n.hero-card:hover { box-shadow: 0 6px 24px rgba(var(--cor-primaria-rgb),0.12); }\n.hero-card.collapsed { padding: 20px 20px; }\n\n.nivel-selector {\n  display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--cor-primaria);\n  font-size: 15px; font-weight: 600; margin-bottom: 10px; cursor: pointer;\n}\n.nivel-selector svg { width: 14px; height: 14px; transition: transform .2s; }\n.nivel-selector.collapsed svg { transform: rotate(180deg); }\n\n.hero-content { overflow: hidden; max-height: 200px; opacity: 1; transition: max-height .25s ease, opacity .2s ease; }\n.hero-content.collapsed { max-height: 0; opacity: 0; }\n.hero-materia { display: block; text-align: center; font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: .6px; color: #7c5cd6; margin-bottom: 4px; }\n.hero-title { text-align: center; font-size: 21px; font-weight: 700; color: #1a1a2e; margin-bottom: 14px; }\n\n.progress-segments { display: flex; gap: 6px; }\n.progress-segments .segment { flex: 1; height: 10px; border-radius: 6px; background: rgba(var(--cor-primaria-rgb),0.15); }\n.progress-segments .segment.filled { background: var(--cor-primaria); }\n.hero-card.etapa-completa .segment.filled { box-shadow: 0 0 10px rgba(var(--cor-primaria-rgb),0.7); }\n\n/* PATH */\n.path-container { position: relative; padding: 24px 8px 8px; overflow: hidden; max-height: 4000px; transition: max-height .25s ease, padding .25s; }\n.path-container.collapsed { max-height: 0; padding-top: 0; padding-bottom: 0; }\n.path-line, .path-line-lit {\n  position: absolute; left: 50%; top: 24px; bottom: 8px; width: 3px; transform: translateX(-50%);\n  border-radius: 2px;\n}\n.path-line { background: repeating-linear-gradient(to bottom, var(--cor-borda-clara) 0 6px, transparent 6px 12px); }\n.path-line-lit { background: #FFD700; height: 0; bottom: auto; transition: height .3s ease; }\n\n.aula-node { position: relative; display: flex; flex-direction: column; align-items: center; padding: 10px 0 26px; text-align: center; }\n.aula-node.locked { opacity: .6; }\n\n.stars { display: flex; gap: 3px; margin-bottom: 6px; }\n.star { font-size: 18px; color: #e5e7eb; filter: drop-shadow(0 2px 4px rgba(255,215,0,0.3)); }\n\n.icon-circle {\n  width: 56px; height: 56px; border-radius: 50%; background: #fff; border: 3px solid var(--cor-borda-clara);\n  display: grid; place-items: center; color: var(--cor-primaria); margin-bottom: 10px; position: relative; z-index: 1;\n}\n.icon-circle svg { width: 24px; height: 24px; }\n.icon-circle.active { background: var(--cor-primaria); border-color: var(--cor-primaria); color: #fff; }\n.icon-circle.locked { background: #f3f4f6; border-color: #e5e7eb; color: #9ca3af; }\n\n.aula-card {\n  width: 100%; background: #fff; border: 2px solid var(--cor-borda-clara); border-radius: 20px;\n  padding: 16px 18px; box-shadow: 0 6px 20px rgba(var(--cor-primaria-rgb),0.08); position: relative;\n  text-align: center;\n}\n.aula-card.locked { background: #f9fafb; border-color: #e5e7eb; box-shadow: none; }\n.aula-card h3 { font-size: 18px; font-weight: 700; color: #1a1a2e; margin-bottom: 6px; }\n.aula-card.locked h3 { color: #6b7280; }\n.status { font-size: 14px; color: #6b7280; margin-bottom: 14px; }\n\n.progress-bar { height: 6px; border-radius: 4px; background: var(--cor-borda-clara); overflow: hidden; margin-bottom: 12px; }\n.progress-bar-fill { height: 100%; background: var(--cor-primaria); transition: width .3s; }\n\n.btn-favoritar {\n  position: absolute; top: 14px; right: 14px; width: 32px; height: 32px; border-radius: 50%;\n  background: #fff; border: 2px solid var(--cor-borda-clara); color: #f3b6c9; display: grid; place-items: center; cursor: pointer;\n}\n.btn-favoritar svg { width: 15px; height: 15px; }\n.btn-favoritar:hover { color: #ec4899; }\n.btn-favoritar.favorita { color: #ec4899; }\n.btn-favoritar.favorita svg { fill: #ec4899; }\n.aula-card.locked .btn-favoritar { opacity: .4; cursor: not-allowed; }\n\n.btn-acao { width: 100%; padding: 11px; border: none; border-radius: 12px; font-family: inherit; font-weight: 700; font-size: 14px; cursor: pointer; }\n.btn-acao.ativa { background: var(--cor-primaria); color: #fff; }\n.btn-acao.ativa:hover { background: var(--cor-primaria-escura); box-shadow: 0 4px 12px rgba(var(--cor-primaria-rgb),0.3); }\n.btn-acao.bloqueada { background: #e5e7eb; color: #9ca3af; cursor: not-allowed; }\n\n/* CADERNOS (erros / favoritos / revisão) */\n.view-erros { padding: 20px 16px 16px; }\n.erros-header { margin-bottom: 18px; }\n.erros-header h2 { font-size: 21px; font-weight: 700; color: #1a1a2e; }\n.erros-header p { font-size: 14px; line-height: 1.5; color: #6b7280; margin-top: 4px; }\n\n.cadernos-tabs { display: flex; gap: 8px; margin-bottom: 18px; }\n.caderno-tab {\n  flex: 1; padding: 10px 12px; border-radius: 12px; border: 1.5px solid var(--cor-borda-clara);\n  background: #fff; color: #6b7280; font-family: inherit; font-weight: 600; font-size: 13px; cursor: pointer;\n  transition: all .2s;\n}\n.caderno-tab:hover { background: var(--cor-hover-fundo); }\n.caderno-tab.active { background: var(--cor-primaria); border-color: var(--cor-primaria); color: #fff; }\n\n.cadernos-subtabs { display: flex; gap: 16px; margin: -6px 0 16px; padding-bottom: 10px; border-bottom: 1.5px solid var(--cor-clara); }\n.caderno-subtab {\n  padding: 4px 2px; border: none; background: none; color: #9ca3af; font-family: inherit;\n  font-weight: 600; font-size: 13px; cursor: pointer; position: relative;\n}\n.caderno-subtab.active { color: var(--cor-primaria); }\n.caderno-subtab.active::after { content: ''; position: absolute; left: 0; right: 0; bottom: -11px; height: 2px; background: var(--cor-primaria); }\n\n.erros-list { display: flex; flex-direction: column; gap: 12px; }\n.erro-card {\n  display: flex; align-items: center; justify-content: space-between; gap: 12px;\n  border: 2px solid #fde0e0; border-radius: 18px; padding: 16px 18px; background: #fff;\n  box-shadow: 0 4px 14px rgba(220,38,38,0.06);\n}\n.erro-card-info h3 { font-size: 16px; font-weight: 700; color: #1a1a2e; margin-bottom: 4px; }\n.erro-card-info p { font-size: 14px; font-weight: 600; color: #ef4444; }\n.erro-card-info p.cor-favorito { color: #ec4899; }\n.erro-card-info p.cor-revisao { color: #4A80F0; }\n\n.btn-praticar {\n  flex-shrink: 0; padding: 10px 18px; border: none; border-radius: 12px; background: var(--cor-primaria);\n  color: #fff; font-family: inherit; font-weight: 600; font-size: 15px; cursor: pointer; transition: all .2s;\n}\n.btn-praticar:hover { background: var(--cor-primaria-escura); transform: translateY(-1px); }\n\n.erros-empty { text-align: center; padding: 60px 20px; color: #6b7280; }\n.erros-empty-emoji { font-size: 40px; margin-bottom: 10px; }\n.erros-empty p { font-size: 15px; margin-bottom: 4px; }\n.erros-empty-sub { font-size: 14px; max-width: 280px; margin: 6px auto 0; line-height: 1.5; color: #9ca3af; }\n\n/* ESTUDOS (visão geral por nível/ciclo) */\n.view-niveis { padding: 20px 16px 16px; }\n.niveis-lista { padding-bottom: 24px; }\n.sprint-lista { display: flex; flex-direction: column; gap: 14px; margin-bottom: 22px; }\n\n.nivel-card-unico { background: #fff; border: 2px solid var(--cor-borda-clara); border-radius: 18px; padding: 18px; box-shadow: 0 4px 14px rgba(var(--cor-primaria-rgb),0.06); }\n.nivel-card-unico-cabecalho { display: flex; align-items: center; gap: 14px; cursor: pointer; }\n.nivel-card-unico-seta { transition: transform .3s ease; flex-shrink: 0; }\n.nivel-card-unico-cabecalho.collapsed .nivel-card-unico-seta { transform: rotate(-90deg); }\n.nivel-card-unico-corpo { overflow: hidden; max-height: 2000px; opacity: 1; transition: max-height .4s ease, opacity .3s ease; }\n.nivel-card-unico-corpo.collapsed { max-height: 0; opacity: 0; }\n\n.sprint-card-numero { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; font-size: 14px; font-weight: 800; color: #fff; flex-shrink: 0; }\n.sprint-card-numero.andamento { background: var(--cor-primaria); }\n.sprint-card-numero.concluida { background: #16a34a; }\n.sprint-titulo { flex: 1; font-size: 16px; font-weight: 700; color: #1a1a2e; line-height: 1.3; }\n\n.ciclo-secao { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--cor-clara); cursor: pointer; }\n.ciclo-secao.bloqueada { cursor: default; padding-top: 14px; }\n.ciclo-secao-cabecalho { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }\n.ciclo-secao-label { font-size: 13px; font-weight: 800; color: #1a1a2e; }\n.ciclo-secao-label.bloqueada { display: flex; align-items: center; gap: 6px; font-weight: 700; color: #9ca3af; }\n\n.sprint-status { font-size: 11px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; padding: 3px 9px; border-radius: 999px; }\n.sprint-status.concluida { background: #dcfce7; color: #15803d; }\n.sprint-status.andamento { background: var(--cor-clara); color: var(--cor-primaria); }\n\n.sprint-etapas { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }\n.sprint-materia-tag { background: #f8f6ff; border: 1px solid var(--cor-clara); border-radius: 10px; padding: 5px 9px; font-size: 12px; font-weight: 700; color: var(--cor-primaria); }\n\n.sprint-progress-row { display: flex; align-items: center; gap: 10px; }\n.sprint-progress-pct { width: 38px; font-size: 13px; font-weight: 800; flex-shrink: 0; }\n.sprint-progress-pct.concluida { color: #16a34a; }\n.sprint-progress-pct.andamento { color: var(--cor-primaria); }\n.sprint-progress-bar { flex: 1; height: 6px; background: var(--cor-clara); border-radius: 4px; overflow: hidden; }\n.sprint-progress-bar-fill { height: 100%; background: var(--cor-primaria); border-radius: 4px; }\n\n.trilha-section { background: #fff; border: 2px solid var(--cor-borda-clara); border-radius: 18px; padding: 18px; margin-bottom: 22px; }\n.trilha-titulo { font-size: 16px; font-weight: 700; color: #1a1a2e; margin-bottom: 4px; }\n.trilha-desc { font-size: 13px; color: #6b7280; line-height: 1.4; }\n.trilha-section.trilha-bloqueada { background: #f9fafb; opacity: .85; }\n.trilha-bloqueada-cabecalho { display: flex; align-items: center; gap: 6px; color: #9ca3af; margin-bottom: 4px; }\n.trilha-bloqueada-cabecalho .trilha-titulo { margin-bottom: 0; color: #9ca3af; }\n.trilha-section.trilha-bloqueada .trilha-desc { margin-bottom: 0; }\n\n/* VIEWS SECUNDÁRIAS (placeholder) */\n.view-placeholder { padding: 60px 24px; text-align: center; color: #6b7280; }\n.view-placeholder h2 { font-size: 19px; color: #1a1a2e; margin-bottom: 8px; }\n\n.vazio-aviso { margin: 40px 20px; padding: 28px 20px; text-align: center; background: #fff; border-radius: 20px; color: #6b7280; box-shadow: 0 4px 16px rgba(var(--cor-primaria-rgb),0.06); }\n\n/* BOTTOM NAV */\n.bottom-nav {\n  position: fixed; bottom: 14px; left: 50%; transform: translateX(-50%); width: calc(100% - 32px); max-width: 460px;\n  background: #fff; border-radius: 28px; box-shadow: 0 8px 30px rgba(0,0,0,0.08); border: 1px solid var(--cor-clara);\n  display: flex; padding: 8px; z-index: 20;\n}\n.nav-item { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 8px 4px; border-radius: 20px; cursor: pointer; color: #9ca3af; font-size: 11px; font-weight: 600; }\n.nav-item svg { width: 20px; height: 20px; }\n.nav-item.active { background: var(--cor-clara); color: var(--cor-primaria); }\n\n/* TOAST */\n.toast {\n  position: fixed; left: 50%; bottom: 90px; transform: translateX(-50%) translateY(20px);\n  background: #1a1a2e; color: #fff; padding: 12px 20px; border-radius: 14px; font-size: 13.5px; font-weight: 600;\n  opacity: 0; pointer-events: none; transition: opacity .2s, transform .2s; max-width: 90%; text-align: center; z-index: 50;\n}\n.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n",
  "js/inicio.mjs": "'use strict';\n\n/**\n * INICIO.JS — Tela inicial do projeto exportado. Gera a trilha de\n * ciclos/etapas/aulas dinamicamente a partir de MODULOS/NIVEIS (js/data/\n * modulos.js) — nunca precisa ser escrita/sincronizada à mão — e reproduz a\n * mesma regra de trava/destrava/estrelas do projeto original (estudos):\n * uma corrente sequencial única por id de aula (MODULOS.flatMap ordem),\n * independente de etapa/nível. Progresso persiste em localStorage via\n * js/progresso.js.\n */\n\nconst state = { aulas: [] };\n\nfunction listaAulas() {\n  return (MODULOS || []).flatMap(m => m.aulas);\n}\n\nfunction aulasPadrao() {\n  return listaAulas().map((a, i) => ({\n    id: a.id,\n    status: i === 0 ? 'active' : 'locked',\n    progress: 0,\n    stars: 0,\n    favorita: false,\n  }));\n}\n\nasync function carregarProgresso() {\n  const dados = await lerArquivoProgresso();\n  const salvas = Array.isArray(dados?.aulas) ? dados.aulas : [];\n  state.aulas = aulasPadrao().map(padrao => {\n    const salva = salvas.find(a => a.id === padrao.id);\n    return salva ? { ...padrao, ...salva } : padrao;\n  });\n\n  // Recalcula o status a partir de \"completed\": a primeira aula não concluída\n  // fica ativa, tudo depois dela fica bloqueado — nunca confia cegamente no\n  // status salvo (protege contra aula nova inserida no meio, etc).\n  let achouAtiva = false;\n  state.aulas = state.aulas.map(aula => {\n    if (aula.status === 'completed') return aula;\n    if (!achouAtiva) {\n      achouAtiva = true;\n      return aula.status === 'active' ? aula : { ...aula, status: 'active' };\n    }\n    return aula.status === 'locked' ? aula : { ...aula, status: 'locked', progress: 0, stars: 0 };\n  });\n}\n\nasync function salvarProgresso() {\n  await gravarArquivoProgresso({ aulas: state.aulas });\n}\n\n/** Lê (e consome) o resultado gravado por estudo.js em sessionStorage antes de voltar. */\nfunction lerResultadoSessao() {\n  const maxId = listaAulas().reduce((max, a) => Math.max(max, a.id), 0);\n  for (let i = 1; i <= maxId; i++) {\n    const key = `aula${i}_resultado`;\n    const raw = sessionStorage.getItem(key);\n    if (!raw) continue;\n    sessionStorage.removeItem(key);\n    const { aulaId, estrelas, acertos, total } = JSON.parse(raw);\n    return { aulaId, estrelas, acertos, total, concluida: acertos >= Math.ceil(total * 0.5) };\n  }\n  return null;\n}\n\nfunction aplicarResultado(r) {\n  const idx = state.aulas.findIndex(a => a.id === r.aulaId);\n  if (idx === -1) return;\n  const atual = state.aulas[idx];\n  if (r.concluida) {\n    state.aulas[idx] = { ...atual, status: 'completed', progress: 100, stars: r.estrelas };\n    const proxima = state.aulas[idx + 1];\n    if (proxima && proxima.status === 'locked') state.aulas[idx + 1] = { ...proxima, status: 'active', progress: 0 };\n  } else {\n    state.aulas[idx] = { ...atual, status: 'active', progress: Math.round((r.acertos / r.total) * 100), stars: r.estrelas };\n  }\n}\n\n/* ---------------------------------------------------------------------- */\n/* Ícones                                                                   */\n/* ---------------------------------------------------------------------- */\n\nconst ICONE_CADEADO = '<rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"></rect><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"></path>';\nconst ICONE_PADRAO = '<path d=\"M12 2l2.4 7.2H22l-6 4.6 2.3 7.2-6.3-4.5-6.3 4.5 2.3-7.2-6-4.6h7.6z\"></path>';\nconst ICONES_AULA = {\n  busca:     '<circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line>',\n  pessoa:    '<circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 21v-1a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v1\"></path>',\n  balao:     '<path d=\"M21 15a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z\"></path>',\n  bandeira:  '<path d=\"M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z\"></path><line x1=\"4\" y1=\"22\" x2=\"4\" y2=\"15\"></line>',\n  nuvem:     '<path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9z\"></path>',\n  relogio:   '<circle cx=\"12\" cy=\"12\" r=\"9\"></circle><polyline points=\"12 7 12 12 16 14\"></polyline>',\n  resumo:    '<rect x=\"6\" y=\"3\" width=\"12\" height=\"18\" rx=\"2\"></rect><line x1=\"9\" y1=\"8\" x2=\"15\" y2=\"8\"></line><line x1=\"9\" y1=\"12\" x2=\"15\" y2=\"12\"></line><line x1=\"9\" y1=\"16\" x2=\"12\" y2=\"16\"></line>',\n  balanca:   '<path d=\"m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z\"></path><path d=\"m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z\"></path><path d=\"M7 21h10\"></path><path d=\"M12 3v18\"></path><path d=\"M3 7h2c2 0 5-1 7-2 2 1 5 2 7 2h2\"></path>',\n  padrao:    ICONE_PADRAO,\n};\n\nfunction escaparHtml(s) {\n  return String(s || '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n}\n\n/* ---------------------------------------------------------------------- */\n/* Construção da trilha (DOM a partir de MODULOS/NIVEIS)                    */\n/* ---------------------------------------------------------------------- */\n\nfunction montarEtapas() {\n  const wrap = document.getElementById('etapasWrap');\n  wrap.innerHTML = '';\n\n  if (listaAulas().length === 0) {\n    wrap.innerHTML = `<div class=\"vazio-aviso\">Nenhuma aula exportada ainda.<br>Volte ao Construtor de Aulas, preencha o conteúdo e exporte de novo.</div>`;\n    return;\n  }\n\n  (MODULOS || []).forEach(etapa => {\n    const div = document.createElement('div');\n    div.className = 'etapa-view';\n    div.dataset.etapa = etapa.id;\n    div.innerHTML = `\n      <div class=\"hero-card\">\n        <div class=\"nivel-selector\"><span></span>\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"></polyline></svg>\n        </div>\n        <div class=\"hero-content\">\n          <span class=\"hero-materia\">${escaparHtml(etapa.materia || '')}</span>\n          <h2 class=\"hero-title\"></h2>\n          <div class=\"progress-segments\"></div>\n        </div>\n      </div>\n      <div class=\"path-container\">\n        <div class=\"path-line\"></div>\n        <div class=\"path-line-lit\"></div>\n        ${etapa.aulas.map(aula => `\n          <div class=\"aula-node\" data-aula=\"${aula.id}\">\n            <div class=\"stars\"><span class=\"star\">★</span><span class=\"star\">★</span><span class=\"star\">★</span></div>\n            <div class=\"icon-circle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></svg></div>\n            <div class=\"aula-card\">\n              <button type=\"button\" class=\"btn-favoritar\" title=\"Marcar como favorita\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1.1L12 21l7.8-7.5 1-1.1a5.5 5.5 0 0 0 0-7.8z\"></path></svg>\n              </button>\n              <h3>${escaparHtml(aula.titulo)}</h3>\n              <p class=\"status\"></p>\n              <div class=\"progress-bar\"><div class=\"progress-bar-fill\" style=\"width:0%\"></div></div>\n              <button type=\"button\" class=\"btn-acao\"></button>\n            </div>\n          </div>`).join('')}\n      </div>`;\n    wrap.appendChild(div);\n  });\n}\n\n/* ---------------------------------------------------------------------- */\n/* Renderização de estado (lock/estrelas/progresso)                         */\n/* ---------------------------------------------------------------------- */\n\nfunction renderAulas() {\n  state.aulas.forEach(aula => {\n    const node = document.querySelector(`[data-aula=\"${aula.id}\"]`);\n    if (!node) return;\n\n    const iconCircle = node.querySelector('.icon-circle');\n    const iconSvg    = iconCircle.querySelector('svg');\n    const card       = node.querySelector('.aula-card');\n    const statusEl   = node.querySelector('.status');\n    const barFill    = node.querySelector('.progress-bar-fill');\n    const btn        = node.querySelector('.btn-acao');\n    const stars      = node.querySelectorAll('.star');\n    const btnFav     = node.querySelector('.btn-favoritar');\n    if (btnFav) btnFav.classList.toggle('favorita', !!aula.favorita);\n\n    const info = listaAulas().find(a => a.id === aula.id);\n    if (iconSvg) iconSvg.innerHTML = aula.status === 'locked' ? ICONE_CADEADO : (ICONES_AULA[info?.icone] || ICONE_PADRAO);\n\n    node.classList.toggle('locked', aula.status === 'locked');\n    card.classList.toggle('locked', aula.status === 'locked');\n\n    if (aula.status === 'locked') {\n      iconCircle.className = 'icon-circle locked';\n      statusEl.textContent = 'Bloqueada';\n      barFill.style.width  = '0%';\n      btn.textContent = '🔒 Bloqueada';\n      btn.disabled    = true;\n      btn.className   = 'btn-acao bloqueada';\n      stars.forEach(s => { s.style.color = '#e5e7eb'; });\n    } else if (aula.status === 'active') {\n      iconCircle.className = 'icon-circle active';\n      statusEl.textContent = aula.progress > 0 ? 'Em andamento' : 'Não iniciada';\n      barFill.style.width  = `${aula.progress}%`;\n      btn.textContent = aula.progress > 0 ? 'Continuar' : 'Começar';\n      btn.disabled    = false;\n      btn.className   = 'btn-acao ativa';\n      stars.forEach((s, i) => { s.style.color = i < aula.stars ? '#FFD700' : '#e5e7eb'; });\n    } else {\n      iconCircle.className = 'icon-circle active';\n      statusEl.textContent = 'Concluída';\n      barFill.style.width  = '100%';\n      btn.textContent = 'Recomeçar';\n      btn.disabled    = false;\n      btn.className   = 'btn-acao ativa';\n      stars.forEach((s, i) => { s.style.color = i < aula.stars ? '#FFD700' : '#e5e7eb'; });\n    }\n  });\n\n  atualizarTrilha();\n  atualizarProgressoEtapas();\n}\n\nfunction atualizarTrilha() {\n  document.querySelectorAll('.etapa-view').forEach(etapaView => {\n    const container = etapaView.querySelector('.path-container');\n    const lit       = etapaView.querySelector('.path-line-lit');\n    const etapaInfo = (MODULOS || []).find(m => String(m.id) === etapaView.dataset.etapa);\n    if (!container || !lit || !etapaInfo) return;\n\n    const aulasDaEtapa = etapaInfo.aulas.map(a => state.aulas.find(s => s.id === a.id)).filter(Boolean);\n    const circulos = aulasDaEtapa.map(aula => document.querySelector(`[data-aula=\"${aula.id}\"] .icon-circle`)).filter(Boolean);\n\n    let ultimoCompletoIdx = -1;\n    for (let i = 0; i < aulasDaEtapa.length; i++) {\n      if (aulasDaEtapa[i].status === 'completed') ultimoCompletoIdx = i;\n      else break;\n    }\n    if (ultimoCompletoIdx === -1 || !circulos[ultimoCompletoIdx]) { lit.style.height = '0px'; return; }\n\n    const containerTop = container.getBoundingClientRect().top;\n    const centro = el => el.getBoundingClientRect().top + el.getBoundingClientRect().height / 2;\n    const proximoCirculo = circulos[ultimoCompletoIdx + 1];\n    const altura = (proximoCirculo ? centro(proximoCirculo) : centro(circulos[ultimoCompletoIdx])) - containerTop;\n    lit.style.height = `${Math.max(0, altura)}px`;\n  });\n}\n\nfunction atualizarProgressoEtapas() {\n  document.querySelectorAll('.etapa-view').forEach(etapaView => {\n    const heroCard     = etapaView.querySelector('.hero-card');\n    const segmentsWrap = etapaView.querySelector('.progress-segments');\n    const etapaInfo    = (MODULOS || []).find(m => String(m.id) === etapaView.dataset.etapa);\n    if (!heroCard || !segmentsWrap || !etapaInfo) return;\n\n    const aulasDaEtapa = etapaInfo.aulas.map(a => state.aulas.find(s => s.id === a.id)).filter(Boolean);\n    const concluidas = aulasDaEtapa.filter(a => a.status === 'completed').length;\n\n    segmentsWrap.innerHTML = aulasDaEtapa.map((_, i) => `<div class=\"segment${i < concluidas ? ' filled' : ''}\"></div>`).join('');\n    heroCard.classList.toggle('etapa-completa', aulasDaEtapa.length > 0 && concluidas === aulasDaEtapa.length);\n  });\n}\n\nfunction atualizarSeletoresDeNivel() {\n  document.querySelectorAll('.etapa-view[data-etapa]').forEach(etapaEl => {\n    const etapaId = parseInt(etapaEl.dataset.etapa, 10);\n    const niveis = NIVEIS || [];\n    const posicao = niveis.findIndex(n => n.etapas.includes(etapaId));\n    const nivel = niveis[posicao];\n\n    // Selo de cima é sempre genérico (\"Nível N\") — quem carrega a informação\n    // de verdade (o nome do ciclo) é o título grande abaixo da matéria, pra\n    // não repetir o mesmo texto duas vezes.\n    const span = etapaEl.querySelector('.nivel-selector span');\n    if (span) span.textContent = posicao === -1 ? 'Etapa' : `Nível ${posicao + 1}`;\n\n    const tituloEl = etapaEl.querySelector('.hero-title');\n    if (tituloEl) tituloEl.textContent = nivel ? nivel.titulo : '';\n  });\n}\n\n/* ---------------------------------------------------------------------- */\n/* Colapsar/expandir cada etapa                                             */\n/* ---------------------------------------------------------------------- */\n\nfunction configurarColapsos() {\n  document.querySelectorAll('.etapa-view').forEach(etapaView => {\n    const nivelSelector = etapaView.querySelector('.nivel-selector');\n    const heroCard      = etapaView.querySelector('.hero-card');\n    const pathContainer = etapaView.querySelector('.path-container');\n    let colapsado = false;\n    function aplicar() {\n      // hero-content (matéria/título/barra de progresso) fica sempre visível\n      // mesmo recolhido — só a lista de aulas (pathContainer) esconde. Igual\n      // ao comportamento real do estudos (configurarColapsoHero em script.js).\n      [nivelSelector, heroCard, pathContainer].forEach(el => el.classList.toggle('collapsed', colapsado));\n    }\n    function alternar() { colapsado = !colapsado; aplicar(); }\n    nivelSelector.addEventListener('click', e => { e.stopPropagation(); alternar(); });\n    heroCard.addEventListener('click', e => { if (e.target.closest('.hero-content')) return; alternar(); });\n    etapaView._setColapsado = valor => { colapsado = valor; aplicar(); };\n  });\n}\n\nfunction aplicarColapsoInicial() {\n  const etapas = Array.from(document.querySelectorAll('.etapa-view')).map(view => {\n    const etapaInfo = (MODULOS || []).find(m => String(m.id) === view.dataset.etapa);\n    const aulasDaEtapa = etapaInfo ? etapaInfo.aulas.map(a => state.aulas.find(s => s.id === a.id)).filter(Boolean) : [];\n    return { view, emAndamento: aulasDaEtapa.some(a => a.status === 'active') };\n  });\n  const existeEmAndamento = etapas.some(e => e.emAndamento);\n  etapas.forEach((etapa, i) => {\n    const deveAbrir = existeEmAndamento ? etapa.emAndamento : i === etapas.length - 1;\n    if (etapa.view._setColapsado) etapa.view._setColapsado(!deveAbrir);\n  });\n}\n\n/* ---------------------------------------------------------------------- */\n/* Eventos das aulas (favoritar / bloqueada / começar)                      */\n/* ---------------------------------------------------------------------- */\n\nfunction configurarEventosAulas() {\n  document.getElementById('etapasWrap').addEventListener('click', e => {\n    const btnFav = e.target.closest('.btn-favoritar');\n    if (btnFav) {\n      e.stopPropagation();\n      const node   = btnFav.closest('[data-aula]');\n      const aulaId = node ? parseInt(node.dataset.aula, 10) : null;\n      const aula   = state.aulas.find(a => a.id === aulaId);\n      if (aula && aula.status === 'locked') { showToast('🔒 Conclua a aula anterior para poder favoritar esta.'); return; }\n      if (aula) {\n        aula.favorita = !aula.favorita;\n        renderAulas();\n        showToast(aula.favorita ? '❤️ Aula marcada como favorita!' : 'Aula removida dos favoritos', 'success');\n        salvarProgresso();\n      }\n      return;\n    }\n\n    const lockedNode = e.target.closest('.aula-node.locked');\n    if (lockedNode) { showToast('🔒 Conclua a aula anterior para desbloquear'); return; }\n\n    const btn = e.target.closest('.btn-acao');\n    if (btn && !btn.disabled) {\n      const node = btn.closest('[data-aula]');\n      const aulaId = node ? node.dataset.aula : null;\n      window.location.href = `estudo.html?aula=${aulaId || 1}`;\n    }\n  });\n}\n\n/* ---------------------------------------------------------------------- */\n/* Toast + navegação inferior                                               */\n/* ---------------------------------------------------------------------- */\n\nlet toastTimer;\nfunction showToast(msg, type = 'default', duracao = 2500) {\n  let toast = document.getElementById('toastMsg');\n  if (!toast) {\n    toast = document.createElement('div');\n    toast.id = 'toastMsg';\n    toast.className = 'toast';\n    document.body.appendChild(toast);\n  }\n  toast.textContent = msg;\n  toast.style.background = type === 'success' ? '#16a34a' : (type === 'warning' ? '#d97706' : '#1a1a2e');\n  clearTimeout(toastTimer);\n  toast.classList.add('show');\n  toastTimer = setTimeout(() => toast.classList.remove('show'), duracao);\n}\n\nfunction configurarBottomNav() {\n  const paginas = {\n    inicio:     document.getElementById('viewInicio'),\n    erros:      document.getElementById('viewErros'),\n    desempenho: document.getElementById('viewDesempenho'),\n    niveis:     document.getElementById('viewNiveis'),\n  };\n  document.querySelectorAll('.nav-item').forEach(item => {\n    item.addEventListener('click', () => {\n      const view = item.dataset.view;\n      Object.entries(paginas).forEach(([nome, el]) => { if (el) el.style.display = nome === view ? '' : 'none'; });\n      document.querySelectorAll('.nav-item').forEach(n => n.classList.toggle('active', n === item));\n      if (view === 'erros') renderCadernoAtivo();\n      if (view === 'niveis') renderNiveis();\n    });\n  });\n}\n\n/* ---------------------------------------------------------------------- */\n/* Init                                                                      */\n/* ---------------------------------------------------------------------- */\n\ndocument.addEventListener('DOMContentLoaded', async () => {\n  montarEtapas();\n  if (listaAulas().length === 0) return;\n\n  await carregarProgresso();\n  const resultado = lerResultadoSessao();\n  if (resultado) {\n    aplicarResultado(resultado);\n    await salvarProgresso();\n  }\n\n  atualizarSeletoresDeNivel();\n  renderAulas();\n  configurarColapsos();\n  aplicarColapsoInicial();\n  configurarEventosAulas();\n  configurarEventosCadernos();\n  configurarBottomNav();\n});\n",
  "js/cadernos.mjs": "'use strict';\n\n/**\n * CADERNOS.MJS — Aba \"Cadernos\": erros, favoritos e telas/perguntas\n * marcadas para revisão. Usa js/progresso.mjs (localStorage) pros dados e\n * MODULOS (js/data/modulos.mjs) pra listar as aulas na ordem certa. Depende\n * de listaAulas()/escaparHtml()/state, definidos em js/inicio.mjs.\n */\n\nlet cadernoAtivo = 'erros';\nlet subCadernoAtivo = 'aula';\n\nconst SUBTABS_POR_CADERNO = {\n  erros:   [{ valor: 'aula', label: 'Por aula' }, { valor: 'geral', label: 'Geral' }],\n  revisao: [{ valor: 'telas', label: 'Aulas' }, { valor: 'perguntas', label: 'Perguntas' }],\n};\n\nfunction trocarCadernoTab(tab) {\n  cadernoAtivo = tab;\n  document.querySelectorAll('.caderno-tab').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tab));\n\n  const subtabsBar = document.getElementById('cadernosSubtabs');\n  const config = SUBTABS_POR_CADERNO[tab];\n  if (config) {\n    subtabsBar.style.display = 'flex';\n    const botoes = subtabsBar.querySelectorAll('.caderno-subtab');\n    config.forEach((cfg, i) => {\n      if (!botoes[i]) return;\n      botoes[i].textContent = cfg.label;\n      botoes[i].dataset.subtab = cfg.valor;\n      botoes[i].classList.toggle('active', i === 0);\n    });\n    subCadernoAtivo = config[0].valor;\n  } else {\n    subtabsBar.style.display = 'none';\n  }\n  renderCadernoAtivo();\n}\n\nfunction trocarCadernoSubTab(sub) {\n  subCadernoAtivo = sub;\n  document.querySelectorAll('.caderno-subtab').forEach(btn => btn.classList.toggle('active', btn.dataset.subtab === sub));\n  renderCadernoAtivo();\n}\n\nfunction formatarTempoRelativo(iso) {\n  const diffMin = (Date.now() - new Date(iso).getTime()) / 60000;\n  if (diffMin < 1) return 'agora mesmo';\n  if (diffMin < 60) return `há ${Math.floor(diffMin)}min`;\n  const h = diffMin / 60;\n  if (h < 24) return `há ${Math.floor(h)}h`;\n  const d = h / 24;\n  if (d < 30) return `há ${Math.floor(d)}d`;\n  return new Date(iso).toLocaleDateString('pt-BR');\n}\n\nfunction ehPergunta(chave) {\n  return chave.startsWith('checagem') || chave.startsWith('questao');\n}\n\nconst EMPTY_ERROS = `\n  <div class=\"erros-empty\">\n    <p class=\"erros-empty-emoji\">🎉</p>\n    <p>Nenhum erro registrado ainda.</p>\n    <p class=\"erros-empty-sub\">As questões que você errar aparecem aqui e ficam disponíveis para revisão até você dominá-las.</p>\n  </div>`;\n\nconst EMPTY_FAVORITOS = `\n  <div class=\"erros-empty\">\n    <p class=\"erros-empty-emoji\">🤍</p>\n    <p>Nenhuma aula favoritada ainda.</p>\n    <p class=\"erros-empty-sub\">Toque no coraçãozinho no card da aula para marcá-la como favorita.</p>\n  </div>`;\n\nfunction emptyRevisaoHtml(mostrarPerguntas) {\n  return `\n    <div class=\"erros-empty\">\n      <p class=\"erros-empty-emoji\">🔖</p>\n      <p>${mostrarPerguntas ? 'Nenhuma pergunta marcada ainda.' : 'Nenhuma tela marcada ainda.'}</p>\n      <p class=\"erros-empty-sub\">${mostrarPerguntas\n        ? 'Toque na etiqueta no canto das perguntas da aula para marcá-las.'\n        : 'Toque na etiqueta no canto das telas de definição, contexto e exemplo para marcá-las.'}</p>\n    </div>`;\n}\n\nasync function renderErrosPorAula() {\n  const list = document.getElementById('errosList');\n  if (!list) return;\n  const notebook = await getErrorNotebook();\n  let html = '';\n  listaAulas().forEach(aula => {\n    const idxs = notebook[String(aula.id)] || [];\n    if (idxs.length === 0) return;\n    html += `\n      <div class=\"erro-card\">\n        <div class=\"erro-card-info\">\n          <h3>${escaparHtml(aula.titulo)}</h3>\n          <p>${idxs.length} ${idxs.length !== 1 ? 'questões' : 'questão'} para revisar</p>\n        </div>\n        <button type=\"button\" class=\"btn-praticar\" data-aula=\"${aula.id}\">Praticar</button>\n      </div>`;\n  });\n  list.innerHTML = html || EMPTY_ERROS;\n}\n\nasync function renderErrosGeral() {\n  const list = document.getElementById('errosList');\n  if (!list) return;\n  const [notebook, recentes] = await Promise.all([getErrorNotebook(), getErrosRecentes()]);\n  const total = Object.values(notebook).reduce((soma, arr) => soma + (arr || []).length, 0);\n  const maisRecente = recentes.reduce((max, r) => (!max || new Date(r.quando) > new Date(max)) ? r.quando : max, null);\n  const subtitulo = `${total} ${total !== 1 ? 'perguntas' : 'pergunta'} de todas as aulas, do mais recente ao mais antigo`\n    + (maisRecente ? ` — último erro ${formatarTempoRelativo(maisRecente)}` : '');\n\n  list.innerHTML = total > 0 ? `\n    <div class=\"erro-card\">\n      <div class=\"erro-card-info\">\n        <h3>Todos os erros</h3>\n        <p>${subtitulo}</p>\n      </div>\n      <button type=\"button\" class=\"btn-praticar\" id=\"btnPraticarGeral\">Praticar</button>\n    </div>` : EMPTY_ERROS;\n}\n\nasync function renderErrosView() {\n  if (subCadernoAtivo === 'geral') return renderErrosGeral();\n  return renderErrosPorAula();\n}\n\nfunction renderFavoritosView() {\n  const list = document.getElementById('errosList');\n  if (!list) return;\n  let html = '';\n  listaAulas().forEach(aulaInfo => {\n    const aula = state.aulas.find(a => a.id === aulaInfo.id);\n    if (!aula || !aula.favorita || aula.status === 'locked') return;\n    html += `\n      <div class=\"erro-card\">\n        <div class=\"erro-card-info\">\n          <h3>${escaparHtml(aulaInfo.titulo)}</h3>\n          <p class=\"cor-favorito\">Aula favorita</p>\n        </div>\n        <button type=\"button\" class=\"btn-praticar\" data-aula=\"${aulaInfo.id}\">Abrir</button>\n      </div>`;\n  });\n  list.innerHTML = html || EMPTY_FAVORITOS;\n}\n\nasync function renderRevisaoView() {\n  const list = document.getElementById('errosList');\n  if (!list) return;\n  const marcados = await getCartoesMarcados();\n  const mostrarPerguntas = subCadernoAtivo === 'perguntas';\n  let html = '';\n  listaAulas().forEach(aula => {\n    const chaves = (marcados[String(aula.id)] || []).filter(c => ehPergunta(c) === mostrarPerguntas);\n    if (chaves.length === 0) return;\n    const rotulo = mostrarPerguntas ? 'pergunta' : 'tela';\n    html += `\n      <div class=\"erro-card\">\n        <div class=\"erro-card-info\">\n          <h3>${escaparHtml(aula.titulo)}</h3>\n          <p class=\"cor-revisao\">${chaves.length} ${rotulo}${chaves.length !== 1 ? 's' : ''} para revisar</p>\n        </div>\n        <button type=\"button\" class=\"btn-praticar\" data-aula=\"${aula.id}\">Ver</button>\n      </div>`;\n  });\n  list.innerHTML = html || emptyRevisaoHtml(mostrarPerguntas);\n}\n\nasync function renderCadernoAtivo() {\n  if (cadernoAtivo === 'favoritos') return renderFavoritosView();\n  if (cadernoAtivo === 'revisao') return renderRevisaoView();\n  return renderErrosView();\n}\n\nfunction configurarEventosCadernos() {\n  document.querySelectorAll('.caderno-tab').forEach(btn => {\n    btn.addEventListener('click', () => trocarCadernoTab(btn.dataset.tab));\n  });\n  document.querySelectorAll('.caderno-subtab').forEach(btn => {\n    btn.addEventListener('click', () => trocarCadernoSubTab(btn.dataset.subtab));\n  });\n  document.getElementById('errosList').addEventListener('click', e => {\n    if (e.target.closest('#btnPraticarGeral')) {\n      window.location.href = 'estudo.html?modo=erros&geral=1';\n      return;\n    }\n    const btn = e.target.closest('.btn-praticar');\n    if (!btn) return;\n    const aulaId = btn.dataset.aula;\n    if (cadernoAtivo === 'favoritos') {\n      window.location.href = `estudo.html?aula=${aulaId}`;\n    } else if (cadernoAtivo === 'revisao') {\n      const tipo = subCadernoAtivo === 'perguntas' ? 'perguntas' : 'telas';\n      window.location.href = `estudo.html?aula=${aulaId}&modo=revisao&tipo=${tipo}`;\n    } else {\n      window.location.href = `estudo.html?aula=${aulaId}&modo=erros`;\n    }\n  });\n}\n",
  "js/niveis.mjs": "'use strict';\n\n/**\n * NIVEIS.MJS — Aba \"Estudos\": visão geral por nível/ciclo, igual ao estudos\n * original. Cada ciclo criado no Construtor de Aulas vira uma NIVEIS entry\n * (js/data/modulos.mjs) — todas elas aparecem aqui dentro de um card único\n * \"Nível 1 — Fundamentos\" (mesma estrutura do app original, onde só existe\n * um nível \"de verdade\" e os demais são ciclos cumulativos dele).\n * Não há sistema de insígnias aqui (fora de escopo) — o status \"CONCLUÍDA\"\n * é calculado direto da % de aulas completas, não de insígnia conquistada.\n */\n\nconst ICONE_CADEADO_NIVEIS = '<rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"></rect><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"></path>';\n\nfunction nivelDesbloqueado(nivel) {\n  const ids = aulaIdsDoNivel(nivel);\n  if (ids.length === 0) return false;\n  const primeira = state.aulas.find(a => a.id === ids[0]);\n  return !!primeira && primeira.status !== 'locked';\n}\n\nfunction aulaIdsDoNivel(nivel) {\n  return (MODULOS || []).filter(m => nivel.etapas.includes(m.id)).flatMap(m => m.aulas.map(a => a.id));\n}\n\nfunction chipsDeEtapas(nivel) {\n  const etapas = (MODULOS || []).filter(m => nivel.etapas.includes(m.id));\n  const materias = [...new Set(etapas.map(e => e.materia).filter(Boolean))];\n  return materias.map(m => `<span class=\"sprint-materia-tag\">${escaparHtml(m)}</span>`).join('');\n}\n\nfunction nivelConcluido(nivel) {\n  const ids = aulaIdsDoNivel(nivel);\n  if (ids.length === 0) return false;\n  return ids.every(id => {\n    const a = state.aulas.find(x => x.id === id);\n    return a && a.status === 'completed';\n  });\n}\n\nfunction renderCicloSecao(nivel) {\n  if (!nivelDesbloqueado(nivel)) {\n    return `\n      <div class=\"ciclo-secao bloqueada\">\n        <span class=\"ciclo-secao-label bloqueada\">\n          <svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONE_CADEADO_NIVEIS}</svg>\n          Ciclo ${nivel.id} — Bloqueado\n        </span>\n      </div>`;\n  }\n\n  const ids = aulaIdsDoNivel(nivel);\n  const concluidas = ids.filter(id => {\n    const a = state.aulas.find(x => x.id === id);\n    return a && a.status === 'completed';\n  }).length;\n  const total = ids.length;\n  const pct = total > 0 ? Math.round((concluidas / total) * 100) : 0;\n  const concluida = nivelConcluido(nivel);\n  const statusClasse = concluida ? 'concluida' : 'andamento';\n  const statusTexto = concluida ? 'CONCLUÍDA' : 'EM ANDAMENTO';\n\n  return `\n    <div class=\"ciclo-secao\" data-nivel-id=\"${nivel.id}\">\n      <div class=\"ciclo-secao-cabecalho\">\n        <span class=\"ciclo-secao-label\">Ciclo ${nivel.id}</span>\n        <span class=\"sprint-status ${statusClasse}\">${statusTexto}</span>\n      </div>\n      <div class=\"sprint-etapas\">${chipsDeEtapas(nivel)}</div>\n      <div class=\"sprint-progress-row\">\n        <span class=\"sprint-progress-pct ${statusClasse}\">${pct}%</span>\n        <div class=\"sprint-progress-bar\"><div class=\"sprint-progress-bar-fill\" style=\"width:${pct}%\"></div></div>\n      </div>\n    </div>`;\n}\n\nfunction renderNiveis() {\n  const wrap = document.getElementById('niveisLista');\n  if (!wrap) return;\n  const niveis = NIVEIS || [];\n  const nivelPrincipal = niveis[0];\n\n  let nivelCardHtml = '';\n  if (nivelPrincipal) {\n    const ganhaTudo = niveis.length > 0 && niveis.every(nivelConcluido);\n    const statusClasse = ganhaTudo ? 'concluida' : 'andamento';\n\n    nivelCardHtml = `\n      <div class=\"nivel-card-unico\">\n        <div class=\"nivel-card-unico-cabecalho\">\n          <div class=\"sprint-card-numero ${statusClasse}\">\n            ${ganhaTudo\n              ? '<svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>'\n              : '01'}\n          </div>\n          <h3 class=\"sprint-titulo\">Nível 1 — Fundamentos</h3>\n          <svg class=\"nivel-card-unico-seta\" viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"#9ca3af\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"></polyline></svg>\n        </div>\n        <div class=\"nivel-card-unico-corpo\">\n          ${niveis.map(renderCicloSecao).join('')}\n        </div>\n      </div>`;\n  }\n\n  const trilhaHtml = `\n    <div class=\"trilha-section trilha-bloqueada\">\n      <div class=\"trilha-bloqueada-cabecalho\">\n        <svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONE_CADEADO_NIVEIS}</svg>\n        <h3 class=\"trilha-titulo\">Escolha sua trilha</h3>\n      </div>\n      <p class=\"trilha-desc\">Conclua a trilha básica (Nível 1) para escolher o concurso que você está estudando.</p>\n    </div>`;\n\n  wrap.innerHTML = `<div class=\"sprint-lista\">${nivelCardHtml}</div>${trilhaHtml}`;\n\n  wrap.querySelectorAll('.ciclo-secao:not(.bloqueada)').forEach(secao => {\n    secao.addEventListener('click', () => irParaNivel(parseInt(secao.dataset.nivelId, 10)));\n  });\n\n  wrap.querySelectorAll('.nivel-card-unico-cabecalho').forEach(cabecalho => {\n    cabecalho.addEventListener('click', () => {\n      cabecalho.classList.toggle('collapsed');\n      cabecalho.nextElementSibling?.classList.toggle('collapsed');\n    });\n  });\n}\n\nfunction irParaNivel(nivelId) {\n  const nivel = (NIVEIS || []).find(n => n.id === nivelId);\n  if (!nivel) return;\n\n  const paginas = { inicio: 'viewInicio', erros: 'viewErros', desempenho: 'viewDesempenho', niveis: 'viewNiveis' };\n  Object.entries(paginas).forEach(([nome, id]) => {\n    const el = document.getElementById(id);\n    if (el) el.style.display = nome === 'inicio' ? '' : 'none';\n  });\n  document.querySelectorAll('.nav-item').forEach(n => n.classList.toggle('active', n.dataset.view === 'inicio'));\n\n  setTimeout(() => {\n    const idsDoNivel = aulaIdsDoNivel(nivel);\n    const aulaAtiva = state.aulas.find(a => idsDoNivel.includes(a.id) && a.status === 'active');\n    let el = null;\n    if (aulaAtiva) {\n      el = document.querySelector(`[data-aula=\"${aulaAtiva.id}\"]`);\n      const etapaView = el?.closest('.etapa-view');\n      if (etapaView?._setColapsado) etapaView._setColapsado(false);\n    } else {\n      const etapaView = document.querySelector(`.etapa-view[data-etapa=\"${nivel.etapas[0]}\"]`);\n      if (etapaView?._setColapsado) etapaView._setColapsado(false);\n      el = etapaView;\n    }\n    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });\n  }, 50);\n}\n",
  "js/progresso.mjs": "'use strict';\n\n/**\n * PROGRESSO.JS — Substitui js/idb.js do projeto \"estudos\" original.\n * Mesma API pública (mesmos nomes de função, mesmas assinaturas async) que\n * estudo.js já espera — só troca onde o progresso é guardado: em vez de um\n * arquivo em uma pasta escolhida pelo usuário (File System Access API), usa\n * localStorage do navegador. Mais simples pra quem só quer estudar sem\n * configurar nada, ao custo de não sincronizar entre dispositivos/navegadores.\n */\nconst PROGRESSO_CHAVE = 'construtor-aulas-progresso';\n\nfunction lerArquivoProgressoSync() {\n  try {\n    const bruto = localStorage.getItem(PROGRESSO_CHAVE);\n    return bruto ? JSON.parse(bruto) : null;\n  } catch (e) {\n    return null;\n  }\n}\n\nasync function lerArquivoProgresso() {\n  return lerArquivoProgressoSync();\n}\n\nasync function gravarArquivoProgresso(mudancas) {\n  try {\n    const atual = lerArquivoProgressoSync() || {};\n    const dados = { ...atual, ...mudancas, savedAt: new Date().toISOString() };\n    localStorage.setItem(PROGRESSO_CHAVE, JSON.stringify(dados));\n    return true;\n  } catch (e) {\n    console.warn('Erro ao gravar progresso:', e);\n    return false;\n  }\n}\n\n// ── CADERNO DE ERROS (persistido junto com o progresso) ──────\nasync function getErrorNotebook() {\n  const dados = await lerArquivoProgresso();\n  return dados?.errosNotebook || {};\n}\n\nasync function addErro(aulaId, qIdx) {\n  const notebook = await getErrorNotebook();\n  const key = String(aulaId);\n  const set = new Set(notebook[key] || []);\n  set.add(qIdx);\n  notebook[key] = Array.from(set).sort((a, b) => a - b);\n\n  const recentes = await getErrosRecentes();\n  const jaExiste = recentes.findIndex(r => r.aulaId === key && r.chave === qIdx);\n  if (jaExiste !== -1) recentes.splice(jaExiste, 1);\n  recentes.push({ aulaId: key, chave: qIdx, quando: new Date().toISOString() });\n\n  await gravarArquivoProgresso({ errosNotebook: notebook, errosRecentes: recentes });\n  return notebook;\n}\n\nasync function getErrosRecentes() {\n  const dados = await lerArquivoProgresso();\n  return dados?.errosRecentes || [];\n}\n\n// ── CARTÕES MARCADOS PARA REVISÃO ─────────────────────────────\nasync function getCartoesMarcados() {\n  const dados = await lerArquivoProgresso();\n  return dados?.cartoesMarcados || {};\n}\n\nasync function alternarCartaoMarcado(aulaId, chave) {\n  const marcados = await getCartoesMarcados();\n  const key = String(aulaId);\n  const set = new Set(marcados[key] || []);\n  const marcando = !set.has(chave);\n  if (marcando) set.add(chave); else set.delete(chave);\n  marcados[key] = Array.from(set);\n  const salvou = await gravarArquivoProgresso({ cartoesMarcados: marcados });\n  return { marcando, salvou };\n}\n\n// ── INSÍGNIAS ──────────────────────────────────────────────────\nasync function getInsignias() {\n  const dados = await lerArquivoProgresso();\n  return dados?.insignias || [];\n}\n\nasync function conquistarInsignia(insigniaId) {\n  const atuais = await getInsignias();\n  if (atuais.includes(insigniaId)) return { nova: false, insignias: atuais };\n  const insignias = [...atuais, insigniaId];\n  await gravarArquivoProgresso({ insignias });\n  return { nova: true, insignias };\n}\n\n// ── SEMENTE DO SIMULADO ────────────────────────────────────────\nasync function getSimuladoSeed() {\n  const dados = await lerArquivoProgresso();\n  return dados?.simuladoSeed ?? null;\n}\nasync function definirSimuladoSeed(seed) { await gravarArquivoProgresso({ simuladoSeed: seed }); }\nasync function limparSimuladoSeed() { await gravarArquivoProgresso({ simuladoSeed: null }); }\n\n// ── TRILHA ESCOLHIDA ───────────────────────────────────────────\nasync function getTrilha() {\n  const dados = await lerArquivoProgresso();\n  return dados?.trilha || null;\n}\nasync function definirTrilha(trilhaId) { await gravarArquivoProgresso({ trilha: trilhaId }); }\n",
  "estudo.html": "<!DOCTYPE html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\r\n<title>{{APP_TITULO}}</title>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<link rel=\"stylesheet\" href=\"css/estudo.css\">\r\n<link rel=\"icon\" href=\"{{APP_FAVICON_HREF}}\">\r\n<meta name=\"theme-color\" content=\"{{APP_COR}}\">\r\n</head>\r\n<body>\r\n\r\n<div class=\"app-wrapper\">\r\n\r\n  <!-- HEADER -->\r\n  <header class=\"estudo-header\">\r\n    <button class=\"btn-fechar\" id=\"btnFechar\" title=\"Sair\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"20\" height=\"20\">\r\n        <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line>\r\n        <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line>\r\n      </svg>\r\n    </button>\r\n    <div class=\"header-info\">\r\n      <span class=\"questao-info\" id=\"questaoInfo\">Questão 1 de 5 • Aula 1: Aprenda o que é o verbo</span>\r\n      <div class=\"progress-segmentos\" id=\"progressSegmentos\"></div>\r\n    </div>\r\n  </header>\r\n\r\n  <!-- QUESTÃO -->\r\n  <div class=\"questao-wrap\">\r\n    <main class=\"questao-area\" id=\"questaoArea\">\r\n      <h2 class=\"questao-titulo\" id=\"questaoTitulo\"></h2>\r\n      <p class=\"questao-subtitulo\" id=\"questaoSubtitulo\"></p>\r\n      <div class=\"opcoes\" id=\"opcoes\"></div>\r\n    </main>\r\n    <div class=\"scroll-fade\" id=\"scrollFade\"></div>\r\n  </div>\r\n\r\n  <!-- FEEDBACK -->\r\n  <div class=\"feedback-bar\" id=\"feedbackBar\">\r\n    <div class=\"feedback-icon\" id=\"feedbackIcon\"></div>\r\n    <div class=\"feedback-texto\" id=\"feedbackTexto\"></div>\r\n  </div>\r\n\r\n  <!-- FOOTER -->\r\n  <footer class=\"estudo-footer\">\r\n    <button class=\"btn-anterior\" id=\"btnAnterior\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"15 18 9 12 15 6\"></polyline></svg>\r\n      Anterior\r\n    </button>\r\n    <button class=\"btn-proxima\" id=\"btnProxima\">\r\n      Próxima\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>\r\n    </button>\r\n  </footer>\r\n\r\n</div>\r\n\r\n<!-- MODAL LIÇÃO -->\r\n<div class=\"licao-overlay\" id=\"licaoOverlay\">\r\n  <div class=\"licao-card\">\r\n    <div class=\"licao-header\">\r\n      <h3 id=\"licaoHeader\">📖 Lição</h3>\r\n      <button class=\"licao-fechar\" id=\"licaoFechar\">✕</button>\r\n    </div>\r\n    <div class=\"licao-corpo\" id=\"licaoCorpo\"></div>\r\n    <button class=\"licao-btn-fechar\" id=\"licaoBtnFechar\">Entendido</button>\r\n  </div>\r\n</div>\r\n\r\n<!-- MODAL RESULTADO -->\r\n<div class=\"resultado-overlay\" id=\"resultadoOverlay\">\r\n  <div class=\"resultado-card\">\r\n    <div class=\"resultado-emoji\" id=\"resultadoEmoji\">🎉</div>\r\n    <h2 class=\"resultado-titulo\" id=\"resultadoTitulo\">Aula concluída!</h2>\r\n    <p class=\"resultado-desc\" id=\"resultadoDesc\"></p>\r\n    <div class=\"resultado-estrelas\" id=\"resultadoEstrelas\"></div>\r\n    <button class=\"resultado-btn-continuar\" id=\"resultadoBtnContinuar\">Voltar ao início</button>\r\n  </div>\r\n</div>\r\n\r\n<script src=\"js/progresso.mjs\"></script>\r\n<script src=\"js/data/modulos.mjs\"></script>\r\n<script src=\"js/estudo.mjs\"></script>\r\n</body>\r\n</html>\r\n",
  "css/estudo.css": "/* Cor de marca em variáveis — o export injeta um :root{} novo no final do\n   arquivo com a cor escolhida no Construtor de Aulas (ver js/export.js). */\n:root {\n  --cor-primaria: #5B2BCB;\n  --cor-primaria-rgb: 91,43,203;\n  --cor-primaria-escura: #4a22a8;\n  --cor-gradiente-1: #8E5CF5;\n  --cor-gradiente-2: #6D2EE8;\n  --cor-clara: #f0eaff;\n  --cor-borda-clara: #e9dffb;\n  --cor-borda-media: #d4c4f0;\n  --cor-hover-fundo: #faf7ff;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  font-family: 'Inter', sans-serif;\n}\n\nbody {\n  background: #f4f0ff;\n  min-height: 100vh;\n}\n\n.app-wrapper {\n  max-width: 700px;\n  width: 100%;\n  margin: 0 auto;\n  background: #ffffff;\n  height: 100vh;   /* fallback para navegadores antigos */\n  height: 100dvh;  /* viewport dinâmico */\n  height: 100svh;  /* viewport \"pequeno\" garantido — evita que a barra de\n                       gestos do sistema (comum no PWA instalado) corte o\n                       rodapé com os botões Anterior/Próxima */\n  display: flex;\n  flex-direction: column;\n  box-shadow: 0 0 60px rgba(91, 43, 203, 0.15);\n  overflow: hidden;\n}\n\n/* HEADER */\n.estudo-header {\n  background: var(--cor-primaria);\n  padding: 16px 20px 14px;\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n}\n\n.btn-fechar {\n  background: rgba(255,255,255,0.2);\n  border: none;\n  border-radius: 50%;\n  width: 36px;\n  height: 36px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  color: white;\n  flex-shrink: 0;\n  transition: background 0.2s;\n}\n.btn-fechar:hover { background: rgba(255,255,255,0.3); }\n\n.header-info {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.questao-info {\n  color: rgba(255,255,255,0.9);\n  font-size: 14px;\n  font-weight: 500;\n}\n\n.progress-segmentos {\n  display: flex;\n  gap: 4px;\n}\n\n.seg {\n  flex: 1;\n  height: 5px;\n  border-radius: 3px;\n  background: rgba(255,255,255,0.3);\n  transition: background 0.4s ease;\n}\n\n.seg.respondida { background: #fff; }\n.seg.atual      { background: rgba(255,255,255,0.7); }\n\n/* TAGS */\n.tags-row {\n  display: flex;\n  gap: 8px;\n  padding: 14px 20px 0;\n}\n\n.tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 6px 12px;\n  border-radius: 20px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.tag-dificuldade {\n  background: var(--cor-clara);\n  color: var(--cor-primaria);\n}\n\n.tag-consultar {\n  background: var(--cor-clara);\n  color: var(--cor-primaria);\n  transition: background 0.2s;\n}\n.tag-consultar:hover { background: var(--cor-borda-media); }\n\n/* QUESTÃO */\n.questao-wrap {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n}\n\n.questao-area {\n  height: 100%;\n  overflow-y: auto;\n  padding: 24px 20px 12px;\n}\n\n.scroll-fade {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  height: 64px;\n  background: linear-gradient(to bottom, transparent, #ffffff);\n  pointer-events: none;\n  opacity: 1;\n  transition: opacity 0.3s;\n}\n\n.scroll-fade.oculto {\n  opacity: 0;\n}\n\n.questao-titulo {\n  font-size: 21px;\n  font-weight: 700;\n  color: #1a1a2e;\n  margin-bottom: 6px;\n  line-height: 1.3;\n}\n\n.questao-subtitulo {\n  font-size: 15px;\n  color: #6b7280;\n  margin-bottom: 24px;\n}\n\n/* TELA DE CHECAGEM — pergunta curta em negrito antes do título grande */\n/* padding-right reserva espaço pro .btn-marcar-cartao (marca-página\n   absoluto no canto superior direito) não sobrepor o texto quando ele\n   quebra em duas linhas em telas estreitas. */\n.checagem-pergunta {\n  font-weight: 700;\n  margin-bottom: 6px;\n  padding-right: 48px;\n}\n\n.checagem-titulo {\n  margin-bottom: 24px;\n}\n\n/* Perguntas de \"o verbo em destaque indica\" — instrução menor,\n   frase analisada maior (é o que realmente importa ler com atenção). */\n.checagem-instrucao {\n  font-size: 16px;\n  padding-right: 48px;\n}\n\n.checagem-frase {\n  font-size: 19px;\n  font-weight: 400;\n  color: #1a1a2e;\n}\n\n.checagem-frase strong {\n  font-weight: 700;\n  color: #4A80F0;\n}\n\n/* TELA DE INTRODUÇÃO (Antes de começar) */\n.intro-label {\n  display: block;\n  font-size: 12px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: #4A80F0;\n  margin-bottom: 8px;\n}\n\n.intro-titulo {\n  font-size: 32px;\n  font-weight: 800;\n  color: #1a1a2e;\n  line-height: 1.25;\n  margin-bottom: 14px;\n}\n\n.intro-desc {\n  font-size: 16px;\n  color: #4b5563;\n  line-height: 1.6;\n  margin-bottom: 28px;\n  text-align: justify;\n}\n\n.intro-info {\n  background: #f5f8ff;\n  border: 1.5px solid #d9e6fc;\n  border-radius: 18px;\n  padding: 22px 20px;\n}\n\n.intro-info-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 16px;\n}\n\n.intro-info-item + .intro-info-item {\n  margin-top: 20px;\n  padding-top: 20px;\n  border-top: 1px solid #d9e6fc;\n}\n\n.intro-info-icone-wrap {\n  width: 52px;\n  height: 52px;\n  border-radius: 50%;\n  background: #eef2ff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.intro-info-texto h3 {\n  font-size: 16px;\n  font-weight: 700;\n  color: #4A80F0;\n  margin-bottom: 6px;\n}\n\n.intro-info-texto p {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.6;\n  text-align: justify;\n}\n\n/* TELA DE DEFINIÇÃO */\n.definicao-card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 24px;\n  padding: 32px 20px;\n  text-align: center;\n  position: relative;\n}\n\n/* ETIQUETA \"MARCAR PARA REVISÃO\" — marca-página no lado esquerdo das\n   telas de conteúdo (definição, contexto, exemplo). */\n.btn-marcar-cartao {\n  position: absolute;\n  top: -6px;\n  right: 10px;\n  width: 36px;\n  height: 44px;\n  padding: 0;\n  background: #ffffff;\n  border: 2px solid #dbe4fb;\n  border-top: none;\n  border-radius: 0 0 8px 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  color: #b9c6f0;\n  z-index: 2;\n  transition: color 0.2s, transform 0.15s;\n}\n\n.btn-marcar-cartao:hover {\n  color: #4A80F0;\n  transform: translateY(1px);\n}\n\n.btn-marcar-cartao svg {\n  width: 19px;\n  height: 19px;\n}\n\n.btn-marcar-cartao.marcada {\n  color: #4A80F0;\n}\n\n.btn-marcar-cartao.marcada svg {\n  fill: #4A80F0;\n}\n\n.definicao-icone-wrap {\n  width: 88px;\n  height: 88px;\n  background: #eef2ff;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.definicao-texto {\n  font-size: 16px;\n  font-weight: 600;\n  color: #1a1a2e;\n  line-height: 1.6;\n  max-width: 300px;\n}\n\n.destaque {\n  color: #4A80F0;\n  font-weight: 700;\n}\n\n/* TELA DE CONTEXTO */\n.contexto-card {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 8px 4px;\n  position: relative;\n}\n\n.contexto-icone-wrap {\n  width: 80px;\n  height: 80px;\n  background: #eef2ff;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  align-self: center;\n}\n\n.contexto-texto {\n  font-size: 16px;\n  font-weight: 500;\n  color: #1a1a2e;\n  line-height: 1.65;\n  text-align: justify;\n}\n\n.contexto-texto strong { font-weight: 700; }\n\n.contexto-nota {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  background: #f1f5f9;\n  border-radius: 12px;\n  padding: 14px 16px;\n}\n\n.contexto-nota svg { flex-shrink: 0; margin-top: 1px; }\n\n.contexto-nota span {\n  font-size: 15px;\n  color: #475569;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n/* TELA DE EXEMPLO */\n.exemplo-card {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 8px 4px;\n  position: relative;\n}\n\n/* Filho de um flex column sem min-width:0 não deixa o overflow-x:auto (ver\n   .frase-anotada-wrap) funcionar — o item cresce pra caber a frase inteira\n   em vez de encolher e deixar rolar, empurrando a caixa pra fora da tela no\n   celular. Aplica em .exemplo-card (telas de exemplo) e .opcoes (telas de\n   checagem), pra cobrir qualquer frase, em qualquer tela, sem precisar\n   lembrar disso de novo a cada caixa nova. */\n.exemplo-card > *,\n.opcoes > * {\n  min-width: 0;\n}\n\n.exemplo-icone-wrap {\n  width: 88px;\n  height: 88px;\n  background: #eef2ff;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  align-self: center;\n}\n\n.exemplo-texto {\n  font-size: 16px;\n  color: #1a1a2e;\n  line-height: 1.65;\n  text-align: justify;\n}\n\n.exemplo-conclusao {\n  font-size: 16px;\n  font-weight: 700;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n.exemplo-pontos {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.exemplo-ponto {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.exemplo-ponto-icone {\n  width: 46px;\n  height: 46px;\n  border-radius: 50%;\n  background: #eef2ff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.exemplo-ponto-texto {\n  font-size: 16px;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: left;\n}\n\n/* TELA DE \"PASSO\" (numerado) — Como encontrar o sujeito, etc. */\n.passo-linha {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.passo-numero {\n  width: 40px;\n  height: 40px;\n  border-radius: 50%;\n  background: #eef2ff;\n  color: #4A80F0;\n  font-weight: 700;\n  font-size: 16px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.passo-instrucao {\n  font-size: 16px;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: left;\n}\n\n.passo-caixa {\n  background: #f5f7ff;\n  border-radius: 16px;\n  padding: 16px;\n}\n\n.passo-caixa-cabecalho {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.passo-caixa-icone {\n  width: 40px;\n  height: 40px;\n  border-radius: 50%;\n  background: #e6ebff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.passo-caixa-inline {\n  font-size: 15px;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: left;\n}\n\n.passo-caixa-corpo {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.passo-caixa-titulo {\n  font-size: 14px;\n  font-weight: 700;\n  color: #1a1a2e;\n}\n\n.passo-caixa-texto {\n  font-size: 15px;\n  color: #1a1a2e;\n  line-height: 1.4;\n}\n\n/* Citação de exemplo em itálico (ex: \"→ João comprou um livro.\") — um\n   pouco menor que o texto normal da caixa, que fica largo/pesado nesse uso. */\n.passo-caixa-texto em {\n  font-size: 13px;\n}\n\n.passo-caixa-divisor {\n  height: 1px;\n  background: #dde3f5;\n  margin: 12px 0;\n}\n\n.passo-caixa-perguntas {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* Checklist de perguntas sim/não dentro de um passo de exemplo (ex: \"o\n   verbo destacado é haver? é fazer? é fenômeno da natureza?\"). */\n.simnao-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.simnao-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.simnao-texto {\n  font-size: 14px;\n  color: #1a1a2e;\n  line-height: 1.4;\n  flex: 1;\n}\n\n.simnao-botoes {\n  display: flex;\n  gap: 6px;\n  flex-shrink: 0;\n}\n\n.simnao-btn {\n  padding: 6px 14px;\n  border: 2px solid var(--cor-borda-clara);\n  border-radius: 10px;\n  background: #ffffff;\n  font-size: 13px;\n  font-weight: 700;\n  color: #1a1a2e;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s, color 0.15s;\n}\n\n.simnao-btn:hover:not(:disabled):not(.correta) {\n  border-color: var(--cor-primaria);\n  background: var(--cor-hover-fundo);\n  color: var(--cor-primaria);\n}\n\n.simnao-btn.correta {\n  border-color: #16a34a;\n  background: #f0fdf4;\n  color: #16a34a;\n}\n\n.simnao-btn.errada {\n  border-color: #dc2626;\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.simnao-btn:disabled:not(.correta) {\n  opacity: 0.55;\n  cursor: default;\n}\n\n.passo-caixa-seta {\n  font-size: 15px;\n  color: #1a1a2e;\n  line-height: 1.4;\n  text-align: left;\n}\n\n/* Linha de exemplo dentro das perguntas, sem a seta \"→\" — só indentada\n   pra se alinhar com o texto das linhas com seta acima/abaixo dela. */\n.passo-caixa-nota-indent {\n  font-size: 15px;\n  color: #1a1a2e;\n  line-height: 1.4;\n  text-align: left;\n  padding-left: 20px;\n}\n\n.passo-nota {\n  font-size: 16px;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: left;\n  margin: 6px 0 0 54px;\n}\n\n.passo-caixa-resposta {\n  font-size: 15px;\n  color: #1a1a2e;\n  text-align: left;\n}\n\n.passo-caixa-resposta strong {\n  color: #4A80F0;\n}\n\n/* TELA DE INFINITIVO */\n.infinitivo-card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 18px;\n  text-align: center;\n}\n\n.infinitivo-icone-wrap {\n  width: 90px;\n  height: 90px;\n  border-radius: 50%;\n  background: #eff6ff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.infinitivo-icone-simbolo {\n  font-size: 44px;\n  font-weight: 700;\n  color: #2563eb;\n  line-height: 1;\n  font-family: Arial, sans-serif;\n}\n\n.infinitivo-descricao {\n  font-size: 19px;\n  font-weight: 700;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n.infinitivo-nota {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n.infinitivo-conj-titulo {\n  font-size: 17px;\n  font-weight: 700;\n  color: #1a1a2e;\n  text-align: center;\n  margin-top: 4px;\n}\n\n.infinitivo-conjs {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  width: 100%;\n}\n\n.infinitivo-conj-card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  background: #ffffff;\n  border: 1.5px solid #e2e8f0;\n  border-radius: 14px;\n  padding: 14px 16px;\n}\n\n.infinitivo-conj-sufixo {\n  font-size: 27px;\n  font-weight: 700;\n  color: #2563eb;\n}\n\n.infinitivo-conj-label {\n  font-size: 14px;\n  color: #64748b;\n}\n\n.infinitivo-extra {\n  font-size: 16px;\n  font-weight: 600;\n  color: #1a1a2e;\n  line-height: 1.6;\n  text-align: justify;\n  background: #eff6ff;\n  border-left: 3px solid #2563eb;\n  border-radius: 10px;\n  padding: 12px 14px;\n}\n\n/* TELA DE RESUMO */\n.resumo-card {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.resumo-titulo {\n  font-size: 18px;\n  font-weight: 700;\n  color: #1a1a2e;\n  margin-bottom: 4px;\n}\n\n.resumo-item {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  background: #fafafa;\n  border: 1px solid var(--cor-clara);\n  border-radius: 14px;\n  padding: 12px 14px;\n}\n\n.resumo-icone {\n  width: 46px;\n  height: 46px;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.resumo-item-info {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.resumo-item-titulo {\n  font-size: 16px;\n  font-weight: 700;\n}\n\n.resumo-item-exemplos {\n  font-size: 14px;\n  color: #64748b;\n}\n\n/* TELA DE IDENTIFICAÇÃO */\n.idf-card {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.idf-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n}\n\n.idf-icone-wrap {\n  width: 52px;\n  height: 52px;\n  border-radius: 14px;\n  background: #eff6ff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.idf-titulo {\n  font-size: 19px;\n  font-weight: 700;\n  color: #1a1a2e;\n  line-height: 1.4;\n  padding-top: 4px;\n}\n\n.idf-intro {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n.idf-exemplos {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.idf-exemplo-card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 3px;\n  background: #ffffff;\n  border: 1.5px solid #e2e8f0;\n  border-radius: 14px;\n  padding: 12px 16px;\n}\n\n.idf-palavra {\n  font-size: 18px;\n  font-weight: 700;\n  color: #2563eb;\n}\n\n.idf-linha {\n  font-size: 14px;\n  color: #64748b;\n}\n\n.idf-rodape {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.6;\n  text-align: justify;\n}\n\n/* TELA DE SENTIDO */\n.sentido-card {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.sentido-dica {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  background: #fefce8;\n  border: 1.5px solid #fde68a;\n  border-radius: 14px;\n  padding: 12px 14px;\n  font-size: 16px;\n  font-weight: 600;\n  color: #1a1a2e;\n  line-height: 1.5;\n  text-align: justify;\n}\n\n.sentido-dica-icone {\n  font-size: 20px;\n  flex-shrink: 0;\n  margin-top: 1px;\n}\n\n.sentido-texto {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.6;\n  text-align: justify;\n}\n\n.sentido-exemplos-titulo {\n  font-size: 17px;\n  font-weight: 700;\n  color: #1a1a2e;\n  margin-top: 4px;\n}\n\n.sentido-exemplos {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.sentido-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n}\n\n.sentido-item-texto {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.sentido-item-frase {\n  font-size: 15px;\n  color: #1a1a2e;\n  line-height: 1.4;\n}\n\n.sentido-item-cadeia {\n  font-size: 14px;\n  color: #64748b;\n  line-height: 1.4;\n}\n\n/* OPÇÕES */\n.opcoes {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  position: relative;\n}\n\n.opcao {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 16px;\n  border: 2px solid var(--cor-borda-clara);\n  border-radius: 14px;\n  cursor: pointer;\n  transition: all 0.2s;\n  background: white;\n  text-align: left;\n  width: 100%;\n}\n\n.opcao:hover:not(:disabled) {\n  border-color: var(--cor-primaria);\n  background: var(--cor-hover-fundo);\n}\n\n.opcao.selecionada {\n  border-color: var(--cor-primaria);\n  background: var(--cor-clara);\n}\n\n.opcao.correta {\n  border-color: #16a34a;\n  background: #f0fdf4;\n}\n\n.opcao.errada {\n  border-color: #dc2626;\n  background: #fef2f2;\n}\n\n.opcao:disabled { cursor: default; }\n\n.letra {\n  width: 36px;\n  height: 36px;\n  border-radius: 50%;\n  border: 2px solid var(--cor-borda-media);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 15px;\n  color: var(--cor-primaria);\n  flex-shrink: 0;\n  transition: all 0.2s;\n}\n\n.opcao.selecionada .letra {\n  background: var(--cor-primaria);\n  border-color: var(--cor-primaria);\n  color: white;\n}\n\n.opcao.correta .letra {\n  background: #16a34a;\n  border-color: #16a34a;\n  color: white;\n}\n\n.opcao.errada .letra {\n  background: #dc2626;\n  border-color: #dc2626;\n  color: white;\n}\n\n.opcao-texto {\n  font-size: 16px;\n  color: #1a1a2e;\n  font-weight: 500;\n  line-height: 1.4;\n}\n\n/* CHECAGEM DO TIPO \"CLIQUE NA PALAVRA\" */\n.sentence-display {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  margin-top: 4px;\n}\n\n.word-chip {\n  display: inline-flex;\n  align-items: center;\n  padding: 8px 12px;\n  border: 2px solid var(--cor-borda-clara);\n  border-radius: 12px;\n  background: #ffffff;\n  font-size: 14px;\n  font-weight: 600;\n  color: #1a1a2e;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s, color 0.15s;\n  user-select: none;\n}\n\n.word-chip:hover:not(:disabled):not(.pontuacao):not(.correta):not(.errada):not(.verbo-pendente):not(.sujeito-pendente):not(.predicado-pendente):not(.verbo-correto):not(.sujeito-correto):not(.predicado-correto):not(.verbo-errado):not(.sujeito-errado):not(.predicado-errado):not(.auxiliar-correto):not(.principal-correto) {\n  border-color: var(--cor-primaria);\n  background: var(--cor-hover-fundo);\n  color: var(--cor-primaria);\n}\n\n.word-chip.correta {\n  border-color: #16a34a;\n  background: #f0fdf4;\n  color: #16a34a;\n}\n\n.word-chip.errada {\n  border-color: #dc2626;\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.word-chip:disabled:not(.correta):not(.errada):not(.verbo-correto):not(.sujeito-correto):not(.predicado-correto):not(.auxiliar-correto):not(.principal-correto) {\n  opacity: 0.55;\n  cursor: default;\n}\n\n.word-chip.pontuacao {\n  border: none;\n  background: transparent;\n  padding: 8px 2px;\n  cursor: default;\n  color: #1a1a2e;\n}\n\n.sentence-display-sm {\n  margin-top: 8px;\n}\n\n.word-chip-sm {\n  padding: 6px 12px;\n  font-size: 14px;\n  border-radius: 10px;\n}\n\n/* Caixa de exemplo estático (sentencaAnotada) — frase só de referência,\n   já com os papéis marcados, sem interação. Um pouco mais compacta que os\n   chips clicáveis, que precisam ficar maiores por serem alvo de toque. */\n#exemploCaixaAnotada .word-chip-sm {\n  padding: 4px 9px;\n  font-size: 12px;\n}\n\n/* CHECAGEM DO TIPO \"CLIQUE NO VERBO E NO SUJEITO\" (duplo-select) */\n.dual-select-wrap {\n  margin-top: 4px;\n}\n\n/* CHECAGEM DO TIPO \"REESCREVA NA ORDEM DIRETA\" (banco de palavras) */\n.reordenar-wrap {\n  margin-top: 4px;\n}\n\n.reordenar-referencia {\n  background: #f5f7ff;\n  border-radius: 12px;\n  padding: 10px 14px;\n  margin-bottom: 14px;\n}\n\n.reordenar-referencia-label {\n  font-size: 12px;\n  font-weight: 700;\n  color: #6b7280;\n  margin-bottom: 2px;\n}\n\n.reordenar-referencia-texto {\n  font-size: 15px;\n  font-weight: 600;\n  color: #1a1a2e;\n}\n\n.reordenar-resposta {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  min-height: 46px;\n  padding: 10px;\n  border: 2px dashed #d8ccf5;\n  border-radius: 12px;\n  margin-bottom: 16px;\n}\n\n.reordenar-resposta-final {\n  border-style: solid;\n  border-color: var(--cor-borda-clara);\n}\n\n.reordenar-banco {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 18px;\n}\n\n.modo-toggle {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 14px;\n}\n\n.modo-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 16px;\n  border-radius: 10px;\n  border: 2px solid var(--cor-borda-clara);\n  background: #ffffff;\n  font-size: 13px;\n  font-weight: 700;\n  color: #6b7280;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s, color 0.15s;\n}\n\n.modo-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  flex-shrink: 0;\n}\n\n.modo-dot-verbo     { background: #2563eb; }\n.modo-dot-sujeito   { background: #dc2626; }\n.modo-dot-predicado { background: var(--cor-primaria); }\n\n.modo-btn.ativo-verbo {\n  border-color: #2563eb;\n  background: #eff6ff;\n  color: #2563eb;\n}\n\n.modo-btn.ativo-sujeito {\n  border-color: #dc2626;\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.modo-btn.ativo-predicado {\n  border-color: var(--cor-primaria);\n  background: #f5f0ff;\n  color: var(--cor-primaria);\n}\n\n/* Botão \"Oração sem sujeito\" da checagem tripla — declaração explícita do\n   aluno de que a frase não tem sujeito (necessário pra liberar o \"Confirmar\n   resposta\" em frases impessoais, que não têm nenhuma palavra pra marcar). */\n.modo-sem-sujeito-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 14px;\n  border-radius: 10px;\n  border: 2px solid var(--cor-borda-clara);\n  background: #ffffff;\n  font-size: 12px;\n  font-weight: 700;\n  color: #6b7280;\n  cursor: pointer;\n  margin-bottom: 14px;\n  transition: border-color 0.15s, background 0.15s, color 0.15s;\n}\n\n.modo-sem-sujeito-btn.ativo {\n  border-color: #ea580c;\n  background: #fff7ed;\n  color: #ea580c;\n}\n\n.frase-anotada-wrap {\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n  margin-bottom: 16px;\n}\n\n/* Quando a frase é larga demais pra tela, o wrap acima já deixa arrastar\n   pro lado — mas sem nenhuma pista visual isso parecia palavra \"sumida\"\n   (cortada na borda). .tem-overflow é ligada via JS (marcarOverflowHorizontal\n   em estudo.js) só quando o conteúdo realmente não cabe inteiro, e desenha\n   um degradê na borda direita pra indicar que dá pra arrastar. Usa\n   mask-image (esmaece o próprio conteúdo) em vez de sobrepor uma cor, pra\n   funcionar igual em qualquer fundo (caixa azulada ou tela branca).  */\n.frase-anotada-wrap.tem-overflow {\n  -webkit-mask-image: linear-gradient(to right, black calc(100% - 28px), transparent 100%);\n  mask-image: linear-gradient(to right, black calc(100% - 28px), transparent 100%);\n}\n\n.frase-anotada {\n  display: inline-grid;\n  column-gap: 8px;\n  row-gap: 4px;\n  align-items: end;\n  grid-template-rows: auto minmax(38px, auto) minmax(38px, auto);\n}\n\n.word-chip.verbo-pendente {\n  border-color: #2563eb;\n  background: #eff6ff;\n  color: #2563eb;\n}\n\n.word-chip.sujeito-pendente {\n  border-color: #dc2626;\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.word-chip.verbo-correto {\n  border-color: #2563eb;\n  background: #eff6ff;\n  color: #1d4ed8;\n}\n\n.word-chip.sujeito-correto {\n  border-color: #dc2626;\n  background: #fef2f2;\n  color: #dc2626;\n}\n\n.word-chip.verbo-errado,\n.word-chip.sujeito-errado,\n.word-chip.predicado-errado {\n  border-color: #9ca3af;\n  background: #f9fafb;\n  color: #6b7280;\n  text-decoration: line-through;\n}\n\n.word-chip.predicado-pendente {\n  border-color: var(--cor-primaria);\n  background: #f5f0ff;\n  color: var(--cor-primaria);\n}\n\n.word-chip.predicado-correto {\n  border-color: var(--cor-primaria);\n  background: #f5f0ff;\n  color: var(--cor-primaria);\n}\n\n.word-chip.auxiliar-correto {\n  border-color: #2563eb;\n  background: #eff6ff;\n  color: #1d4ed8;\n}\n\n.word-chip.principal-correto {\n  border-color: #16a34a;\n  background: #dcfce7;\n  color: #15803d;\n}\n\n.anotacao-verbo,\n.anotacao-sujeito,\n.anotacao-predicado,\n.anotacao-auxiliar,\n.anotacao-principal {\n  position: relative;\n  grid-row: 2;\n  text-align: center;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  padding: 5px 6px 3px;\n  margin-top: 14px;\n  border-top: 2px solid currentColor;\n  white-space: nowrap;\n}\n\n.anotacao-verbo::before, .anotacao-verbo::after,\n.anotacao-sujeito::before, .anotacao-sujeito::after,\n.anotacao-predicado::before, .anotacao-predicado::after,\n.anotacao-auxiliar::before, .anotacao-auxiliar::after,\n.anotacao-principal::before, .anotacao-principal::after {\n  content: '';\n  position: absolute;\n  top: -14px;\n  width: 2px;\n  height: 14px;\n  background: currentColor;\n}\n\n.anotacao-verbo::before,   .anotacao-sujeito::before,   .anotacao-predicado::before,   .anotacao-auxiliar::before,   .anotacao-principal::before { left: 0; }\n.anotacao-verbo::after,    .anotacao-sujeito::after,    .anotacao-predicado::after,    .anotacao-auxiliar::after,    .anotacao-principal::after  { right: 0; }\n.anotacao-verbo      { color: #2563eb; }\n.anotacao-sujeito    { color: #dc2626; }\n.anotacao-predicado  { color: var(--cor-primaria); grid-row: 3; }\n.anotacao-auxiliar   { color: #2563eb; }\n.anotacao-principal  { color: #16a34a; }\n\n.btn-confirmar-duplo {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 12px 22px;\n  border-radius: 12px;\n  border: none;\n  background: var(--cor-primaria);\n  color: #fff;\n  font-size: 15px;\n  font-weight: 700;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.btn-confirmar-duplo:disabled {\n  background: #e5e7eb;\n  color: #9ca3af;\n  cursor: not-allowed;\n}\n\n/* RESULTADO DE CADA PALAVRA (depois de responder a checagem de \"clique na palavra\") */\n.checagem-resultado-itens {\n  margin-top: 24px;\n  padding-top: 16px;\n  border-top: 2px solid #efe9fb;\n}\n\n.checagem-resultado-titulo {\n  font-size: 12px;\n  font-weight: 800;\n  color: #1a1a2e;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  padding: 6px 10px;\n  background: #f4f0ff;\n  border-radius: 6px;\n  display: inline-block;\n  margin-bottom: 12px;\n}\n\n.checagem-resultado-lista {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.checagem-resultado-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 14px;\n  padding: 6px 4px;\n}\n\n.checagem-resultado-item.errada-selecionada {\n  background: #fef2f2;\n  border-radius: 8px;\n  padding: 6px 8px;\n}\n\n.cri-palavra {\n  font-size: 15px;\n  font-weight: 800;\n  min-width: 90px;\n  color: #1a1a2e;\n}\n\n.cri-palavra.correta { color: #16a34a; }\n.cri-palavra.errada  { color: #dc2626; }\n\n.cri-seta {\n  color: #9ca3af;\n  font-size: 14px;\n  flex-shrink: 0;\n}\n\n.cri-classe { font-weight: 500; color: #6b7280; }\n.cri-classe.correta { color: #16a34a; font-weight: 600; }\n.cri-classe.errada  { color: #dc2626; font-weight: 700; }\n\n.cri-icone {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  font-size: 15px;\n}\n\n/* FEEDBACK */\n.feedback-bar {\n  margin: 12px 20px;\n  padding: 14px 16px;\n  border-radius: 14px;\n  display: none;\n  align-items: center;\n  gap: 12px;\n}\n\n.feedback-bar.show { display: flex; }\n\n.feedback-bar.acerto {\n  background: #f0fdf4;\n  border: 2px solid #86efac;\n}\n\n.feedback-bar.erro {\n  background: #fef2f2;\n  border: 2px solid #fca5a5;\n}\n\n.feedback-icon { font-size: 22px; }\n\n.feedback-texto {\n  font-size: 15px;\n  line-height: 1.4;\n  text-align: justify;\n}\n\n.feedback-titulo {\n  display: block;\n  font-weight: 700;\n  margin-bottom: 8px;\n}\n\n.feedback-explicacao {\n  display: block;\n  font-weight: 400;\n}\n\n.feedback-correta {\n  display: block;\n  font-weight: 700;\n  margin-top: 8px;\n}\n\n.feedback-bar.acerto .feedback-texto { color: #16a34a; }\n.feedback-bar.erro .feedback-texto   { color: #dc2626; }\n\n/* FOOTER */\n.estudo-footer {\n  flex-shrink: 0;\n  padding: 14px 20px calc(24px + env(safe-area-inset-bottom, 0px));\n  display: flex;\n  gap: 10px;\n  background: #ffffff;\n}\n\n.btn-anterior {\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 14px 16px;\n  background: white;\n  border: 1.5px solid var(--cor-borda-media);\n  border-radius: 14px;\n  color: var(--cor-primaria);\n  font-weight: 600;\n  font-size: 16px;\n  cursor: pointer;\n  transition: background 0.2s;\n}\n.btn-anterior:hover { background: var(--cor-hover-fundo); }\n.btn-anterior:disabled { opacity: 0.35; cursor: default; }\n\n.btn-proxima {\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 14px 16px;\n  background: var(--cor-primaria);\n  border: none;\n  border-radius: 14px;\n  color: white;\n  font-weight: 600;\n  font-size: 16px;\n  cursor: pointer;\n  transition: background 0.2s;\n}\n.btn-proxima:hover { background: var(--cor-primaria-escura); }\n.btn-proxima:disabled { background: var(--cor-borda-media); cursor: default; }\n\n/* MODAL LIÇÃO */\n.licao-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0,0,0,0.5);\n  display: flex;\n  align-items: flex-end;\n  justify-content: center;\n  z-index: 500;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity 0.3s;\n}\n.licao-overlay.show {\n  opacity: 1;\n  pointer-events: all;\n}\n\n.licao-card {\n  background: white;\n  border-radius: 24px 24px 0 0;\n  padding: 24px 24px 36px;\n  width: 100%;\n  max-width: 600px;\n  transform: translateY(100%);\n  transition: transform 0.35s ease;\n}\n.licao-overlay.show .licao-card { transform: translateY(0); }\n\n.licao-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n.licao-header h3 { font-size: 19px; font-weight: 700; color: #1a1a2e; }\n\n.licao-fechar {\n  background: #f3f4f6;\n  border: none;\n  border-radius: 50%;\n  width: 32px;\n  height: 32px;\n  font-size: 15px;\n  cursor: pointer;\n  color: #6b7280;\n}\n\n.licao-corpo {\n  font-size: 16px;\n  color: #374151;\n  line-height: 1.7;\n}\n.licao-corpo ul { padding-left: 20px; margin: 10px 0; }\n.licao-corpo p  { margin-bottom: 8px; text-align: justify; }\n.licao-corpo li { text-align: justify; }\n\n.licao-btn-fechar {\n  margin-top: 20px;\n  width: 100%;\n  padding: 14px;\n  background: var(--cor-primaria);\n  color: white;\n  border: none;\n  border-radius: 14px;\n  font-weight: 600;\n  font-size: 16px;\n  cursor: pointer;\n}\n\n/* MODAL RESULTADO */\n.resultado-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0,0,0,0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 500;\n  padding: 20px;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity 0.3s;\n}\n.resultado-overlay.show {\n  opacity: 1;\n  pointer-events: all;\n}\n\n.resultado-card {\n  background: white;\n  border-radius: 24px;\n  padding: 36px 28px;\n  text-align: center;\n  max-width: 340px;\n  width: 100%;\n  transform: scale(0.9);\n  transition: transform 0.3s ease;\n}\n.resultado-overlay.show .resultado-card { transform: scale(1); }\n\n.resultado-emoji { font-size: 56px; margin-bottom: 16px; }\n.resultado-titulo { font-size: 23px; font-weight: 700; color: #1a1a2e; margin-bottom: 10px; }\n.resultado-desc   { font-size: 15px; color: #6b7280; margin-bottom: 20px; line-height: 1.6; }\n\n.resultado-estrelas { font-size: 32px; margin-bottom: 24px; }\n\n.resultado-btn-continuar {\n  width: 100%;\n  padding: 14px;\n  background: var(--cor-primaria);\n  color: white;\n  border: none;\n  border-radius: 14px;\n  font-weight: 600;\n  font-size: 16px;\n  cursor: pointer;\n  transition: background 0.2s;\n}\n.resultado-btn-continuar:hover { background: var(--cor-primaria-escura); }\n\n@media (min-width: 768px) {\n  body { background: #f4f0ff; }\n}\n\n/* Ajuste fino em telas bem estreitas, para o texto justificado não ficar apertado */\n@media (max-width: 380px) {\n  .intro-titulo             { font-size: 27px; }\n  .intro-desc,\n  .intro-info-texto p,\n  .contexto-texto,\n  .exemplo-texto,\n  .exemplo-conclusao,\n  .infinitivo-nota,\n  .infinitivo-extra,\n  .idf-intro,\n  .idf-rodape,\n  .sentido-texto,\n  .sentido-dica,\n  .licao-corpo,\n  .opcao-texto               { font-size: 15px; }\n  .infinitivo-descricao      { font-size: 17px; }\n  .idf-titulo                { font-size: 17px; }\n  .word-chip                 { font-size: 13px; padding: 7px 10px; }\n}\n\n/* TOAST */\n.toast {\n  position: fixed;\n  bottom: 90px;\n  left: 50%;\n  transform: translateX(-50%) translateY(20px);\n  background: #1a1a2e;\n  color: white;\n  padding: 12px 20px;\n  border-radius: 12px;\n  font-size: 15px;\n  font-weight: 500;\n  opacity: 0;\n  transition: opacity 0.3s ease, transform 0.3s ease;\n  z-index: 600;\n  white-space: nowrap;\n  pointer-events: none;\n}\n\n.toast.show {\n  opacity: 1;\n  transform: translateX(-50%) translateY(0);\n}\n",
  "js/estudo.mjs": "﻿'use strict';\r\n\r\n/**\r\n * ESTUDO.JS — Controller genérico da tela de estudos.\r\n * Carrega dinamicamente o arquivo de questões da aula via URL: ?aula=N\r\n * Para criar uma nova aula, basta criar js/data/questoes/aula-N.mjs\r\n */\r\n\r\nconst LETRAS = ['A', 'B', 'C', 'D'];\r\nconst params   = new URLSearchParams(window.location.search);\r\nconst aulaId   = params.get('aula') || '1';\r\nconst modoErros   = params.get('modo') === 'erros';\r\nconst modoRevisao = params.get('modo') === 'revisao';\r\n// \"Geral\" do Caderno de Erros: junta as checagens erradas de TODAS as aulas\r\n// numa prática só, do erro mais recente pro mais antigo (sem precisar de ?aula=N).\r\nconst modoErrosGeral = modoErros && params.get('geral') === '1';\r\n// Sub-tipo do caderno de Revisão: 'perguntas' mostra só checagem*/questao*\r\n// marcadas, 'telas' mostra só definicao/contexto/exemplo* marcadas. Sem o\r\n// parâmetro (links antigos), mostra tudo que estiver marcado, como antes.\r\nconst tipoRevisao = params.get('tipo');\r\n\r\n// Questões pontuadas desativadas por enquanto (dado da aula mantido em\r\n// js/data/questoes/aula-N.mjs para reativar depois — é só voltar para true).\r\nconst QUESTOES_ATIVAS = false;\r\n\r\n// ── ESTADO ───────────────────────────────────────────────────\r\nconst estado = {\r\n  atual:         0,\r\n  respostas:     [],   // preenchido após carregar as questões\r\n  origIdx:       [],   // mapeia índice exibido -> índice original em aula.questoes (modo caderno de erros)\r\n  totalOriginal: 0,    // nº de questões da 1ª rodada, para a mensagem final após rodadas de revisão\r\n};\r\n\r\n// true quando a aula carregada é o Simulado (montarSimulado) — usado só em\r\n// mostrarFinalizadoChecagem() pra saber se deve limpar a semente do sorteio\r\n// ao terminar a tentativa com 100% de acerto (ver js/idb.js).\r\nlet aulaEhSimulado = false;\r\n\r\n// ── CARREGAR QUESTÕES DINAMICAMENTE ─────────────────────────\r\nfunction carregarAula(id) {\r\n  return new Promise((resolve, reject) => {\r\n    const script  = document.createElement('script');\r\n    script.src    = `js/data/questoes/aula-${id}.mjs`;\r\n    script.onload = () => resolve(window.AULA_DATA);\r\n    script.onerror = () => reject(new Error(`Aula ${id} não encontrada.`));\r\n    document.head.appendChild(script);\r\n  });\r\n}\r\n\r\n// ── ELEMENTOS ────────────────────────────────────────────────\r\nconst questaoInfo      = document.getElementById('questaoInfo');\r\nconst progressSegs     = document.getElementById('progressSegmentos');\r\nconst questaoTitulo    = document.getElementById('questaoTitulo');\r\nconst questaoSubtitulo = document.getElementById('questaoSubtitulo');\r\nconst opcoesEl         = document.getElementById('opcoes');\r\nconst feedbackBar      = document.getElementById('feedbackBar');\r\nconst feedbackIcon     = document.getElementById('feedbackIcon');\r\nconst feedbackTexto    = document.getElementById('feedbackTexto');\r\nconst btnAnterior      = document.getElementById('btnAnterior');\r\nconst btnProxima       = document.getElementById('btnProxima');\r\nconst questaoArea      = document.getElementById('questaoArea');\r\nconst scrollFade       = document.getElementById('scrollFade');\r\n\r\n// ── TOAST ────────────────────────────────────────────────────\r\nlet toastTimer;\r\nfunction showToast(msg, type = 'default') {\r\n  let toast = document.getElementById('toastMsg');\r\n  if (!toast) {\r\n    toast = document.createElement('div');\r\n    toast.id = 'toastMsg';\r\n    toast.className = 'toast';\r\n    document.body.appendChild(toast);\r\n  }\r\n  toast.textContent = msg;\r\n  toast.style.background = type === 'warning' ? '#d97706' : '';\r\n  clearTimeout(toastTimer);\r\n  toast.classList.add('show');\r\n  toastTimer = setTimeout(() => toast.classList.remove('show'), type === 'warning' ? 4000 : 2200);\r\n}\r\n\r\n// Monta o texto da barra de feedback com o \"Correto!\"/\"Incorreto.\" em\r\n// uma linha e a explicação em outra, separados por um espaço maior.\r\n// Quando errado, acrescenta uma terceira linha indicando a alternativa certa.\r\nfunction montarFeedbackHtml(acertou, texto, letraCorreta) {\r\n  const titulo = acertou ? 'Correto!' : 'Incorreto.';\r\n  const correta = !acertou && letraCorreta\r\n    ? `<span class=\"feedback-correta\">Alternativa ${letraCorreta} é a correta.</span>`\r\n    : '';\r\n  return `<span class=\"feedback-titulo\">${titulo}</span><span class=\"feedback-explicacao\">${texto}</span>${correta}`;\r\n}\r\n\r\nfunction atualizarScrollFade() {\r\n  if (!questaoArea || !scrollFade) return;\r\n  const atBottom = questaoArea.scrollHeight - questaoArea.scrollTop <= questaoArea.clientHeight + 8;\r\n  scrollFade.classList.toggle('oculto', atBottom);\r\n}\r\nquestaoArea.addEventListener('scroll', atualizarScrollFade);\r\n\r\n// Frases longas (ex: \"Aconteceram fatos estranhos naquela noite.\") podem não\r\n// caber na largura da tela — o .frase-anotada-wrap já deixa arrastar pro\r\n// lado (overflow-x:auto), mas sem nenhuma pista visual isso parecia palavra\r\n// cortada/sumida. Liga .tem-overflow (degradê na borda, ver estudo.css) só\r\n// quando o conteúdo realmente não cabe inteiro. Chamada depois de popular\r\n// qualquer grid .frase-anotada, então roda em todas de uma vez.\r\nfunction marcarOverflowNasFrasesAnotadas() {\r\n  document.querySelectorAll('.frase-anotada-wrap').forEach(wrap => {\r\n    wrap.classList.toggle('tem-overflow', wrap.scrollWidth > wrap.clientWidth + 2);\r\n  });\r\n}\r\n\r\n// ── TELAS DE INTRODUÇÃO ─────────────────────────────────────\r\nlet introTotal = 0;\r\n\r\nfunction renderIntroSegs(step) {\r\n  progressSegs.innerHTML = '';\r\n  for (let i = 0; i < introTotal; i++) {\r\n    const seg = document.createElement('div');\r\n    seg.className = i <= step ? 'seg respondida' : 'seg';\r\n    progressSegs.appendChild(seg);\r\n  }\r\n}\r\n\r\nfunction mostrarIntro(aula, introIdx = 0) {\r\n  // Oculta elementos das questões\r\n  feedbackBar.style.display = 'none';\r\n  btnAnterior.style.display = introIdx > 0 ? '' : 'none';\r\n\r\n  // Atualiza header\r\n  questaoInfo.textContent = aula.titulo;\r\n  if (introIdx === 0) {\r\n    progressSegs.innerHTML = '';\r\n  } else {\r\n    renderIntroSegs(introIdx - 1);\r\n  }\r\n\r\n  // Monta conteúdo da intro\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n\r\n  const ac = aula.antesComecar || {};\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"intro-card\">\r\n      <span class=\"intro-label\">Antes de começar</span>\r\n      <h2 class=\"intro-titulo\">${ac.titulo || aula.titulo}</h2>\r\n      <p class=\"intro-desc\">${ac.descricao || ''}</p>\r\n      <div class=\"intro-info\">\r\n        <div class=\"intro-info-item\">\r\n          <div class=\"intro-info-icone-wrap\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"26\" height=\"26\">\r\n              <path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/>\r\n              <path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/>\r\n            </svg>\r\n          </div>\r\n          <div class=\"intro-info-texto\">\r\n            <h3>O que você vai aprender</h3>\r\n            <p>${ac.aprender || ''}</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"intro-info-item\">\r\n          <div class=\"intro-info-icone-wrap\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"26\" height=\"26\">\r\n              <path d=\"M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5\"/>\r\n              <path d=\"M9 18h6\"/>\r\n              <path d=\"M10 22h4\"/>\r\n            </svg>\r\n          </div>\r\n          <div class=\"intro-info-texto\">\r\n            <h3>Por que isso é importante</h3>\r\n            <p>${ac.importancia || ''}</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>`;\r\n\r\n  // Botão \"Começar\"\r\n  btnProxima.innerHTML  = 'Começar <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled   = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\nfunction sairIntro() {\r\n  feedbackBar.style.display = '';\r\n  btnAnterior.style.display = '';\r\n  questaoTitulo.innerHTML   = '';\r\n}\r\n\r\n// ── MARCAR CARTÃO PARA REVISÃO ───────────────────────────────\r\n// Etiqueta tipo marca-página no lado esquerdo das telas de conteúdo\r\n// (definição, contexto, exemplo...). Fica salva no arquivo de progresso.\r\nlet cartaoMarcadoSet = new Set();\r\n\r\nfunction marcarCartaoHtml(chave) {\r\n  const marcada = cartaoMarcadoSet.has(chave);\r\n  return `\r\n    <button type=\"button\" class=\"btn-marcar-cartao${marcada ? ' marcada' : ''}\" data-chave=\"${chave}\" title=\"Marcar para revisão\">\r\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n        <path d=\"M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z\"></path>\r\n      </svg>\r\n    </button>`;\r\n}\r\n\r\nfunction ativarBotaoMarcar() {\r\n  const btn = opcoesEl.querySelector('.btn-marcar-cartao');\r\n  if (!btn) return;\r\n  btn.addEventListener('click', async () => {\r\n    const chave = btn.dataset.chave;\r\n    const marcandoOtimista = !cartaoMarcadoSet.has(chave);\r\n    // Atualiza a tela na hora (sensação de resposta imediata), mas só\r\n    // confirma \"salvo\" depois que gravarArquivoProgresso() de fato terminar\r\n    // — sem isso, uma permissão de pasta \"esquecida\" fazia parecer que\r\n    // marcou quando na verdade nada foi salvo em disco.\r\n    if (marcandoOtimista) cartaoMarcadoSet.add(chave); else cartaoMarcadoSet.delete(chave);\r\n    btn.classList.toggle('marcada', marcandoOtimista);\r\n\r\n    const { marcando, salvou } = await alternarCartaoMarcado(aulaId, chave);\r\n    if (!salvou) {\r\n      // Não salvou de verdade — desfaz o estado otimista na tela.\r\n      if (marcandoOtimista) cartaoMarcadoSet.delete(chave); else cartaoMarcadoSet.add(chave);\r\n      btn.classList.toggle('marcada', !marcandoOtimista);\r\n      showToast('⚠️ Não foi possível salvar — reconecte a pasta e tente de novo.', 'warning');\r\n      return;\r\n    }\r\n    showToast(marcando ? '🔖 Marcada para revisão!' : 'Removida da revisão');\r\n  });\r\n}\r\n\r\nfunction mostrarDefinicao(aula, introIdx) {\r\n  const def = aula.definicao || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"definicao-card\">\r\n      ${marcarCartaoHtml('definicao')}\r\n      <div class=\"definicao-icone-wrap\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"40\" height=\"40\">\r\n          <path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/>\r\n          <path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/>\r\n        </svg>\r\n      </div>\r\n      <p class=\"definicao-texto\">${def.texto || ''}</p>\r\n    </div>`;\r\n  ativarBotaoMarcar();\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\nfunction mostrarContexto(aula, introIdx) {\r\n  const ctx = aula.contexto || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = introIdx > 0 ? '' : 'none';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"contexto-card\">\r\n      ${marcarCartaoHtml('contexto')}\r\n      <div class=\"contexto-icone-wrap\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"36\" height=\"36\">\r\n          <circle cx=\"11\" cy=\"11\" r=\"8\"/>\r\n          <line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/>\r\n        </svg>\r\n      </div>\r\n      <p class=\"contexto-texto\">${ctx.texto || ''}</p>\r\n      ${ctx.nota ? `\r\n      <div class=\"contexto-nota\">\r\n        <svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\"><circle cx=\"12\" cy=\"12\" r=\"10\" fill=\"#4A80F0\"/><rect x=\"11\" y=\"11\" width=\"2\" height=\"6\" rx=\"1\" fill=\"white\"/><rect x=\"11\" y=\"8\" width=\"2\" height=\"2\" rx=\"1\" fill=\"white\"/></svg>\r\n        <span>${ctx.nota}</span>\r\n      </div>` : ''}\r\n    </div>`;\r\n  ativarBotaoMarcar();\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// Tela de exemplo do fenômeno da natureza usa um nascer do sol\r\n// (em vez da chuva do resumo), para casar com a palavra \"Amanheceu\".\r\nconst EXEMPLO_ICONE_FENOMENO = `\r\n  <path fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"1.8\" stroke-linecap=\"round\" d=\"M13 2v2M8.5 4.9l1 1M17.5 4.9l-1 1\"/>\r\n  <path fill=\"#4A80F0\" d=\"M8 12a5 5 0 0 1 10 0z\"/>\r\n  <line x1=\"6\" y1=\"12\" x2=\"20\" y2=\"12\" stroke=\"#4A80F0\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\r\n  <path fill=\"none\" stroke=\"#4A80F0\" stroke-width=\"1.8\" stroke-linecap=\"round\" d=\"M8 16h4M15 16h3M10 19h3\"/>`;\r\n\r\n// Rótulo do colchete anotado embaixo da palavra. Aceita um índice único ou\r\n// um intervalo (ex: o predicado cobre o verbo + a palavra recém-clicada).\r\nconst ROTULO_PAPEL = { verbo: 'Verbo', sujeito: 'Sujeito', predicado: 'Predicado', auxiliar: 'Auxiliar', principal: 'Principal' };\r\n\r\nfunction anotarPapelInterativo(wrap, idxOuIdxs, papel) {\r\n  const lista  = Array.isArray(idxOuIdxs) ? idxOuIdxs : [idxOuIdxs];\r\n  const sorted = [...lista].sort((a, b) => a - b);\r\n  // O predicado fica numa linha abaixo de verbo/sujeito porque seu colchete\r\n  // pode cobrir a mesma coluna do verbo (ele é o núcleo do predicado).\r\n  const linha = papel === 'predicado' ? 3 : 2;\r\n\r\n  // Agrupa em blocos contíguos — um papel pode ficar \"quebrado\" por outro no\r\n  // meio da frase (ex: predicado quebrado pelo sujeito na ordem invertida:\r\n  // \"Aconteceram fatos estranhos naquela noite\" — predicado é [0,3,4], não\r\n  // um intervalo único, senão o colchete cobriria o sujeito também).\r\n  const grupos = [];\r\n  let inicio = sorted[0], fim = sorted[0];\r\n  for (let i = 1; i < sorted.length; i++) {\r\n    if (sorted[i] === fim + 1) {\r\n      fim = sorted[i];\r\n    } else {\r\n      grupos.push([inicio, fim]);\r\n      inicio = fim = sorted[i];\r\n    }\r\n  }\r\n  grupos.push([inicio, fim]);\r\n\r\n  grupos.forEach(([ini, final]) => {\r\n    wrap.insertAdjacentHTML('beforeend',\r\n      `<div class=\"anotacao-${papel}\" style=\"grid-column:${ini + 1}/span ${final - ini + 1};grid-row:${linha}\">${ROTULO_PAPEL[papel]}</div>`);\r\n  });\r\n}\r\n\r\n// Passo de exemplo com mais de uma palavra clicável pro mesmo papel (ex:\r\n// \"estudou\" e \"ontem\", ambos parte do predicado). Diferente de marcarAntes\r\n// (travado, só contexto), as palavras em \"corretas\" continuam clicáveis —\r\n// algumas já têm uma cor própria conhecida (papeisIniciais, ex: o verbo\r\n// continua azul mesmo depois de confirmado como parte do predicado) e viram\r\n// a cor do papel principal quando não têm uma cor própria. O colchete do\r\n// papel principal cresce a cada clique, até cobrir todas as palavras certas.\r\nfunction renderInterativoMultiplo(ex, interativo, wrap) {\r\n  const jaAcertou = ex._acertouInterativo === true;\r\n  btnProxima.disabled = !jaAcertou;\r\n  wrap.innerHTML = '';\r\n\r\n  // Palavras já encontradas num passo anterior (ex: o verbo) entram contadas\r\n  // desde o início — não precisam de um clique extra pra \"confirmar\" de novo.\r\n  if (!ex._selecionadas) ex._selecionadas = [...(interativo.preSelecionadas || [])];\r\n  const marcarAntes    = interativo.marcarAntes || [];\r\n  const papeisIniciais = interativo.papeisIniciais || {};\r\n\r\n  interativo.palavras.forEach((palavra, idx) => {\r\n    const btn = document.createElement('button');\r\n    btn.className = 'word-chip word-chip-sm';\r\n    btn.textContent = palavra;\r\n    btn.style.gridColumn = String(idx + 1);\r\n    btn.style.gridRow    = '1';\r\n\r\n    const prefixada  = marcarAntes.find(m => Array.isArray(m.idx) ? m.idx.includes(idx) : m.idx === idx);\r\n    const ehAlvo      = interativo.corretas.includes(idx);\r\n    const jaSelecionada = ex._selecionadas.includes(idx);\r\n\r\n    if (PONTUACAO_RE.test(palavra)) {\r\n      btn.classList.add('pontuacao');\r\n      btn.disabled = true;\r\n    } else if (prefixada) {\r\n      btn.disabled = true;\r\n      btn.classList.add(`${prefixada.papel}-correto`);\r\n    } else if (ehAlvo && jaAcertou) {\r\n      btn.disabled = true;\r\n      btn.classList.add(`${papeisIniciais[idx] || interativo.papel}-correto`);\r\n    } else if (ehAlvo) {\r\n      // Mesmo já contando desde o início (preSelecionadas), a palavra\r\n      // continua clicável — clicar nela de novo também \"abre\" o colchete do\r\n      // predicado, igual clicar numa palavra nova.\r\n      if (jaSelecionada || papeisIniciais[idx]) btn.classList.add(`${papeisIniciais[idx] || interativo.papel}-correto`);\r\n      btn.addEventListener('click', () => {\r\n        ex._algumClique = true;\r\n        if (!ex._selecionadas.includes(idx)) ex._selecionadas.push(idx);\r\n        if (interativo.corretas.every(i => ex._selecionadas.includes(i))) ex._acertouInterativo = true;\r\n        renderInterativoMultiplo(ex, interativo, wrap);\r\n      });\r\n    } else {\r\n      btn.disabled = true;\r\n    }\r\n    wrap.appendChild(btn);\r\n  });\r\n\r\n  marcarAntes.forEach(m => anotarPapelInterativo(wrap, m.idx, m.papel));\r\n  Object.keys(papeisIniciais).forEach(idxStr => {\r\n    const idx = Number(idxStr);\r\n    if (interativo.corretas.includes(idx) && (ex._selecionadas.includes(idx) || jaAcertou)) {\r\n      anotarPapelInterativo(wrap, idx, papeisIniciais[idx]);\r\n    }\r\n  });\r\n  // O colchete do papel principal (predicado) só aparece depois de um clique\r\n  // de verdade — palavras pré-selecionadas sozinhas (ex: o verbo, já sabido\r\n  // de um passo anterior) não bastam pra \"abrir\" o predicado sozinhas, mas\r\n  // clicar em qualquer uma das palavras-alvo (mesmo já contada) já conta.\r\n  const mostrarPrincipal = jaAcertou || ex._algumClique === true;\r\n  if (mostrarPrincipal && ex._selecionadas.length > 0) {\r\n    anotarPapelInterativo(wrap, ex._selecionadas, interativo.papel);\r\n  }\r\n\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// Frase já anotada, só ilustrativa (sem clique) — usada pra recapitular a\r\n// divisão sujeito/verbo/predicado de um passo anterior, com os colchetes\r\n// já prontos, em vez de repetir a explicação em texto.\r\nfunction renderFraseAnotadaEstatica(dados, wrap) {\r\n  dados.sentenca.forEach((palavra, i) => {\r\n    const btn = document.createElement('button');\r\n    let cls = 'word-chip word-chip-sm';\r\n    if (PONTUACAO_RE.test(palavra))       cls += ' pontuacao';\r\n    else if (i === dados.verbo)                cls += ' verbo-correto';\r\n    else if (dados.sujeito.includes(i))   cls += ' sujeito-correto';\r\n    else if (dados.predicado.includes(i)) cls += ' predicado-correto';\r\n    btn.className         = cls;\r\n    btn.textContent        = palavra;\r\n    btn.disabled           = true;\r\n    btn.style.gridColumn   = String(i + 1);\r\n    btn.style.gridRow      = '1';\r\n    wrap.appendChild(btn);\r\n  });\r\n  if (dados.sujeito.length)   anotarPapelInterativo(wrap, dados.sujeito, 'sujeito');\r\n  if (dados.verbo != null)    anotarPapelInterativo(wrap, dados.verbo, 'verbo');\r\n  if (dados.predicado.length) anotarPapelInterativo(wrap, dados.predicado, 'predicado');\r\n}\r\n\r\n// Passo de exemplo com uma checklist de perguntas sim/não (ex: \"o verbo\r\n// destacado é haver? é fazer? é fenômeno da natureza?\") — precisa acertar\r\n// todas antes de liberar o \"Próximo\". Progresso guardado em ex._simNaoOk,\r\n// array paralelo a caixa.perguntasSimNao (true quando já respondida certo).\r\nfunction renderSimNao(ex, wrap) {\r\n  const perguntas = ex.caixa.perguntasSimNao;\r\n  if (!ex._simNaoOk) ex._simNaoOk = perguntas.map(() => false);\r\n  const todasCertas = ex._simNaoOk.every(Boolean);\r\n  btnProxima.disabled = !todasCertas;\r\n\r\n  wrap.innerHTML = perguntas.map((p, i) => `\r\n    <div class=\"simnao-item\">\r\n      <p class=\"simnao-texto\">${p.texto}</p>\r\n      <div class=\"simnao-botoes\">\r\n        <button type=\"button\" class=\"simnao-btn\" data-i=\"${i}\" data-valor=\"true\"${ex._simNaoOk[i] ? ' disabled' : ''}>Sim</button>\r\n        <button type=\"button\" class=\"simnao-btn\" data-i=\"${i}\" data-valor=\"false\"${ex._simNaoOk[i] ? ' disabled' : ''}>Não</button>\r\n      </div>\r\n    </div>`).join('') +\r\n    (todasCertas ? `\r\n    <div class=\"passo-caixa-divisor\"></div>\r\n    <p class=\"passo-caixa-seta\">→ ${ex.caixa.conclusao}</p>` : '');\r\n\r\n  perguntas.forEach((p, i) => {\r\n    if (ex._simNaoOk[i]) {\r\n      const certoBtn = wrap.querySelector(`.simnao-btn[data-i=\"${i}\"][data-valor=\"${p.resposta}\"]`);\r\n      if (certoBtn) certoBtn.classList.add('correta');\r\n      return;\r\n    }\r\n    wrap.querySelectorAll(`.simnao-btn[data-i=\"${i}\"]`).forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        const valor = btn.dataset.valor === 'true';\r\n        if (valor === p.resposta) {\r\n          ex._simNaoOk[i] = true;\r\n          renderSimNao(ex, wrap);\r\n        } else {\r\n          btn.classList.add('errada');\r\n          setTimeout(() => btn.classList.remove('errada'), 500);\r\n        }\r\n      });\r\n    });\r\n  });\r\n}\r\n\r\nfunction mostrarExemplo(aula, introIdx, i) {\r\n  const ex = (aula.exemplo || [])[i] || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  const icone = ex.tipo === 'fenomeno'\r\n    ? EXEMPLO_ICONE_FENOMENO\r\n    : (RESUMO_ICONES[ex.tipo] ? RESUMO_ICONES[ex.tipo]('#4A80F0') : RESUMO_ICONES.acao('#4A80F0'));\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"exemplo-card\">\r\n      ${marcarCartaoHtml(`exemplo${i}`)}\r\n      <div class=\"exemplo-icone-wrap\">\r\n        <svg viewBox=\"-6 0 30 24\" fill=\"none\" width=\"60\" height=\"48\">\r\n          <line x1=\"-5\" y1=\"8\"  x2=\"0\" y2=\"8\"  stroke=\"#b8ccf4\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\r\n          <line x1=\"-5\" y1=\"12\" x2=\"1\" y2=\"12\" stroke=\"#b8ccf4\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\r\n          <line x1=\"-5\" y1=\"16\" x2=\"0\" y2=\"16\" stroke=\"#b8ccf4\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\r\n          ${icone}\r\n        </svg>\r\n      </div>\r\n      ${ex.texto ? `<p class=\"exemplo-texto\">${ex.texto}</p>` : ''}\r\n      ${ex.conclusao ? `<p class=\"exemplo-conclusao\">${ex.conclusao}</p>` : ''}\r\n      ${ex.obs ? `<p class=\"exemplo-texto\">${ex.obs}</p>` : ''}\r\n      ${(ex.pontos || []).length ? `\r\n      <div class=\"exemplo-pontos\">\r\n        ${ex.pontos.map(p => `\r\n          <div class=\"exemplo-ponto\">\r\n            <div class=\"exemplo-ponto-icone\">\r\n              <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\">${RESUMO_ICONES[p.tipo] ? RESUMO_ICONES[p.tipo]('#4A80F0') : ''}</svg>\r\n            </div>\r\n            <p class=\"exemplo-ponto-texto\">${p.texto}</p>\r\n          </div>`).join('')}\r\n      </div>` : ''}\r\n      ${ex.fechamento ? `<p class=\"exemplo-texto\">${ex.fechamento}</p>` : ''}\r\n      ${ex.passo ? `\r\n      <div class=\"passo-bloco\">\r\n        <div class=\"passo-linha\">\r\n          <div class=\"passo-numero\">${ex.passo.numero}</div>\r\n          <p class=\"passo-instrucao\">– ${ex.passo.instrucao}</p>\r\n        </div>\r\n        ${ex.passo.nota ? `<p class=\"passo-nota\">${ex.passo.nota}</p>` : ''}\r\n      </div>` : ''}\r\n      ${ex.caixa ? (ex.caixa.anotado ? `\r\n      <div class=\"passo-caixa\">\r\n        <div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"exemploAnotado\" style=\"grid-template-columns:repeat(${ex.caixa.anotado.sentenca.length},auto)\"></div></div>\r\n      </div>` : ex.caixa.perguntasSimNao ? `\r\n      <div class=\"passo-caixa\">\r\n        <div class=\"simnao-wrap\" id=\"simNaoWrap\"></div>\r\n      </div>` : (!ex.caixa.titulo && !ex.caixa.exemplo && !ex.caixa.sentencaAnotada && !ex.caixa.interativo && !ex.caixa.inline && (ex.caixa.perguntas || []).length) ? `\r\n      <div class=\"passo-caixa passo-caixa-somente-texto\">\r\n        <div class=\"passo-caixa-perguntas\">\r\n          ${ex.caixa.perguntas.map(p => typeof p === 'string'\r\n            ? `<p class=\"passo-caixa-seta\">→ ${p}</p>`\r\n            : `<p class=\"passo-caixa-nota-indent\">${p.nota}</p>`\r\n          ).join('')}\r\n        </div>\r\n      </div>` : `\r\n      <div class=\"passo-caixa\">\r\n        <div class=\"passo-caixa-cabecalho\">\r\n          <div class=\"passo-caixa-icone\">\r\n            <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\">${RESUMO_ICONES[ex.caixa.tipo] ? RESUMO_ICONES[ex.caixa.tipo]('#4A80F0') : ''}</svg>\r\n          </div>\r\n          ${ex.caixa.interativo\r\n            ? `<p class=\"passo-caixa-inline\"><strong>${ex.caixa.rotulo || 'Selecione o verbo abaixo:'}</strong></p>`\r\n            : ex.caixa.inline\r\n              ? `<p class=\"passo-caixa-inline\"><strong>Exemplo:</strong> ${ex.caixa.exemplo}</p>`\r\n              : `<div class=\"passo-caixa-corpo\">\r\n                   <p class=\"passo-caixa-titulo\">${ex.caixa.titulo || 'Exemplo:'}</p>\r\n                   ${ex.caixa.exemplo ? `<p class=\"passo-caixa-texto\">${ex.caixa.exemplo}</p>` : ''}\r\n                 </div>`}\r\n        </div>\r\n        ${ex.caixa.interativo ? `<div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"exemploSentence\" style=\"grid-template-columns:repeat(${ex.caixa.interativo.palavras.length},auto)\"></div></div>` : ''}\r\n        ${ex.caixa.sentencaAnotada ? `<div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"exemploCaixaAnotada\" style=\"grid-template-columns:repeat(${ex.caixa.sentencaAnotada.sentenca.length},auto)\"></div></div>` : ''}\r\n        ${(ex.caixa.perguntas || []).length ? `\r\n        <div class=\"passo-caixa-divisor\"></div>\r\n        <div class=\"passo-caixa-perguntas\">\r\n          ${ex.caixa.perguntas.map(p => typeof p === 'string'\r\n            ? `<p class=\"passo-caixa-seta\">→ ${p}</p>`\r\n            : `<p class=\"passo-caixa-nota-indent\">${p.nota}</p>`\r\n          ).join('')}\r\n        </div>` : ''}\r\n        ${ex.caixa.resposta ? `\r\n        <div class=\"passo-caixa-divisor\"></div>\r\n        <p class=\"passo-caixa-resposta\"><strong>Resposta:</strong> ${ex.caixa.resposta}</p>` : ''}\r\n      </div>`) : ''}\r\n    </div>`;\r\n  ativarBotaoMarcar();\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n\r\n  // Palavras clicáveis dentro da caixa de exemplo (ex: selecionar o verbo).\r\n  // Não é uma checagem — não conta erro, só trava o \"Próximo\" até acertar.\r\n  if (ex.caixa && ex.caixa.anotado) {\r\n    renderFraseAnotadaEstatica(ex.caixa.anotado, document.getElementById('exemploAnotado'));\r\n    btnProxima.disabled = false;\r\n  } else if (ex.caixa && ex.caixa.sentencaAnotada) {\r\n    renderFraseAnotadaEstatica(ex.caixa.sentencaAnotada, document.getElementById('exemploCaixaAnotada'));\r\n    btnProxima.disabled = false;\r\n  } else if (ex.caixa && ex.caixa.perguntasSimNao) {\r\n    renderSimNao(ex, document.getElementById('simNaoWrap'));\r\n  } else if (ex.caixa && ex.caixa.interativo && Array.isArray(ex.caixa.interativo.corretas)) {\r\n    renderInterativoMultiplo(ex, ex.caixa.interativo, document.getElementById('exemploSentence'));\r\n  } else if (ex.caixa && ex.caixa.interativo) {\r\n    const interativo = ex.caixa.interativo;\r\n    const jaAcertou   = ex._acertouInterativo === true;\r\n    btnProxima.disabled = !jaAcertou;\r\n    const wrap = document.getElementById('exemploSentence');\r\n    // Palavras já encontradas num passo anterior (ex: o verbo, antes de\r\n    // procurar o sujeito) aparecem travadas e destacadas, com o colchete já\r\n    // anotado embaixo — não fazem parte da pergunta deste passo, só dão\r\n    // contexto do que já foi descoberto.\r\n    const marcarAntes = interativo.marcarAntes || [];\r\n    interativo.palavras.forEach((palavra, idx) => {\r\n      const btn = document.createElement('button');\r\n      btn.className = 'word-chip word-chip-sm';\r\n      btn.textContent = palavra;\r\n      btn.style.gridColumn = String(idx + 1);\r\n      btn.style.gridRow    = '1';\r\n      const prefixada = marcarAntes.find(m => Array.isArray(m.idx) ? m.idx.includes(idx) : m.idx === idx);\r\n      if (PONTUACAO_RE.test(palavra)) {\r\n        btn.classList.add('pontuacao');\r\n        btn.disabled = true;\r\n      } else if (prefixada) {\r\n        btn.disabled = true;\r\n        btn.classList.add(`${prefixada.papel}-correto`);\r\n      } else if (jaAcertou) {\r\n        btn.disabled = true;\r\n        if (idx === interativo.correta) btn.classList.add(interativo.papel ? `${interativo.papel}-correto` : 'correta');\r\n      } else {\r\n        btn.addEventListener('click', () => {\r\n          if (idx === interativo.correta) {\r\n            ex._acertouInterativo = true;\r\n            btn.classList.add(interativo.papel ? `${interativo.papel}-correto` : 'correta');\r\n            Array.from(wrap.children).forEach(c => c.disabled = true);\r\n            btnProxima.disabled = false;\r\n            if (interativo.papel) anotarPapelInterativo(wrap, interativo.intervaloAoAcertar || idx, interativo.papel);\r\n          } else {\r\n            btn.classList.add('errada');\r\n            setTimeout(() => btn.classList.remove('errada'), 500);\r\n          }\r\n        });\r\n      }\r\n      wrap.appendChild(btn);\r\n    });\r\n    marcarAntes.forEach(m => anotarPapelInterativo(wrap, m.idx, m.papel));\r\n    if (jaAcertou && interativo.papel) {\r\n      anotarPapelInterativo(wrap, interativo.intervaloAoAcertar || interativo.correta, interativo.papel);\r\n    }\r\n  } else {\r\n    btnProxima.disabled = false;\r\n  }\r\n\r\n  marcarOverflowNasFrasesAnotadas();\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// ── ÍCONES DO RESUMO ─────────────────────────────────────────\r\nconst RESUMO_ICONES = {\r\n  acao:     cor => `<path fill=\"${cor}\" d=\"M13.49 5.48c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm-3.6 13.9l1-4.4 2.1 2v6h2v-7.5l-2.1-2 .6-3c1.3 1.5 3.3 2.5 5.5 2.5v-2c-1.9 0-3.5-1-4.3-2.4l-1-1.6c-.4-.6-1-1-1.7-1-.3 0-.5.1-.8.1l-5.2 2.2v4.7h2v-3.4l1.8-.7-1.6 8.1-4.9-1-.4 2 7 1.4z\"/>`,\r\n  estado:   cor => `<circle cx=\"12\" cy=\"5\" r=\"2.5\" fill=\"${cor}\"/><path fill=\"${cor}\" d=\"M12 9c-3 0-5 2-5 4.5V17h3v4h4v-4h3v-3.5C17 11 15 9 12 9z\"/>`,\r\n  mudanca:  cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"2.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M23 4v6h-6M1 20v-6h6M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15\"/>`,\r\n  fenomeno: cor => `<path fill=\"${cor}\" d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9z\"/><line x1=\"8\" y1=\"20\" x2=\"8\" y2=\"23\" stroke=\"${cor}\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"23\" stroke=\"${cor}\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><line x1=\"16\" y1=\"20\" x2=\"16\" y2=\"23\" stroke=\"${cor}\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>`,\r\n  infinito: cor => `<text x=\"13\" y=\"17\" font-size=\"16\" font-weight=\"700\" fill=\"${cor}\" text-anchor=\"middle\">∞</text>`,\r\n  conjugar: cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"2.1\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M18.5 4.5a2.121 2.121 0 0 1 3 3L9 20l-4.5 1 1-4.5L18.5 4.5z\"/>`,\r\n  gota:     cor => `<path fill=\"${cor}\" d=\"M12 2s6 7.3 6 11.5A6 6 0 0 1 6 13.5C6 9.3 12 2 12 2z\"/>`,\r\n  peca:     cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4 7h3a1 1 0 0 0 1 -1v-1a2 2 0 0 1 4 0v1a1 1 0 0 0 1 1h3a1 1 0 0 1 1 1v3a1 1 0 0 0 1 1h1a2 2 0 0 1 0 4h-1a1 1 0 0 0 -1 1v3a1 1 0 0 1 -1 1h-3a1 1 0 0 1 -1 -1v-1a2 2 0 0 0 -4 0v1a1 1 0 0 1 -1 1h-3a1 1 0 0 1 -1 -1v-3a1 1 0 0 0 -1 -1h-1a2 2 0 0 1 0 -4h1a1 1 0 0 0 1 -1v-3a1 1 0 0 1 1 -1\"/>`,\r\n  foguete:  cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z\"/><path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 15l-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z\"/><path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0\"/><path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5\"/>`,\r\n  sujeito:  cor => `<circle cx=\"12\" cy=\"8\" r=\"4\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\"/><path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" d=\"M4 21v-1a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v1\"/>`,\r\n  fala:     cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21 15a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z\"/><circle cx=\"9\" cy=\"11\" r=\"1\" fill=\"${cor}\"/><circle cx=\"12\" cy=\"11\" r=\"1\" fill=\"${cor}\"/><circle cx=\"15\" cy=\"11\" r=\"1\" fill=\"${cor}\"/>`,\r\n  busca:    cor => `<circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"2.1\"/><line x1=\"20\" y1=\"20\" x2=\"16\" y2=\"16\" stroke=\"${cor}\" stroke-width=\"2.1\" stroke-linecap=\"round\"/>`,\r\n  tarefa:   cor => `<rect x=\"5\" y=\"4\" width=\"12\" height=\"16\" rx=\"2\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.6\"/><line x1=\"8\" y1=\"8\" x2=\"14\" y2=\"8\" stroke=\"${cor}\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><line x1=\"8\" y1=\"12\" x2=\"12\" y2=\"12\" stroke=\"${cor}\" stroke-width=\"1.6\" stroke-linecap=\"round\"/><path d=\"M14 16l4-4 2 2-4 4h-2v-2z\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.4\" stroke-linejoin=\"round\"/>`,\r\n  pergunta: cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21 15a2 2 0 0 1-2 2H8l-4 4V5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z\"/><text x=\"9.5\" y=\"14\" font-size=\"9\" font-weight=\"700\" fill=\"${cor}\">?</text>`,\r\n  dica:     cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.4.8 1 .8 1.6v.5h5.4v-.5c0-.6.3-1.2.8-1.6A6 6 0 0 0 12 3z\"/>`,\r\n  predVerbal:      cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M5 12h14M13 6l6 6-6 6\"/>`,\r\n  predNominal:     cor => `<circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>`,\r\n  predVerboNominal: cor => `<path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 17H7a5 5 0 1 1 0-10h2M15 7h2a5 5 0 1 1 0 10h-2M8 12h8\"/>`,\r\n  semSujeito: cor => `<line x1=\"-1\" y1=\"6\"  x2=\"2\" y2=\"6\"  stroke=\"${cor}\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.5\"/><line x1=\"-1\" y1=\"10\" x2=\"2\" y2=\"10\" stroke=\"${cor}\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.5\"/><line x1=\"-1\" y1=\"14\" x2=\"2\" y2=\"14\" stroke=\"${cor}\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.5\"/><circle cx=\"11\" cy=\"8\" r=\"4\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\"/><path fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.8\" stroke-linecap=\"round\" d=\"M4 21v-1a6 6 0 0 1 6-6h1.5\"/><circle cx=\"18\" cy=\"17\" r=\"5\" fill=\"none\" stroke=\"${cor}\" stroke-width=\"1.7\"/><line x1=\"16.1\" y1=\"15.1\" x2=\"19.9\" y2=\"18.9\" stroke=\"${cor}\" stroke-width=\"1.7\" stroke-linecap=\"round\"/><line x1=\"19.9\" y1=\"15.1\" x2=\"16.1\" y2=\"18.9\" stroke=\"${cor}\" stroke-width=\"1.7\" stroke-linecap=\"round\"/>`,\r\n};\r\n\r\nfunction mostrarInfinitivo(aula, introIdx) {\r\n  const inf = aula.infinitivo || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"infinitivo-card\">\r\n      <div class=\"infinitivo-icone-wrap\">\r\n        <span class=\"infinitivo-icone-simbolo\">∞</span>\r\n      </div>\r\n      <p class=\"infinitivo-descricao\">${inf.descricao || ''}</p>\r\n      ${inf.nota ? `<p class=\"infinitivo-nota\">${inf.nota}</p>` : ''}\r\n      <p class=\"infinitivo-conj-titulo\">Normalmente, os infinitivos terminam em:</p>\r\n      <div class=\"infinitivo-conjs\">\r\n        ${(inf.conjugacoes || []).map(c => `\r\n        <div class=\"infinitivo-conj-card\">\r\n          <span class=\"infinitivo-conj-sufixo\">${c.sufixo}</span>\r\n          <span class=\"infinitivo-conj-label\">${c.label}</span>\r\n        </div>`).join('')}\r\n      </div>\r\n      ${inf.extra ? `<p class=\"infinitivo-extra\">${inf.extra}</p>` : ''}\r\n    </div>`;\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\nfunction mostrarResumo(aula, introIdx) {\r\n  const res = aula.resumo || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"resumo-card\">\r\n      <p class=\"resumo-titulo\">${res.titulo || ''}</p>\r\n      ${(res.itens || []).map(item => `\r\n      <div class=\"resumo-item\">\r\n        <div class=\"resumo-icone\" style=\"background:${item.corFundo}\">\r\n          <svg viewBox=\"0 0 24 24\" width=\"26\" height=\"26\">\r\n            ${RESUMO_ICONES[item.tipo] ? RESUMO_ICONES[item.tipo](item.cor) : ''}\r\n          </svg>\r\n        </div>\r\n        <div class=\"resumo-item-info\">\r\n          <span class=\"resumo-item-titulo\" style=\"color:${item.cor}\">${item.titulo}</span>\r\n          <span class=\"resumo-item-exemplos\">${item.exemplos}</span>\r\n        </div>\r\n      </div>`).join('')}\r\n    </div>`;\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\nfunction mostrarLicao(aula, introIdx) {\r\n  const lic = aula.licao || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"resumo-card\">\r\n      <p class=\"resumo-titulo\">${lic.titulo || ''}</p>\r\n      <div class=\"licao-corpo\">${lic.html || ''}</div>\r\n    </div>`;\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\nfunction mostrarIdentificacao(aula, introIdx) {\r\n  const idf = aula.identificacao || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"idf-card\">\r\n      <div class=\"idf-header\">\r\n        <div class=\"idf-icone-wrap\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"30\" height=\"30\">\r\n            <path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/>\r\n            <path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/>\r\n          </svg>\r\n        </div>\r\n        <p class=\"idf-titulo\">${idf.titulo || ''}</p>\r\n      </div>\r\n      <p class=\"idf-intro\">${idf.intro || ''}</p>\r\n      <div class=\"idf-exemplos\">\r\n        ${(idf.exemplos || []).map(e => `\r\n        <div class=\"idf-exemplo-card\">\r\n          <span class=\"idf-palavra\">${e.palavra}</span>\r\n          <span class=\"idf-linha\">${e.infinitivo} → terminação <strong>${e.terminacao}</strong></span>\r\n          <span class=\"idf-linha\">→ ${e.conjugacao}</span>\r\n        </div>`).join('')}\r\n      </div>\r\n      ${idf.rodape ? `<p class=\"idf-rodape\">${idf.rodape}</p>` : ''}\r\n    </div>`;\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// ── CHECAGEM (pergunta rápida no meio da introdução) ─────────\r\n// Não conta na pontuação da aula — é só um checkpoint de leitura.\r\n// A resposta escolhida fica guardada em dados._escolhida, então\r\n// voltar/avançar preserva o estado já respondido.\r\n// Checagens do tipo \"duplo-select\" (clicar no verbo e no sujeito) guardam\r\n// a resposta como objeto {verbo, sujeito:[]} em vez de um índice único,\r\n// então usam dados._correta (booleano) pra saber se acertou.\r\nfunction acertouChecagem(dados) {\r\n  return (dados.sujeito || dados.banco) ? dados._correta === true : dados._escolhida === dados.correta;\r\n}\r\n\r\nfunction mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId = aulaId) {\r\n  // No modo \"Geral\", cada item pode vir de uma aula diferente — mostra o\r\n  // título da aula de origem, não o título genérico \"Caderno de Erros — Geral\".\r\n  const origemInfo = modoErrosGeral\r\n    ? (MODULOS || []).flatMap(m => m.aulas).find(a => String(a.id) === String(origemAulaId))\r\n    : null;\r\n  questaoInfo.textContent      = origemInfo ? origemInfo.titulo : aula.titulo;\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  // Ordem invertida: a pergunta curta vem primeiro (em negrito, no\r\n  // tamanho do subtítulo) e \"O que é um verbo?\" vem depois, mantendo\r\n  // o tamanho grande que já tinha.\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  feedbackBar.style.display    = '';\r\n\r\n  const respondida = dados._escolhida !== undefined;\r\n\r\n  // Só a primeira checagem (\"O que é um verbo?\") usa a ordem invertida\r\n  // (pergunta curta em negrito antes do título grande). As demais seguem\r\n  // o layout padrão das questões, com o verbo em destaque no subtítulo.\r\n  // Checagens com \"sentenca\" (clicar na palavra) não repetem a frase como\r\n  // subtítulo — ela já aparece como as palavras clicáveis logo abaixo.\r\n  opcoesEl.innerHTML = marcarCartaoHtml(`checagem${checagemIdx}`) + (dados.invertido\r\n    ? `<p class=\"questao-subtitulo checagem-pergunta\">${dados.subtitulo || ''}</p>\r\n       <h2 class=\"questao-titulo checagem-titulo\">${dados.titulo || ''}</h2>`\r\n    : `<h2 class=\"questao-titulo checagem-instrucao\">${dados.titulo || ''}</h2>` +\r\n      ((dados.sentenca || dados.banco) ? '' : `<p class=\"questao-subtitulo checagem-frase\">${dados.subtitulo || ''}</p>`)) +\r\n    (dados.predicado ? '<div class=\"tri-select-wrap\" id=\"triSelectWrap\"></div>'\r\n      : dados.sujeito ? '<div class=\"dual-select-wrap\" id=\"dualSelectWrap\"></div>'\r\n      : dados.banco ? '<div class=\"reordenar-wrap\" id=\"reordenarWrap\"></div>'\r\n      : dados.sentenca ? '<div class=\"sentence-display\" id=\"sentenceDisplay\"></div>' : '');\r\n  ativarBotaoMarcar();\r\n\r\n  if (dados.predicado) {\r\n    mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, respondida);\r\n  } else if (dados.sujeito) {\r\n    mostrarChecagemDupla(aula, introIdx, dados, checagemIdx, origemAulaId, respondida);\r\n  } else if (dados.banco) {\r\n    mostrarChecagemReordenar(aula, introIdx, dados, checagemIdx, origemAulaId, respondida);\r\n  } else if (dados.sentenca) {\r\n    const wrap = document.getElementById('sentenceDisplay');\r\n    const PONTUACAO = /^[.,!?;:]+$/;\r\n    dados.sentenca.forEach((palavra, i) => {\r\n      const ehPontuacao = PONTUACAO.test(palavra);\r\n      const btn = document.createElement('button');\r\n      btn.className = 'word-chip' + (ehPontuacao ? ' pontuacao' : '');\r\n      btn.textContent = palavra;\r\n      if (ehPontuacao) {\r\n        btn.disabled = true;\r\n      } else if (respondida) {\r\n        btn.disabled = true;\r\n        if (i === dados.correta)                                btn.classList.add('correta');\r\n        else if (i === dados._escolhida && i !== dados.correta) btn.classList.add('errada');\r\n      } else {\r\n        btn.addEventListener('click', () => {\r\n          dados._escolhida = i;\r\n          if (i !== dados.correta) {\r\n            addErro(origemAulaId, `checagem${checagemIdx}`);\r\n            erroNestaSessao = true;\r\n          }\r\n          mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId);\r\n        });\r\n      }\r\n      wrap.appendChild(btn);\r\n    });\r\n\r\n    // Depois de responder, mostra a classe gramatical de cada palavra da\r\n    // frase (o verbo em verde, a escolha errada em vermelho, se houver).\r\n    if (respondida && dados.classes) {\r\n      const acertou = dados._escolhida === dados.correta;\r\n      const linhas = dados.sentenca.map((palavra, i) => {\r\n        if (PONTUACAO.test(palavra)) return '';\r\n        const info = dados.classes[i] || {};\r\n        const ehVerbo   = i === dados.correta;\r\n        const ehErrada  = !acertou && i === dados._escolhida;\r\n        const classe    = ehVerbo ? 'correta' : (ehErrada ? 'errada' : '');\r\n        return `\r\n          <div class=\"checagem-resultado-item${ehErrada ? ' errada-selecionada' : ''}\">\r\n            <span class=\"cri-palavra ${classe}\">${palavra}</span>\r\n            <span class=\"cri-seta\">→</span>\r\n            <span class=\"cri-classe ${classe}\">${info.classe || ''}</span>\r\n            ${ehVerbo  ? '<span class=\"cri-icone\" style=\"color:#16a34a\">✓</span>' : ''}\r\n            ${ehErrada ? '<span class=\"cri-icone\" style=\"color:#dc2626\">✕</span>' : ''}\r\n          </div>`;\r\n      }).join('');\r\n      opcoesEl.insertAdjacentHTML('beforeend', `\r\n        <div class=\"checagem-resultado-itens\">\r\n          <p class=\"checagem-resultado-titulo\">Resposta de cada item:</p>\r\n          <div class=\"checagem-resultado-lista\">${linhas}</div>\r\n        </div>`);\r\n    }\r\n  } else {\r\n    (dados.opcoes || []).forEach((texto, i) => {\r\n      const btn = document.createElement('button');\r\n      btn.className = 'opcao';\r\n      if (respondida) {\r\n        btn.disabled = true;\r\n        if (i === dados.correta)                                btn.classList.add('correta');\r\n        else if (i === dados._escolhida && i !== dados.correta) btn.classList.add('errada');\r\n      } else {\r\n        btn.addEventListener('click', () => {\r\n          dados._escolhida = i;\r\n          if (i !== dados.correta) {\r\n            addErro(origemAulaId, `checagem${checagemIdx}`);\r\n            erroNestaSessao = true;\r\n          }\r\n          mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId);\r\n        });\r\n      }\r\n      btn.innerHTML = `<span class=\"letra\">${LETRAS[i]}</span><span class=\"opcao-texto\">${texto}</span>`;\r\n      opcoesEl.appendChild(btn);\r\n    });\r\n  }\r\n\r\n  if (respondida) {\r\n    const acertou = acertouChecagem(dados);\r\n    feedbackBar.className     = `feedback-bar show ${acertou ? 'acerto' : 'erro'}`;\r\n    feedbackIcon.textContent  = acertou ? '✅' : '❌';\r\n    const letraCorreta        = (dados.sentenca || dados.sujeito || dados.banco) ? null : LETRAS[dados.correta];\r\n    feedbackTexto.innerHTML   = montarFeedbackHtml(acertou, dados.feedback, letraCorreta);\r\n  } else {\r\n    feedbackBar.className = 'feedback-bar';\r\n  }\r\n\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = !respondida;\r\n  marcarOverflowNasFrasesAnotadas();\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// Checagem \"clique no verbo e no sujeito\" — duas seleções (verbo + sujeito,\r\n// podendo ter mais de uma palavra) antes de confirmar. Não conta como\r\n// respondida até clicar em \"Confirmar resposta\".\r\nconst PONTUACAO_RE = /^[.,!?;:]+$/;\r\n\r\nfunction mostrarChecagemDupla(aula, introIdx, dados, checagemIdx, origemAulaId, respondida) {\r\n  const wrap = document.getElementById('dualSelectWrap');\r\n  const N = dados.sentenca.length;\r\n\r\n  if (!respondida) {\r\n    if (!dados._pendente) dados._pendente = { modo: 'verbo', verboIdx: null, sujeitoIdxs: [] };\r\n    const { modo, verboIdx, sujeitoIdxs } = dados._pendente;\r\n    const podeConfirmar = verboIdx !== null && sujeitoIdxs.length > 0;\r\n\r\n    wrap.innerHTML = `\r\n      <div class=\"modo-toggle\">\r\n        <button type=\"button\" class=\"modo-btn${modo === 'verbo' ? ' ativo-verbo' : ''}\" id=\"modoVerboBtn\">\r\n          <span class=\"modo-dot modo-dot-verbo\"></span> VERBO\r\n        </button>\r\n        <button type=\"button\" class=\"modo-btn${modo === 'sujeito' ? ' ativo-sujeito' : ''}\" id=\"modoSujeitoBtn\">\r\n          <span class=\"modo-dot modo-dot-sujeito\"></span> SUJEITO\r\n        </button>\r\n      </div>\r\n      <div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"fraseAnotada\" style=\"grid-template-columns:repeat(${N},auto)\"></div></div>\r\n      <button type=\"button\" class=\"btn-confirmar-duplo\" id=\"btnConfirmarDuplo\"${podeConfirmar ? '' : ' disabled'}>Confirmar resposta</button>`;\r\n\r\n    const grid = document.getElementById('fraseAnotada');\r\n    dados.sentenca.forEach((palavra, i) => {\r\n      const ehPontuacao = PONTUACAO_RE.test(palavra);\r\n      const btn = document.createElement('button');\r\n      let cls = 'word-chip';\r\n      if (ehPontuacao)                     cls += ' pontuacao';\r\n      else if (i === verboIdx)             cls += ' verbo-pendente';\r\n      else if (sujeitoIdxs.includes(i))    cls += ' sujeito-pendente';\r\n      btn.className = cls;\r\n      btn.textContent = palavra;\r\n      btn.style.gridColumn = String(i + 1);\r\n      btn.style.gridRow = '1';\r\n      if (ehPontuacao) {\r\n        btn.disabled = true;\r\n      } else {\r\n        btn.addEventListener('click', () => {\r\n          const p = dados._pendente;\r\n          if (p.modo === 'verbo') {\r\n            if (p.verboIdx === i) {\r\n              p.verboIdx = null;\r\n            } else {\r\n              p.verboIdx = i;\r\n              p.sujeitoIdxs = p.sujeitoIdxs.filter(x => x !== i);\r\n              p.modo = 'sujeito';\r\n            }\r\n          } else {\r\n            if (i === p.verboIdx) return;\r\n            const idx = p.sujeitoIdxs.indexOf(i);\r\n            if (idx === -1) p.sujeitoIdxs.push(i); else p.sujeitoIdxs.splice(idx, 1);\r\n          }\r\n          mostrarChecagemDupla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n        });\r\n      }\r\n      grid.appendChild(btn);\r\n    });\r\n\r\n    if (verboIdx !== null) anotarPapelInterativo(grid, verboIdx, 'verbo');\r\n    if (sujeitoIdxs.length > 0) anotarPapelInterativo(grid, sujeitoIdxs, 'sujeito');\r\n\r\n    document.getElementById('modoVerboBtn').addEventListener('click', () => {\r\n      dados._pendente.modo = 'verbo';\r\n      mostrarChecagemDupla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    document.getElementById('modoSujeitoBtn').addEventListener('click', () => {\r\n      dados._pendente.modo = 'sujeito';\r\n      mostrarChecagemDupla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    if (podeConfirmar) {\r\n      document.getElementById('btnConfirmarDuplo').addEventListener('click', () => {\r\n        const verboCorreto   = dados._pendente.verboIdx === dados.verbo;\r\n        const sujeitoCorreto = dados._pendente.sujeitoIdxs.length === dados.sujeito.length &&\r\n                                dados.sujeito.every(i => dados._pendente.sujeitoIdxs.includes(i));\r\n        const acertou = verboCorreto && sujeitoCorreto;\r\n        dados._escolhida = { verbo: dados._pendente.verboIdx, sujeito: [...dados._pendente.sujeitoIdxs] };\r\n        dados._correta   = acertou;\r\n        if (!acertou) {\r\n          addErro(origemAulaId, `checagem${checagemIdx}`);\r\n          erroNestaSessao = true;\r\n        }\r\n        mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId);\r\n      });\r\n    }\r\n    marcarOverflowNasFrasesAnotadas();\r\n    return;\r\n  }\r\n\r\n  // Já respondida — mostra o resultado com a chave verbo/sujeito.\r\n  wrap.innerHTML = `<div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"fraseAnotada\" style=\"grid-template-columns:repeat(${N},auto)\"></div></div>`;\r\n  const grid = document.getElementById('fraseAnotada');\r\n  const escolhida = dados._escolhida;\r\n  dados.sentenca.forEach((palavra, i) => {\r\n    const ehPontuacao = PONTUACAO_RE.test(palavra);\r\n    const btn = document.createElement('button');\r\n    let cls = 'word-chip';\r\n    if (ehPontuacao) {\r\n      cls += ' pontuacao';\r\n    } else {\r\n      const ehVerboCorreto   = i === dados.verbo;\r\n      const ehSujeitoCorreto = dados.sujeito.includes(i);\r\n      const foiVerbo         = i === escolhida.verbo;\r\n      const foiSujeito       = escolhida.sujeito.includes(i);\r\n      if      (ehVerboCorreto)                  cls += ' verbo-correto';\r\n      else if (ehSujeitoCorreto)                cls += ' sujeito-correto';\r\n      else if (foiVerbo && !ehVerboCorreto)     cls += ' verbo-errado';\r\n      else if (foiSujeito && !ehSujeitoCorreto) cls += ' sujeito-errado';\r\n    }\r\n    btn.className = cls;\r\n    btn.textContent = palavra;\r\n    btn.disabled = true;\r\n    btn.style.gridColumn = String(i + 1);\r\n    btn.style.gridRow = '1';\r\n    grid.appendChild(btn);\r\n  });\r\n  anotarPapelInterativo(grid, dados.verbo, 'verbo');\r\n  anotarPapelInterativo(grid, dados.sujeito, 'sujeito');\r\n\r\n  const linhas = dados.sentenca.map((palavra, i) => {\r\n    if (PONTUACAO_RE.test(palavra)) return '';\r\n    const ehVerbo   = i === dados.verbo;\r\n    const ehSujeito = dados.sujeito.includes(i);\r\n    const classe    = (ehVerbo || ehSujeito) ? 'correta' : '';\r\n    const papel     = ehVerbo ? 'Verbo' : ehSujeito ? 'Sujeito' : '—';\r\n    return `\r\n      <div class=\"checagem-resultado-item\">\r\n        <span class=\"cri-palavra ${classe}\">${palavra}</span>\r\n        <span class=\"cri-seta\">→</span>\r\n        <span class=\"cri-classe ${classe}\">${papel}</span>\r\n        ${(ehVerbo || ehSujeito) ? '<span class=\"cri-icone\" style=\"color:#16a34a\">✓</span>' : ''}\r\n      </div>`;\r\n  }).join('');\r\n  wrap.insertAdjacentHTML('beforeend', `\r\n    <div class=\"checagem-resultado-itens\">\r\n      <p class=\"checagem-resultado-titulo\">Resposta de cada item:</p>\r\n      <div class=\"checagem-resultado-lista\">${linhas}</div>\r\n    </div>`);\r\n  marcarOverflowNasFrasesAnotadas();\r\n}\r\n\r\n// Checagem \"clique no verbo, no sujeito e no predicado\" — três seleções\r\n// (verbo, sujeito, predicado) em vez das duas do duplo-select. O predicado\r\n// inclui o verbo (seu núcleo): clicar nele de novo, já em modo \"predicado\",\r\n// confirma que ele também faz parte do predicado.\r\nfunction mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, respondida) {\r\n  const wrap = document.getElementById('triSelectWrap');\r\n  const N = dados.sentenca.length;\r\n\r\n  if (!respondida) {\r\n    if (!dados._pendente) {\r\n      dados._pendente = { modo: 'verbo', verboIdx: null, sujeitoIdxs: [], predicadoIdxs: [], predicadoConfirmado: false, semSujeito: false };\r\n    }\r\n    const p = dados._pendente;\r\n    const podeConfirmar = p.verboIdx !== null && (p.sujeitoIdxs.length > 0 || p.semSujeito);\r\n\r\n    wrap.innerHTML = `\r\n      <div class=\"modo-toggle\">\r\n        <button type=\"button\" class=\"modo-btn${p.modo === 'verbo' ? ' ativo-verbo' : ''}\" id=\"modoVerboBtn\">\r\n          <span class=\"modo-dot modo-dot-verbo\"></span> VERBO\r\n        </button>\r\n        <button type=\"button\" class=\"modo-btn${p.modo === 'sujeito' ? ' ativo-sujeito' : ''}\" id=\"modoSujeitoBtn\">\r\n          <span class=\"modo-dot modo-dot-sujeito\"></span> SUJEITO\r\n        </button>\r\n        <button type=\"button\" class=\"modo-btn${p.modo === 'predicado' ? ' ativo-predicado' : ''}\" id=\"modoPredicadoBtn\">\r\n          <span class=\"modo-dot modo-dot-predicado\"></span> PREDICADO\r\n        </button>\r\n      </div>\r\n      <button type=\"button\" class=\"modo-sem-sujeito-btn${p.semSujeito ? ' ativo' : ''}\" id=\"btnSemSujeitoTripla\">\r\n        <span class=\"sem-sujeito-icone\">⊘</span> Oração sem sujeito\r\n      </button>\r\n      <div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"fraseAnotadaTri\" style=\"grid-template-columns:repeat(${N},auto)\"></div></div>\r\n      <button type=\"button\" class=\"btn-confirmar-duplo\" id=\"btnConfirmarTripla\"${podeConfirmar ? '' : ' disabled'}>Confirmar resposta</button>`;\r\n\r\n    const grid = document.getElementById('fraseAnotadaTri');\r\n    dados.sentenca.forEach((palavra, i) => {\r\n      const ehPontuacao = PONTUACAO_RE.test(palavra);\r\n      const btn = document.createElement('button');\r\n      let cls = 'word-chip';\r\n      if (ehPontuacao) {\r\n        cls += ' pontuacao';\r\n      } else if (i === p.verboIdx) {\r\n        cls += (p.modo === 'predicado' && p.predicadoConfirmado) ? ' predicado-pendente' : ' verbo-pendente';\r\n      } else if (p.sujeitoIdxs.includes(i)) {\r\n        cls += ' sujeito-pendente';\r\n      } else if (p.predicadoIdxs.includes(i)) {\r\n        cls += ' predicado-pendente';\r\n      }\r\n      btn.className = cls;\r\n      btn.textContent = palavra;\r\n      btn.style.gridColumn = String(i + 1);\r\n      btn.style.gridRow = '1';\r\n      if (ehPontuacao) {\r\n        btn.disabled = true;\r\n      } else {\r\n        btn.addEventListener('click', () => {\r\n          if (p.modo === 'verbo') {\r\n            if (p.verboIdx === i) {\r\n              p.predicadoIdxs      = [];\r\n              p.predicadoConfirmado = false;\r\n              p.verboIdx = null;\r\n            } else {\r\n              p.sujeitoIdxs         = p.sujeitoIdxs.filter(x => x !== i);\r\n              p.predicadoIdxs       = [];\r\n              p.predicadoConfirmado = false;\r\n              p.verboIdx = i;\r\n              p.modo     = 'sujeito';\r\n            }\r\n          } else if (p.modo === 'sujeito') {\r\n            if (i === p.verboIdx) return;\r\n            p.semSujeito    = false;\r\n            p.predicadoIdxs = p.predicadoIdxs.filter(x => x !== i);\r\n            const idx = p.sujeitoIdxs.indexOf(i);\r\n            if (idx === -1) p.sujeitoIdxs.push(i); else p.sujeitoIdxs.splice(idx, 1);\r\n          } else {\r\n            if (i === p.verboIdx) {\r\n              p.predicadoConfirmado = true;\r\n              if (!p.predicadoIdxs.includes(i)) p.predicadoIdxs.push(i);\r\n            } else {\r\n              if (p.sujeitoIdxs.includes(i)) return;\r\n              const idx = p.predicadoIdxs.indexOf(i);\r\n              if (idx === -1) p.predicadoIdxs.push(i); else p.predicadoIdxs.splice(idx, 1);\r\n            }\r\n          }\r\n          mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n        });\r\n      }\r\n      grid.appendChild(btn);\r\n    });\r\n\r\n    if (p.sujeitoIdxs.length > 0) anotarPapelInterativo(grid, p.sujeitoIdxs, 'sujeito');\r\n    if (p.verboIdx !== null) anotarPapelInterativo(grid, p.verboIdx, 'verbo');\r\n    if ((p.predicadoConfirmado || p.predicadoIdxs.some(i => i !== p.verboIdx)) && p.predicadoIdxs.length > 0) {\r\n      anotarPapelInterativo(grid, p.predicadoIdxs, 'predicado');\r\n    }\r\n\r\n    document.getElementById('modoVerboBtn').addEventListener('click', () => {\r\n      dados._pendente.modo = 'verbo';\r\n      mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    document.getElementById('modoSujeitoBtn').addEventListener('click', () => {\r\n      dados._pendente.modo = 'sujeito';\r\n      mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    document.getElementById('modoPredicadoBtn').addEventListener('click', () => {\r\n      dados._pendente.modo = 'predicado';\r\n      mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    // \"Oração sem sujeito\" — declaração explícita do aluno de que a frase não\r\n    // tem sujeito (necessário pra liberar o \"Confirmar resposta\" nesses casos,\r\n    // já que sem isso não dava pra confirmar sem marcar nenhuma palavra como\r\n    // sujeito). Marcar uma palavra como sujeito desfaz essa declaração.\r\n    document.getElementById('btnSemSujeitoTripla').addEventListener('click', () => {\r\n      p.semSujeito = !p.semSujeito;\r\n      if (p.semSujeito) p.sujeitoIdxs = [];\r\n      mostrarChecagemTripla(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n    });\r\n    if (podeConfirmar) {\r\n      document.getElementById('btnConfirmarTripla').addEventListener('click', () => {\r\n        const verboCorreto     = p.verboIdx === dados.verbo;\r\n        const sujeitoCorreto   = dados.sujeito.length === 0\r\n          ? (p.semSujeito && p.sujeitoIdxs.length === 0)\r\n          : (!p.semSujeito && p.sujeitoIdxs.length === dados.sujeito.length &&\r\n             dados.sujeito.every(i => p.sujeitoIdxs.includes(i)));\r\n        const predicadoCorreto = p.predicadoIdxs.length === dados.predicado.length &&\r\n                                  dados.predicado.every(i => p.predicadoIdxs.includes(i));\r\n        const acertou = verboCorreto && sujeitoCorreto && predicadoCorreto;\r\n        dados._escolhida = { verbo: p.verboIdx, sujeito: [...p.sujeitoIdxs], predicado: [...p.predicadoIdxs], semSujeito: p.semSujeito };\r\n        dados._correta   = acertou;\r\n        if (!acertou) {\r\n          addErro(origemAulaId, `checagem${checagemIdx}`);\r\n          erroNestaSessao = true;\r\n        }\r\n        mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId);\r\n      });\r\n    }\r\n    marcarOverflowNasFrasesAnotadas();\r\n    return;\r\n  }\r\n\r\n  // Já respondida — mostra o resultado com a chave sujeito/verbo/predicado.\r\n  wrap.innerHTML = `<div class=\"frase-anotada-wrap\"><div class=\"frase-anotada\" id=\"fraseAnotadaTri\" style=\"grid-template-columns:repeat(${N},auto)\"></div></div>`;\r\n  const grid = document.getElementById('fraseAnotadaTri');\r\n  const escolhida = dados._escolhida;\r\n  dados.sentenca.forEach((palavra, i) => {\r\n    const ehPontuacao = PONTUACAO_RE.test(palavra);\r\n    const btn = document.createElement('button');\r\n    let cls = 'word-chip';\r\n    if (ehPontuacao) {\r\n      cls += ' pontuacao';\r\n    } else {\r\n      const ehVerboCorreto     = i === dados.verbo;\r\n      const ehSujeitoCorreto   = dados.sujeito.includes(i);\r\n      const ehPredicadoCorreto = dados.predicado.includes(i);\r\n      const foiVerbo           = i === escolhida.verbo;\r\n      const foiSujeito         = escolhida.sujeito.includes(i);\r\n      const foiPredicado       = escolhida.predicado.includes(i);\r\n      if      (ehVerboCorreto)                      cls += ' verbo-correto';\r\n      else if (ehSujeitoCorreto)                    cls += ' sujeito-correto';\r\n      else if (ehPredicadoCorreto)                  cls += ' predicado-correto';\r\n      else if (foiVerbo && !ehVerboCorreto)         cls += ' verbo-errado';\r\n      else if (foiSujeito && !ehSujeitoCorreto)     cls += ' sujeito-errado';\r\n      else if (foiPredicado && !ehPredicadoCorreto) cls += ' predicado-errado';\r\n    }\r\n    btn.className = cls;\r\n    btn.textContent = palavra;\r\n    btn.disabled = true;\r\n    btn.style.gridColumn = String(i + 1);\r\n    btn.style.gridRow = '1';\r\n    grid.appendChild(btn);\r\n  });\r\n\r\n  if (dados.sujeito.length > 0) anotarPapelInterativo(grid, dados.sujeito, 'sujeito');\r\n  anotarPapelInterativo(grid, dados.verbo, 'verbo');\r\n  anotarPapelInterativo(grid, dados.predicado, 'predicado');\r\n\r\n  const linhas = dados.sentenca.map((palavra, i) => {\r\n    if (PONTUACAO_RE.test(palavra)) return '';\r\n    const ehVerbo     = i === dados.verbo;\r\n    const ehSujeito   = dados.sujeito.includes(i);\r\n    const ehPredicado = dados.predicado.includes(i) && !ehVerbo;\r\n    const classe = (ehVerbo || ehSujeito || ehPredicado) ? 'correta' : '';\r\n    const papel  = ehVerbo ? 'Verbo' : ehSujeito ? 'Sujeito' : ehPredicado ? 'Predicado' : '—';\r\n    return `\r\n      <div class=\"checagem-resultado-item\">\r\n        <span class=\"cri-palavra ${classe}\">${palavra}</span>\r\n        <span class=\"cri-seta\">→</span>\r\n        <span class=\"cri-classe ${classe}\">${papel}</span>\r\n        ${(ehVerbo || ehSujeito || ehPredicado) ? '<span class=\"cri-icone\" style=\"color:#16a34a\">✓</span>' : ''}\r\n      </div>`;\r\n  }).join('');\r\n  wrap.insertAdjacentHTML('beforeend', `\r\n    <div class=\"checagem-resultado-itens\">\r\n      <p class=\"checagem-resultado-titulo\">Resposta de cada item:</p>\r\n      <div class=\"checagem-resultado-lista\">${linhas}</div>\r\n    </div>`);\r\n  marcarOverflowNasFrasesAnotadas();\r\n}\r\n\r\n// Checagem \"reescreva na ordem direta\" — a frase original (ordem inversa)\r\n// fica fixa no topo só de referência; embaixo, um banco de palavras\r\n// embaralhadas (dados.banco) que a pessoa clica em ordem pra ir montando a\r\n// resposta numa caixa no meio. dados.ordemCorreta guarda a ordem certa como\r\n// índices em dados.banco (não pelo texto, pra lidar com palavras repetidas).\r\nfunction mostrarChecagemReordenar(aula, introIdx, dados, checagemIdx, origemAulaId, respondida) {\r\n  const wrap = document.getElementById('reordenarWrap');\r\n\r\n  if (!respondida) {\r\n    if (!dados._pendente) dados._pendente = { escolhidos: [] };\r\n    const p = dados._pendente;\r\n    const podeConfirmar = p.escolhidos.length === dados.banco.length;\r\n\r\n    wrap.innerHTML = `\r\n      <div class=\"reordenar-referencia\">\r\n        <p class=\"reordenar-referencia-label\">Frase original:</p>\r\n        <p class=\"reordenar-referencia-texto\">${dados.referencia.join(' ')}</p>\r\n      </div>\r\n      <div class=\"reordenar-resposta\" id=\"reordenarResposta\"></div>\r\n      <div class=\"reordenar-banco\" id=\"reordenarBanco\"></div>\r\n      <button type=\"button\" class=\"btn-confirmar-duplo\" id=\"btnConfirmarReordenar\"${podeConfirmar ? '' : ' disabled'}>Confirmar resposta</button>`;\r\n\r\n    const respostaEl = document.getElementById('reordenarResposta');\r\n    const bancoEl     = document.getElementById('reordenarBanco');\r\n\r\n    p.escolhidos.forEach(bancoIdx => {\r\n      const btn = document.createElement('button');\r\n      btn.type = 'button';\r\n      btn.className = 'word-chip';\r\n      btn.textContent = dados.banco[bancoIdx];\r\n      btn.addEventListener('click', () => {\r\n        p.escolhidos = p.escolhidos.filter(i => i !== bancoIdx);\r\n        mostrarChecagemReordenar(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n      });\r\n      respostaEl.appendChild(btn);\r\n    });\r\n\r\n    dados.banco.forEach((palavra, i) => {\r\n      const jaEscolhida = p.escolhidos.includes(i);\r\n      const btn = document.createElement('button');\r\n      btn.type = 'button';\r\n      btn.className = 'word-chip';\r\n      btn.textContent = palavra;\r\n      btn.disabled = jaEscolhida;\r\n      if (!jaEscolhida) {\r\n        btn.addEventListener('click', () => {\r\n          p.escolhidos.push(i);\r\n          mostrarChecagemReordenar(aula, introIdx, dados, checagemIdx, origemAulaId, false);\r\n        });\r\n      }\r\n      bancoEl.appendChild(btn);\r\n    });\r\n\r\n    if (podeConfirmar) {\r\n      document.getElementById('btnConfirmarReordenar').addEventListener('click', () => {\r\n        const acertou = p.escolhidos.every((idx, pos) => idx === dados.ordemCorreta[pos]);\r\n        dados._escolhida = [...p.escolhidos];\r\n        dados._correta   = acertou;\r\n        if (!acertou) {\r\n          addErro(origemAulaId, `checagem${checagemIdx}`);\r\n          erroNestaSessao = true;\r\n        }\r\n        mostrarChecagem(aula, introIdx, dados, checagemIdx, origemAulaId);\r\n      });\r\n    }\r\n    return;\r\n  }\r\n\r\n  // Já respondida — mostra a resposta dada e, se errou, a ordem certa.\r\n  const acertou = dados._correta === true;\r\n  wrap.innerHTML = `\r\n    <div class=\"reordenar-referencia\">\r\n      <p class=\"reordenar-referencia-label\">Frase original:</p>\r\n      <p class=\"reordenar-referencia-texto\">${dados.referencia.join(' ')}</p>\r\n    </div>\r\n    <p class=\"reordenar-referencia-label\">Sua resposta:</p>\r\n    <div class=\"reordenar-resposta reordenar-resposta-final\">\r\n      ${dados._escolhida.map((bancoIdx, pos) => {\r\n        const certa = dados.ordemCorreta[pos] === bancoIdx;\r\n        return `<span class=\"word-chip ${certa ? 'correta' : 'errada'}\">${dados.banco[bancoIdx]}</span>`;\r\n      }).join('')}\r\n    </div>\r\n    ${!acertou ? `\r\n    <p class=\"reordenar-referencia-label\">Ordem correta:</p>\r\n    <div class=\"reordenar-resposta reordenar-resposta-final\">\r\n      ${dados.ordemCorreta.map(bancoIdx => `<span class=\"word-chip correta\">${dados.banco[bancoIdx]}</span>`).join('')}\r\n    </div>` : ''}`;\r\n}\r\n\r\nfunction mostrarSentido(aula, introIdx) {\r\n  const s = aula.sentido || {};\r\n  questaoInfo.textContent      = aula.titulo;\r\n  feedbackBar.style.display    = 'none';\r\n  btnAnterior.style.display    = '';\r\n  renderIntroSegs(introIdx - 1);\r\n  questaoTitulo.innerHTML      = '';\r\n  questaoSubtitulo.textContent = '';\r\n  opcoesEl.innerHTML = `\r\n    <div class=\"sentido-card\">\r\n      <div class=\"sentido-dica\">\r\n        <span class=\"sentido-dica-icone\">💡</span>\r\n        <p>${s.dica || ''}</p>\r\n      </div>\r\n      ${(s.textos || []).map(t => `<p class=\"sentido-texto\">${t}</p>`).join('')}\r\n      <p class=\"sentido-exemplos-titulo\">${s.exemplos?.titulo || ''}</p>\r\n      <div class=\"sentido-exemplos\">\r\n        ${(s.exemplos?.itens || []).map(item => `\r\n        <div class=\"sentido-item\">\r\n          <div class=\"resumo-icone\" style=\"background:${item.corFundo}\">\r\n            <svg viewBox=\"0 0 24 24\" width=\"26\" height=\"26\">\r\n              ${RESUMO_ICONES[item.tipo] ? RESUMO_ICONES[item.tipo](item.cor) : ''}\r\n            </svg>\r\n          </div>\r\n          <div class=\"sentido-item-texto\">\r\n            <p class=\"sentido-item-frase\">${item.frase}</p>\r\n            <p class=\"sentido-item-cadeia\">${item.cadeia}</p>\r\n          </div>\r\n        </div>`).join('')}\r\n      </div>\r\n    </div>`;\r\n  btnProxima.innerHTML = 'Próximo <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>';\r\n  btnProxima.disabled  = false;\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// ── RENDERIZAR QUESTÃO ───────────────────────────────────────\r\nfunction renderQuestao(aula) {\r\n  const questoes = aula.questoes;\r\n  const q        = questoes[estado.atual];\r\n  const idx      = estado.atual;\r\n  const total    = questoes.length;\r\n\r\n  // Header\r\n  questaoInfo.textContent = `Questão ${idx + 1} de ${total} • ${aula.titulo}`;\r\n\r\n  // Segmentos de progresso\r\n  progressSegs.innerHTML = '';\r\n  questoes.forEach((_, i) => {\r\n    const seg = document.createElement('div');\r\n    seg.className = 'seg';\r\n    if (estado.respostas[i] !== null) seg.classList.add('respondida');\r\n    else if (i === idx)               seg.classList.add('atual');\r\n    progressSegs.appendChild(seg);\r\n  });\r\n\r\n  // Enunciado\r\n  questaoTitulo.textContent = q.titulo;\r\n  questaoSubtitulo.innerHTML = q.subtitulo;\r\n\r\n  // Opções\r\n  opcoesEl.innerHTML = '';\r\n  const respostaDada = estado.respostas[idx];\r\n\r\n  q.opcoes.forEach((texto, i) => {\r\n    const btn = document.createElement('button');\r\n    btn.className = 'opcao';\r\n\r\n    if (respostaDada !== null) {\r\n      btn.disabled = true;\r\n      if (i === q.correta)                              btn.classList.add('correta');\r\n      else if (i === respostaDada && i !== q.correta)   btn.classList.add('errada');\r\n    }\r\n\r\n    btn.innerHTML = `<span class=\"letra\">${LETRAS[i]}</span><span class=\"opcao-texto\">${texto}</span>`;\r\n\r\n    if (respostaDada === null) {\r\n      btn.addEventListener('click', () => {\r\n        responder(i, aula);\r\n      });\r\n    }\r\n    opcoesEl.appendChild(btn);\r\n  });\r\n\r\n  // Feedback\r\n  if (respostaDada !== null) {\r\n    const acertou = respostaDada === q.correta;\r\n    feedbackBar.className     = `feedback-bar show ${acertou ? 'acerto' : 'erro'}`;\r\n    feedbackIcon.textContent  = acertou ? '✅' : '❌';\r\n    feedbackTexto.innerHTML   = montarFeedbackHtml(acertou, q.feedback, LETRAS[q.correta]);\r\n  } else {\r\n    feedbackBar.className = 'feedback-bar';\r\n  }\r\n\r\n  // Botões de navegação\r\n  btnAnterior.disabled = idx === 0;\r\n\r\n  const todasRespondidas = estado.respostas.every(r => r !== null);\r\n  if (idx === total - 1) {\r\n    btnProxima.innerHTML  = 'Concluir ✓';\r\n    btnProxima.disabled   = !todasRespondidas;\r\n  } else {\r\n    btnProxima.innerHTML  = `Próxima <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" width=\"16\" height=\"16\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>`;\r\n    btnProxima.disabled   = respostaDada === null;\r\n  }\r\n  questaoArea.scrollTop = 0;\r\n  atualizarScrollFade();\r\n}\r\n\r\n// ── RESPONDER ────────────────────────────────────────────────\r\nfunction responder(opcaoIdx, aula) {\r\n  if (estado.respostas[estado.atual] !== null) return;\r\n  estado.respostas[estado.atual] = opcaoIdx;\r\n\r\n  // Errou → vai para o caderno de erros e não sai mais de lá, mesmo se acertar depois.\r\n  const q = aula.questoes[estado.atual];\r\n  if (opcaoIdx !== q.correta) {\r\n    addErro(aulaId, estado.origIdx[estado.atual]);\r\n    erroNestaSessao = true;\r\n  }\r\n\r\n  renderQuestao(aula);\r\n}\r\n\r\n// ── REVISÃO (repete só as questões erradas até acertar tudo) ─\r\n// Regra vale para qualquer aula, pois vive aqui no controller genérico,\r\n// não no arquivo de dados de cada aula.\r\nlet aguardandoRevisao   = false;\r\nlet idxsRevisaoPendente = [];\r\nlet aguardandoReinicio  = false;\r\n\r\n// Marca se errou algo nesta visita à aula (mesmo já tendo concluído antes) —\r\n// usado para mandar direto pro Caderno de Erros ao sair, em vez do Início.\r\nlet erroNestaSessao = false;\r\n\r\nfunction mostrarRevisao(idxsErrados) {\r\n  aguardandoRevisao   = true;\r\n  idxsRevisaoPendente = idxsErrados;\r\n  const n = idxsErrados.length;\r\n  document.getElementById('resultadoEmoji').textContent    = '🔄';\r\n  document.getElementById('resultadoTitulo').textContent   = 'Vamos revisar!';\r\n  document.getElementById('resultadoDesc').textContent     = `Você errou ${n} ${n !== 1 ? 'questões' : 'questão'}. Responda de novo até acertar tudo para concluir a aula.`;\r\n  document.getElementById('resultadoEstrelas').textContent = '';\r\n  document.getElementById('resultadoBtnContinuar').textContent = 'Revisar agora';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n}\r\n\r\n// Errou tudo na rodada — a lição inteira não ficou clara, volta pro início\r\n// da aula (telas de introdução) em vez de só repetir as mesmas questões.\r\nfunction mostrarReinicio() {\r\n  aguardandoReinicio = true;\r\n  document.getElementById('resultadoEmoji').textContent    = '📚';\r\n  document.getElementById('resultadoTitulo').textContent   = 'Vamos rever a aula';\r\n  document.getElementById('resultadoDesc').textContent     = 'Você errou todas as questões. Vamos revisar a aula desde o início antes de tentar de novo.';\r\n  document.getElementById('resultadoEstrelas').textContent = '';\r\n  document.getElementById('resultadoBtnContinuar').textContent = 'Rever a aula';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n}\r\n\r\n// ── MESMA REGRA PARA AS CHECAGENS ─────────────────────────────\r\n// Enquanto as questões pontuadas estiverem desativadas, as checagens são\r\n// \"as questões\" da aula — então valem as mesmas regras de revisão/reinício.\r\nlet aguardandoRevisaoChecagem = false;\r\nlet checagemRevisaoPendente   = [];\r\n\r\nfunction mostrarRevisaoChecagem(itens) {\r\n  aguardandoRevisaoChecagem = true;\r\n  checagemRevisaoPendente   = itens;\r\n  const n = itens.length;\r\n  document.getElementById('resultadoEmoji').textContent    = '🔄';\r\n  document.getElementById('resultadoTitulo').textContent   = 'Vamos revisar!';\r\n  document.getElementById('resultadoDesc').textContent     = `Você errou ${n} ${n !== 1 ? 'questões' : 'questão'}. Responda de novo até acertar tudo para concluir a aula.`;\r\n  document.getElementById('resultadoEstrelas').textContent = '';\r\n  document.getElementById('resultadoBtnContinuar').textContent = 'Revisar agora';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n}\r\n\r\n// Se a aula concluída é a última da sua Etapa, a celebração é pelo módulo\r\n// inteiro (não só pela aula) — e o próximo nível é liberado no Início.\r\nfunction infoEtapaDaAula() {\r\n  const etapa = (MODULOS || []).find(m => m.aulas.some(a => a.id === parseInt(aulaId)));\r\n  if (!etapa) return null;\r\n  const ehUltima = etapa.aulas[etapa.aulas.length - 1].id === parseInt(aulaId);\r\n  return { etapa, ehUltima };\r\n}\r\n\r\nfunction mostrarFinalizadoChecagem() {\r\n  // Tentativa do Simulado terminou com 100% de acerto — limpa a semente do\r\n  // sorteio pra próxima vez montar um conjunto novo (ver montarSimulado).\r\n  if (aulaEhSimulado) limparSimuladoSeed();\r\n\r\n  const infoEtapa = infoEtapaDaAula();\r\n  if (infoEtapa && infoEtapa.ehUltima) {\r\n    document.getElementById('resultadoEmoji').textContent    = '🏆';\r\n    document.getElementById('resultadoTitulo').textContent   = 'Parabéns!';\r\n    document.getElementById('resultadoDesc').textContent     = `Você concluiu o módulo \"${infoEtapa.etapa.titulo}\" com 100% de acerto! Um novo nível foi liberado.`;\r\n  } else {\r\n    document.getElementById('resultadoEmoji').textContent    = '🎉';\r\n    document.getElementById('resultadoTitulo').textContent   = 'Excelente!';\r\n    document.getElementById('resultadoDesc').textContent     = 'Você completou a aula com 100% de acerto!';\r\n  }\r\n  document.getElementById('resultadoEstrelas').textContent = '★★★';\r\n  document.getElementById('resultadoBtnContinuar').textContent = 'Voltar ao início';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n  sessionStorage.setItem(`aula${aulaId}_resultado`, JSON.stringify({\r\n    aulaId: parseInt(aulaId), estrelas: 3, acertos: 1, total: 1,\r\n  }));\r\n}\r\n\r\n// Praticando só os erros do caderno de erros (não a aula inteira) —\r\n// termina sem estrelas nem desbloquear a próxima aula.\r\nfunction mostrarPraticaConcluidaChecagem() {\r\n  document.getElementById('resultadoEmoji').textContent    = '📓';\r\n  document.getElementById('resultadoTitulo').textContent   = 'Prática concluída!';\r\n  document.getElementById('resultadoDesc').textContent     = 'Você acertou todas as questões revisadas.';\r\n  document.getElementById('resultadoEstrelas').textContent = '';\r\n  document.getElementById('resultadoBtnContinuar').textContent = 'Voltar ao início';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n}\r\n\r\n// ── RESULTADO ────────────────────────────────────────────────\r\nfunction mostrarResultado(aula) {\r\n  const questoes = aula.questoes;\r\n  const acertos  = estado.respostas.filter((r, i) => r === questoes[i].correta).length;\r\n\r\n  if (modoErros) {\r\n    document.getElementById('resultadoEmoji').textContent   = '📓';\r\n    document.getElementById('resultadoTitulo').textContent  = 'Prática concluída!';\r\n    document.getElementById('resultadoDesc').textContent    = `Você acertou ${acertos} de ${questoes.length} questões revisadas. As questões erradas continuam no caderno de erros para você revisar de novo.`;\r\n    document.getElementById('resultadoEstrelas').textContent = '';\r\n    document.getElementById('resultadoOverlay').classList.add('show');\r\n    return;\r\n  }\r\n\r\n  // Só chega aqui depois de acertar 100% da rodada (a última, após as\r\n  // revisões necessárias) — por isso sempre fecha com as 3 estrelas.\r\n  const total = estado.totalOriginal || questoes.length;\r\n  const infoEtapa = infoEtapaDaAula();\r\n  if (infoEtapa && infoEtapa.ehUltima) {\r\n    document.getElementById('resultadoEmoji').textContent  = '🏆';\r\n    document.getElementById('resultadoTitulo').textContent = 'Parabéns!';\r\n    document.getElementById('resultadoDesc').textContent   = `Você concluiu o módulo \"${infoEtapa.etapa.titulo}\" com 100% de acerto! Um novo nível foi liberado.`;\r\n  } else {\r\n    document.getElementById('resultadoEmoji').textContent  = '🎉';\r\n    document.getElementById('resultadoTitulo').textContent = 'Excelente!';\r\n    document.getElementById('resultadoDesc').textContent   = `Você completou as ${total} questões da aula com 100% de acerto!`;\r\n  }\r\n  document.getElementById('resultadoEstrelas').textContent = '★★★';\r\n  document.getElementById('resultadoOverlay').classList.add('show');\r\n\r\n  // Passa resultado para index.html via sessionStorage\r\n  sessionStorage.setItem(`aula${aulaId}_resultado`, JSON.stringify({\r\n    aulaId:   parseInt(aulaId),\r\n    estrelas: 3,\r\n    acertos:  total,\r\n    total,\r\n  }));\r\n}\r\n\r\n// ── LIÇÃO (modal) ────────────────────────────────────────────\r\nfunction abrirLicao(aula) {\r\n  const el = document.getElementById('licaoHeader');\r\n  if (el) el.textContent = aula.licao.titulo;\r\n  const corpo = document.getElementById('licaoCorpo');\r\n  if (corpo) corpo.innerHTML = aula.licao.html;\r\n  document.getElementById('licaoOverlay').classList.add('show');\r\n}\r\n\r\n// Embaralha uma cópia do array (Fisher-Yates) — não mexe no original. Usa\r\n// `rand` (0-1) como fonte de aleatoriedade; por padrão Math.random(), mas o\r\n// Simulado passa um gerador com semente fixa (ver montarSimulado) pra poder\r\n// repetir o mesmo sorteio entre recarregamentos da mesma tentativa.\r\nfunction embaralhar(lista, rand = Math.random) {\r\n  const copia = [...lista];\r\n  for (let i = copia.length - 1; i > 0; i--) {\r\n    const j = Math.floor(rand() * (i + 1));\r\n    [copia[i], copia[j]] = [copia[j], copia[i]];\r\n  }\r\n  return copia;\r\n}\r\n\r\n// Gerador pseudoaleatório simples e determinístico (mulberry32) — mesma\r\n// semente sempre produz a mesma sequência, ao contrário de Math.random().\r\nfunction criarGeradorComSemente(semente) {\r\n  let a = semente;\r\n  return function() {\r\n    a |= 0; a = (a + 0x6D2B79F5) | 0;\r\n    let t = Math.imul(a ^ (a >>> 15), 1 | a);\r\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\r\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\r\n  };\r\n}\r\n\r\n// Monta a aula sintética do Simulado: carrega todas as aulas dos módulos 1\r\n// a 5, sorteia N itens de checagem de cada módulo (aula.simulado.porModulo)\r\n// e embaralha a ordem final. Cada item é clonado (JSON) pra não compartilhar\r\n// estado (_escolhida/_correta/_pendente) com a aula original — senão\r\n// responder aqui \"sujaria\" o progresso de quem depois faz a aula de verdade.\r\n//\r\n// O sorteio usa uma semente salva no arquivo de progresso (getSimuladoSeed),\r\n// não Math.random() puro: enquanto a tentativa atual não termina (100% de\r\n// acerto), qualquer recarregamento — inclusive abrir o Caderno de Erros —\r\n// tem que sortear o MESMO conjunto/ordem, senão o índice \"checagemN\" salvo\r\n// no caderno passaria a apontar pra uma pergunta diferente a cada vez.\r\nasync function montarSimulado(aulaBase) {\r\n  const qtdPorModulo = (aulaBase.simulado && aulaBase.simulado.porModulo) || 5;\r\n  const etapaIds     = aulaBase.simulado.etapaIds || [];\r\n  const modulosBase  = (MODULOS || []).filter(m => etapaIds.includes(m.id));\r\n  const porAula = {};\r\n  await Promise.all(\r\n    modulosBase.flatMap(m => m.aulas.map(a => a.id))\r\n      .map(async id => { porAula[id] = await carregarAula(id); })\r\n  );\r\n\r\n  let semente = await getSimuladoSeed();\r\n  if (semente == null) {\r\n    semente = Math.floor(Math.random() * 2 ** 31);\r\n    await definirSimuladoSeed(semente);\r\n  }\r\n  const rand = criarGeradorComSemente(semente);\r\n\r\n  let itens = [];\r\n  modulosBase.forEach(modulo => {\r\n    const pool = modulo.aulas.flatMap(a => (porAula[a.id].checagem || []));\r\n    const escolhidos = embaralhar(pool, rand).slice(0, qtdPorModulo).map(d => JSON.parse(JSON.stringify(d)));\r\n    itens = itens.concat(escolhidos);\r\n  });\r\n\r\n  return { ...aulaBase, checagem: embaralhar(itens, rand), questoes: [] };\r\n}\r\n\r\n// ── INIT ─────────────────────────────────────────────────────\r\n// No modo \"Geral\" (Caderno de Erros), carrega TODAS as aulas com checagens\r\n// erradas de uma vez e monta uma aula sintética com os itens já na ordem\r\n// certa (mais recente primeiro) — o resto do controller nem percebe a\r\n// diferença, já que só enxerga um objeto \"aula\" com um array \"checagem\".\r\nasync function carregarDadosIniciais() {\r\n  if (modoErrosGeral) {\r\n    const [notebook, recentes, cartoesMarcados] = await Promise.all([\r\n      getErrorNotebook(), getErrosRecentes(), getCartoesMarcados(),\r\n    ]);\r\n    const aulaIdsComErro = Object.keys(notebook).filter(id =>\r\n      (notebook[id] || []).some(x => typeof x === 'string' && /^checagem\\d+$/.test(x))\r\n    );\r\n    if (aulaIdsComErro.length === 0) {\r\n      window.location.href = 'index.html?view=erros';\r\n      return null;\r\n    }\r\n    const porAula = {};\r\n    await Promise.all(aulaIdsComErro.map(async id => { porAula[id] = await carregarAula(id); }));\r\n\r\n    const mapaQuando = new Map(recentes.map(r => [`${r.aulaId}:${r.chave}`, r.quando]));\r\n    const itens = [];\r\n    aulaIdsComErro.forEach(id => {\r\n      (notebook[id] || [])\r\n        .filter(x => typeof x === 'string' && /^checagem\\d+$/.test(x))\r\n        .forEach(chave => {\r\n          const i     = parseInt(chave.slice('checagem'.length), 10);\r\n          const dados = porAula[id].checagem && porAula[id].checagem[i];\r\n          if (!dados) return;\r\n          itens.push({ aulaId: id, i, dados, quando: mapaQuando.get(`${id}:${chave}`) || null });\r\n        });\r\n    });\r\n    // Mais recente primeiro; erros sem horário conhecido (registrados antes\r\n    // dessa funcionalidade existir) vão pro fim, sem inventar uma ordem.\r\n    itens.sort((a, b) => {\r\n      if (a.quando && b.quando) return new Date(b.quando) - new Date(a.quando);\r\n      return a.quando ? -1 : (b.quando ? 1 : 0);\r\n    });\r\n\r\n    const aulaOriginal = { titulo: 'Caderno de Erros — Geral', checagem: itens.map(it => it.dados), questoes: [] };\r\n    return { aulaOriginal, notebook, cartoesMarcados, itensGeral: itens };\r\n  }\r\n\r\n  const [aulaCarregada, notebook, cartoesMarcados] = await Promise.all([\r\n    carregarAula(aulaId),\r\n    modoErros ? getErrorNotebook() : Promise.resolve(null),\r\n    getCartoesMarcados(),\r\n  ]);\r\n  aulaEhSimulado = !!aulaCarregada.simulado;\r\n  const aulaOriginal = aulaCarregada.simulado ? await montarSimulado(aulaCarregada) : aulaCarregada;\r\n  return { aulaOriginal, notebook, cartoesMarcados, itensGeral: null };\r\n}\r\n\r\ncarregarDadosIniciais().then((carregado) => {\r\n  if (!carregado) return; // modo Geral sem nenhum erro — já redirecionou\r\n  const { aulaOriginal, notebook, cartoesMarcados, itensGeral } = carregado;\r\n  let aula = aulaOriginal;\r\n  let modoErrosChecagem     = false;\r\n  let checagemErrosIniciais = [];\r\n  cartaoMarcadoSet = new Set(cartoesMarcados[String(aulaId)] || []);\r\n\r\n  if (modoErrosGeral) {\r\n    modoErrosChecagem     = true;\r\n    checagemErrosIniciais = itensGeral.map(it => ({ dados: it.dados, i: it.i, aulaId: it.aulaId }));\r\n  } else if (modoErros) {\r\n    const todosErros = notebook[String(aulaId)] || [];\r\n    const errIdxs = todosErros\r\n      .filter(i => Number.isInteger(i) && i >= 0 && aulaOriginal.questoes && i < aulaOriginal.questoes.length)\r\n      .slice().sort((a, b) => a - b);\r\n    // Erros de checagem ficam guardados como \"checagemN\" — extrai o índice.\r\n    const checagemErrIdxs = todosErros\r\n      .filter(x => typeof x === 'string' && /^checagem\\d+$/.test(x))\r\n      .map(x => parseInt(x.slice('checagem'.length), 10))\r\n      .filter(i => aulaOriginal.checagem && i >= 0 && i < aulaOriginal.checagem.length)\r\n      .sort((a, b) => a - b);\r\n\r\n    if (errIdxs.length === 0 && checagemErrIdxs.length === 0) {\r\n      window.location.href = 'index.html?view=erros';\r\n      return;\r\n    }\r\n    if (errIdxs.length === 0) {\r\n      // Só tem erros de checagem — pratica direto só essas, sem passar\r\n      // pela aula inteira (introdução, exemplos etc.).\r\n      aula = { ...aulaOriginal, titulo: `Caderno de Erros — ${aulaOriginal.titulo}` };\r\n      modoErrosChecagem     = true;\r\n      checagemErrosIniciais = checagemErrIdxs.map(i => ({ dados: aulaOriginal.checagem[i], i }));\r\n    } else {\r\n      aula = { ...aulaOriginal, titulo: `Caderno de Erros — ${aulaOriginal.titulo}`, questoes: errIdxs.map(i => aulaOriginal.questoes[i]) };\r\n      estado.origIdx = errIdxs;\r\n    }\r\n  } else if (modoRevisao) {\r\n    aula = { ...aulaOriginal, titulo: `Revisão — ${aulaOriginal.titulo}`, questoes: [] };\r\n  } else {\r\n    if (!QUESTOES_ATIVAS) aula = { ...aula, questoes: [] };\r\n    estado.origIdx = aula.questoes.map((_, i) => i);\r\n    estado.totalOriginal = aula.questoes.length;\r\n  }\r\n\r\n  // Inicializa estado com o número correto de questões\r\n  estado.respostas = new Array(aula.questoes.length).fill(null);\r\n\r\n  // Telas de intro em ordem (dinâmico, baseado nos campos da aula) — puladas\r\n  // no modo caderno de erros. No modo revisão, mostra só as telas marcadas.\r\n  const introScreens = [];\r\n  const introFns = {};\r\n  if (modoRevisao) {\r\n    // \"tipo=telas\" mostra só definição/contexto/exemplo marcados; \"tipo=perguntas\"\r\n    // mostra só checagens marcadas. Sem o parâmetro, mostra tudo (compatibilidade).\r\n    const mostrarTelas     = tipoRevisao !== 'perguntas';\r\n    const mostrarPerguntas = tipoRevisao !== 'telas';\r\n    if (mostrarTelas && cartaoMarcadoSet.has('definicao') && aula.definicao) {\r\n      introScreens.push('definicao');\r\n      introFns.definicao = mostrarDefinicao;\r\n    }\r\n    if (mostrarTelas && cartaoMarcadoSet.has('contexto') && aula.contexto) {\r\n      introScreens.push('contexto');\r\n      introFns.contexto = mostrarContexto;\r\n    }\r\n    if (mostrarTelas) {\r\n      (aula.exemplo || []).forEach((_, i) => {\r\n        const chave = `exemplo${i}`;\r\n        if (cartaoMarcadoSet.has(chave)) {\r\n          introScreens.push(chave);\r\n          introFns[chave] = (a, idx) => mostrarExemplo(a, idx, i);\r\n        }\r\n      });\r\n    }\r\n    if (mostrarPerguntas) {\r\n      (aula.checagem || []).forEach((dados, i) => {\r\n        const chave = `checagem${i}`;\r\n        if (cartaoMarcadoSet.has(chave)) {\r\n          introScreens.push(chave);\r\n          introFns[chave] = (a, idx) => mostrarChecagem(a, idx, dados, i);\r\n        }\r\n      });\r\n    }\r\n    if (introScreens.length === 0) {\r\n      window.location.href = 'index.html?view=erros';\r\n      return;\r\n    }\r\n  } else if (Array.isArray(aula.ordem) && aula.ordem.length > 0) {\r\n    // Sequência customizada (Construtor de Aulas, aba \"Estrutura das telas\") —\r\n    // cada token do array vira uma tela, na ordem exata em que aparece lá.\r\n    // Sem \"ordem\" na aula, cai no comportamento padrão abaixo (compatibilidade\r\n    // com aulas escritas à mão, sem essa propriedade).\r\n    Object.assign(introFns, {\r\n      justificativa: mostrarIntro, infinitivo: mostrarInfinitivo, resumo: mostrarResumo,\r\n      identificacao: mostrarIdentificacao, sentido: mostrarSentido, licao: mostrarLicao,\r\n      definicao: mostrarDefinicao, contexto: mostrarContexto,\r\n    });\r\n    (aula.exemplo || []).forEach((_, i) => { introFns[`exemplo${i}`] = (a, idx) => mostrarExemplo(a, idx, i); });\r\n    (aula.checagem || []).forEach((dados, i) => { introFns[`checagem${i}`] = (a, idx) => mostrarChecagem(a, idx, dados, i); });\r\n    aula.ordem.forEach(token => {\r\n      const chave = token === 'antesComecar' ? 'justificativa' : token;\r\n      if (introFns[chave]) introScreens.push(chave);\r\n    });\r\n  } else {\r\n    introScreens.push('justificativa');\r\n    Object.assign(introFns, { justificativa: mostrarIntro, infinitivo: mostrarInfinitivo, resumo: mostrarResumo, identificacao: mostrarIdentificacao, sentido: mostrarSentido });\r\n    if (aula.infinitivo)    introScreens.push('infinitivo');\r\n    if (aula.identificacao) introScreens.push('identificacao');\r\n    if (aula.sentido)       introScreens.push('sentido');\r\n    if (aula.definicao)     introScreens.push('definicao');\r\n    if (aula.contexto)      introScreens.push('contexto');\r\n    introFns.definicao = mostrarDefinicao;\r\n    introFns.contexto  = mostrarContexto;\r\n    (aula.exemplo || []).forEach((_, i) => {\r\n      const chave = `exemplo${i}`;\r\n      introScreens.push(chave);\r\n      introFns[chave] = (a, idx) => mostrarExemplo(a, idx, i);\r\n    });\r\n    (aula.checagem || []).forEach((dados, i) => {\r\n      const chave = `checagem${i}`;\r\n      introScreens.push(chave);\r\n      introFns[chave] = (a, idx) => mostrarChecagem(a, idx, dados, i);\r\n    });\r\n    // Tela de resumo desativada por enquanto (dados mantidos para uso futuro)\r\n    // if (aula.resumo) introScreens.push('resumo');\r\n  }\r\n  introTotal = introScreens.length - 1;\r\n  let introIdx = 0;\r\n  let introAtiva = !modoErros;\r\n\r\n  // ── Revisão/reinício das checagens (mesma regra das questões) ──\r\n  // Enquanto QUESTOES_ATIVAS estiver desligado, as checagens são \"as\r\n  // questões\" da aula, então repetem-se as erradas até fechar 100% —\r\n  // ou reinicia a aula inteira se todas saírem erradas.\r\n  let revisandoChecagem = false;\r\n  let checagemFila       = [];\r\n  let checagemPos        = 0;\r\n  let introTotalSalvo    = 0;\r\n\r\n  function itensChecagemErrados(itens) {\r\n    return itens.filter(({ dados }) => !acertouChecagem(dados));\r\n  }\r\n\r\n  function avaliarChecagens(itens) {\r\n    const erradas = itensChecagemErrados(itens);\r\n    // No modo \"Geral\" não existe uma única aula pra \"rever desde o início\"\r\n    // — mesmo errando tudo, só continua repetindo os itens errados.\r\n    if (!modoErrosGeral && erradas.length > 0 && erradas.length === itens.length) {\r\n      mostrarReinicio();\r\n    } else if (erradas.length > 0) {\r\n      mostrarRevisaoChecagem(erradas);\r\n    } else if (modoErros) {\r\n      // Só terminou de praticar os erros do caderno — não é a aula\r\n      // completa, então não dá estrelas nem desbloqueia a próxima.\r\n      mostrarPraticaConcluidaChecagem();\r\n    } else if (aula.questoes.length === 0) {\r\n      mostrarFinalizadoChecagem();\r\n    } else {\r\n      introAtiva = false;\r\n      sairIntro();\r\n      renderQuestao(aula);\r\n    }\r\n  }\r\n\r\n  function finalizarChecagens() {\r\n    avaliarChecagens((aula.checagem || []).map((dados, i) => ({ dados, i })));\r\n  }\r\n\r\n  function mostrarChecagemRevisaoAtual() {\r\n    const { dados, i, aulaId: origemAulaId } = checagemFila[checagemPos];\r\n    mostrarChecagem(aula, checagemPos, dados, i, origemAulaId || aulaId);\r\n    btnAnterior.disabled = checagemPos === 0;\r\n  }\r\n\r\n  function iniciarRevisaoChecagem(itens) {\r\n    revisandoChecagem = true;\r\n    checagemFila       = itens;\r\n    checagemPos        = 0;\r\n    checagemFila.forEach(({ dados }) => { delete dados._escolhida; delete dados._correta; delete dados._pendente; });\r\n    introTotalSalvo = introTotal;\r\n    introTotal      = checagemFila.length;\r\n    mostrarChecagemRevisaoAtual();\r\n  }\r\n\r\n  function finalizarRevisaoChecagem() {\r\n    revisandoChecagem = false;\r\n    introTotal = introTotalSalvo;\r\n    avaliarChecagens(checagemFila);\r\n  }\r\n\r\n  if (modoErrosChecagem) {\r\n    iniciarRevisaoChecagem(checagemErrosIniciais);\r\n  } else if (introAtiva) {\r\n    introFns[introScreens[0]](aula, 0);\r\n    btnAnterior.style.display = 'none'; // nunca mostra \"Anterior\" na 1ª tela\r\n  } else {\r\n    sairIntro();\r\n    renderQuestao(aula);\r\n  }\r\n\r\n  // Navegação\r\n  btnAnterior.addEventListener('click', () => {\r\n    if (revisandoChecagem) {\r\n      if (checagemPos > 0) { checagemPos--; mostrarChecagemRevisaoAtual(); }\r\n      return;\r\n    }\r\n    if (introAtiva) {\r\n      if (introIdx > 0) {\r\n        introIdx--;\r\n        introFns[introScreens[introIdx]](aula, introIdx);\r\n      }\r\n      return;\r\n    }\r\n    if (estado.atual > 0) { estado.atual--; renderQuestao(aula); }\r\n  });\r\n\r\n  btnProxima.addEventListener('click', () => {\r\n    if (revisandoChecagem) {\r\n      checagemPos++;\r\n      if (checagemPos < checagemFila.length) {\r\n        mostrarChecagemRevisaoAtual();\r\n      } else {\r\n        finalizarRevisaoChecagem();\r\n      }\r\n      return;\r\n    }\r\n    if (introAtiva) {\r\n      introIdx++;\r\n      if (introIdx < introScreens.length) {\r\n        introFns[introScreens[introIdx]](aula, introIdx);\r\n      } else if (modoRevisao) {\r\n        window.location.href = 'index.html?view=erros';\r\n      } else {\r\n        finalizarChecagens();\r\n      }\r\n      return;\r\n    }\r\n    if (estado.atual < aula.questoes.length - 1) {\r\n      estado.atual++;\r\n      renderQuestao(aula);\r\n      return;\r\n    }\r\n    if (modoErros) {\r\n      mostrarResultado(aula);\r\n      return;\r\n    }\r\n    // Fim da rodada — se errou alguma, repete só as erradas até fechar 100%.\r\n    // Se errou todas, a aula inteira não ficou clara: volta pro começo dela.\r\n    const idxsErrados = aula.questoes\r\n      .map((q, i) => (estado.respostas[i] !== q.correta ? estado.origIdx[i] : null))\r\n      .filter(i => i !== null);\r\n    if (idxsErrados.length === aula.questoes.length) {\r\n      mostrarReinicio();\r\n    } else if (idxsErrados.length > 0) {\r\n      mostrarRevisao(idxsErrados);\r\n    } else {\r\n      mostrarResultado(aula);\r\n    }\r\n  });\r\n\r\n  // Fechar lição\r\n  document.getElementById('licaoFechar').addEventListener('click',    () => document.getElementById('licaoOverlay').classList.remove('show'));\r\n  document.getElementById('licaoBtnFechar').addEventListener('click', () => document.getElementById('licaoOverlay').classList.remove('show'));\r\n\r\n  // Fechar antes de terminar — se errou algo nesta visita, manda direto pro\r\n  // Caderno de Erros em vez do Início, pra não perder de vista o que rever.\r\n  // Terminar a aula de verdade (loop de revisão já fechou com 100%) sempre\r\n  // volta pro Início — só a prática vinda do Caderno (modoErros) retorna\r\n  // pra lá, pra continuar revisando outras questões erradas.\r\n  const destinoVoltarCedo = () => (modoErros || erroNestaSessao) ? 'index.html?view=erros' : 'index.html';\r\n  const destinoVoltarFinal = () => modoErros ? 'index.html?view=erros' : 'index.html';\r\n  document.getElementById('btnFechar').addEventListener('click', () => {\r\n    window.location.href = destinoVoltarCedo();\r\n  });\r\n\r\n  // Voltar ao início após resultado — ou começar a rodada de revisão/reinício\r\n  document.getElementById('resultadoBtnContinuar').addEventListener('click', () => {\r\n    if (aguardandoReinicio) {\r\n      // Recarrega a aula do zero (telas de introdução, checagens, tudo).\r\n      window.location.href = `estudo.html?aula=${aulaId}`;\r\n      return;\r\n    }\r\n    if (aguardandoRevisao) {\r\n      aguardandoRevisao = false;\r\n      document.getElementById('resultadoOverlay').classList.remove('show');\r\n      document.getElementById('resultadoBtnContinuar').textContent = 'Voltar ao início';\r\n      aula = { ...aulaOriginal, questoes: idxsRevisaoPendente.map(i => aulaOriginal.questoes[i]) };\r\n      estado.origIdx   = idxsRevisaoPendente;\r\n      estado.atual     = 0;\r\n      estado.respostas = new Array(aula.questoes.length).fill(null);\r\n      renderQuestao(aula);\r\n      return;\r\n    }\r\n    if (aguardandoRevisaoChecagem) {\r\n      aguardandoRevisaoChecagem = false;\r\n      document.getElementById('resultadoOverlay').classList.remove('show');\r\n      document.getElementById('resultadoBtnContinuar').textContent = 'Voltar ao início';\r\n      iniciarRevisaoChecagem(checagemRevisaoPendente);\r\n      return;\r\n    }\r\n    window.location.href = destinoVoltarFinal();\r\n  });\r\n\r\n}).catch(err => {\r\n  console.error(err);\r\n  document.getElementById('questaoTitulo').textContent = 'Aula não encontrada.';\r\n});\r\n",
};
